local config = {
  ui_story_5084_50840100_1_dialog_content = "這裡是……墓穴？",
  ui_story_5084_50840100_2_dialog_content = "「瓦拉吉，妳的命運已然揭示。但妳的內心，還在猶豫。」",
  ui_story_5084_50840100_3_dialog_content = "我明白力量的代價是成為其俘虜，惶惶不可終日。",
  ui_story_5084_50840100_4_dialog_content = "我不想像我父母那樣，強大卻痛苦，直到最後一滴瓦拉吉的血液流乾才能安息。",
  ui_story_5084_50840100_5_dialog_content = "「妳不是瓦拉吉的信徒。妳和我一樣，只信奉真理之主。」",
  ui_story_5084_50840100_6_dialog_content = "「妳已遊歷此世，壯大勢力。妳是真理的信徒。」",
  ui_story_5084_50840100_7_dialog_content = "「祈願真理之主的降世，妳又何懼犧牲？」",
  ui_story_5084_50840100_8_dialog_content = "你要我怎麼做？",
  ui_story_5084_50840100_9_dialog_content = "「幫我找回力量與身體。作為交換，我將抽取妳的力量，讓妳早日沉眠。」",
  ui_story_5084_50840100_10_dialog_content = "「我喜歡品嚐危險的東西。」",
  ui_story_5084_50840100_11_dialog_content = "「在那其中，透露著真理的味道。」",
  ui_story_5084_50840100_12_dialog_content = "維多利亞大人，您看到了什麼？",
  ui_story_5084_50840100_13_dialog_content = "與邪典簽訂契約之時。彼時，它並未預示這枚戒指的未來。",
  ui_story_5084_50840100_14_dialog_content = "如今這枚戒指居然回到我手上。還未看見它，我就感到一股古老力量的召喚。",
  ui_story_5084_50840100_15_dialog_content = "握住戒指時，那種熟悉的刺痛感……",
  ui_story_5084_50840100_16_dialog_content = "這枚戒指與您有關？",
  ui_story_5084_50840100_17_dialog_content = "這枚戒指是瓦拉吉祖先的遺物，歸真理結社歷任領袖所有。",
  ui_story_5084_50840100_18_dialog_content = "物歸原主，這是值得慶賀的圓滿。",
  ui_story_5084_50840100_19_dialog_content = "重要的不是戒指本身，而是它出現的時間。",
  ui_story_5084_50840100_20_dialog_content = "這枚早已下落不明的戒指，竟在聖鳴節前夕回到我的手中。",
  ui_story_5084_50840100_21_dialog_content = "......！",
  ui_story_5084_50840100_22_dialog_content = "維多利亞大人！",
  ui_story_5084_50840100_23_dialog_content = "哈哈哈哈，瓦拉吉！",
  ui_story_5084_50840100_24_dialog_content = "你！唔、唔！",
  ui_story_5084_50840100_25_dialog_content = "呃啊啊啊——！",
  ui_story_5084_50840100_26_dialog_content = "維多利亞大人！",
  ui_story_5084_50840100_27_dialog_content = "剛才那是……",
  ui_story_5084_50840100_28_dialog_content = "曾經發生的事……又像「未來」的預言……",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>嘩啦啦——！</color>",
  ui_story_5084_50840100_30_dialog_content = "「變革之人，獲得邀請。」",
  ui_story_5084_50840100_31_dialog_content = "「星空墓穴，等待造訪。」",
  ui_story_5084_50840100_32_dialog_content = "「真理之悟，尚待驗證。」",
  ui_story_5084_50840100_33_dialog_content = "「盛典，逢舊月。」",
  ui_story_5084_50840100_34_dialog_content = "「到來，值此刻。」",
  ui_story_5084_50840100_35_dialog_content = "……",
  ui_story_5084_50840100_36_dialog_content = "維多利亞大人，這次的啟示似乎不太明確？",
  ui_story_5084_50840100_37_dialog_content = "結合戒指對過去的預言，這啟示非常明確。",
  ui_story_5084_50840100_38_dialog_content = "「時間已到，聖鳴節會有意想不到的際遇。」",
  ui_story_5084_50840100_39_dialog_content = "「如果想驗證對真理的體悟，就需造訪星空墓穴的守護者。」",
  ui_story_5084_50840100_40_dialog_content = "「這次行動，需要帶上空裔。」",
  ui_story_5084_50840100_41_dialog_content = "這還是血色邪典第一次用幾乎倒裝的語句來預言行動。",
  ui_story_5084_50840100_42_dialog_content = "看來這枚消失已久的戒指，帶來的啟示將會連接起一些未曾見證的時日。",
  ui_story_5084_50840100_43_dialog_content = "您這麼一說，我能夠理解了。",
  ui_story_5084_50840100_44_dialog_content = "那「鮮活的血液」，就由你去指引吧。",
  ui_story_5084_50840100_45_dialog_content = "沒問題，維多利亞大人。",
  ui_story_5084_50840100_46_dialog_content = "雖然你解釋了一路，我還是聽不懂。真理結社的慶典活動，為什麼要找我去？",
  ui_story_5084_50840100_47_dialog_content = "謹遵真理之主與維多利亞大人的指示。",
  ui_story_5084_50840100_48_dialog_content = "唉，你們真理結社真是……",
  ui_story_5084_50840100_49_dialog_content = "我們已經離影鎮很遠了，這是哪裡啊？",
  ui_story_5084_50840100_50_dialog_content = "哇嗚——",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_5084_50840100_52_dialog_content = "這黑呼呼的東西怎麼會動啊？！",
  ui_story_5084_50840100_53_dialog_content = "原來是小白你在打擾我睡覺啊。",
  ui_story_5084_50840100_54_dialog_content = "希卡蕾？",
  ui_story_5084_50840100_55_dialog_content = "把我絆倒的東西，原來是妳伸出來的藤蔓？",
  ui_story_5084_50840100_56_dialog_content = "踩到別人應該道歉才對，怎麼還質問起來了。",
  ui_story_5084_50840100_57_dialog_content = "對、對不起。不過，妳怎麼會在這啊？",
  ui_story_5084_50840100_58_dialog_content = "這話應該我問你們才對吧。到這來有什麼事嗎？",
  ui_story_5084_50840100_59_dialog_content = "都是我的錯。打從今天一早，我就知道今天會犯下不可饒恕的錯誤。",
  ui_story_5084_50840100_60_dialog_content = "如果希卡蕾小姐允許，我想在這裡懺悔。",
  ui_story_5084_50840100_61_dialog_content = "大家都到齊了，維多利亞大人。",
  ui_story_5084_50840100_62_dialog_content = "維多利亞小姐。",
  ui_story_5084_50840100_63_dialog_content = "此前妳說過，時候未到，星空墓穴內藏的祕密連我都無法窺探。",
  ui_story_5084_50840100_64_dialog_content = "如今，邪典啟示我到此地拜訪。",
  ui_story_5084_50840100_65_dialog_content = "能否請教，您這次得到了什麼遺物？",
  ui_story_5084_50840100_66_dialog_content = "這個。",
  ui_story_5084_50840100_67_dialog_content = "如果啟示如此，那麼您確實有權利進入星空墓穴一探究竟。",
  ui_story_5084_50840100_68_dialog_content = "星空墓穴是什麼地方？",
  ui_story_5084_50840100_69_dialog_content = "用俗話說，就是埋死人的地方。",
  ui_story_5084_50840100_70_dialog_content = "死……！浮士德明明說，是為了即將到來的真理結社慶典！",
  ui_story_5084_50840100_71_dialog_content = "「即將到來的」慶典，所以這是必經之路。",
  ui_story_5084_50840100_72_dialog_content = "不用緊張，裡頭的東西據說比白夜城所有財富加起來都要值錢。",
  ui_story_5084_50840100_73_dialog_content = "有無數人想一窺墓穴中的祕密，最終都葬身於此。這麼說來，你反而很幸運。",
  ui_story_5084_50840100_74_dialog_content = "就算是財寶！就算……！是、是財寶的話，我倒是可以認真考慮啦。",
  ui_story_5084_50840100_75_dialog_content = "關於星空墓穴，我有三點提醒要給予進入之人。",
  ui_story_5084_50840100_76_dialog_content = "第一點，鮮血是法利亞識別進入者的唯一方式。訂下血契之人，方可進入墓穴。",
  ui_story_5084_50840100_77_dialog_content = "而法利亞打開的另一扇門，會聽從契約之人的指引。",
  ui_story_5084_50840100_78_dialog_content = "這就是「法利亞」。",
  ui_story_5084_50840100_79_dialog_content = "第二點，隨身之物將同樣受到指引。這些物品屬時間所有，將順應時間各自歸位。",
  ui_story_5084_50840100_80_dialog_content = "第三點，命運早已銘刻。不容質疑，不容憎惡，不容改變。",
  ui_story_5084_50840100_81_dialog_content = "看起來，小白似乎有很多疑問？",
  ui_story_5084_50840100_82_option_content = "血契？",
  ui_story_5084_50840100_83_dialog_content = "是要流血的意思嗎？",
  ui_story_5084_50840100_84_dialog_content = "偉大的主，若您不棄，請將我這骯髒的血液全部拿走。",
  ui_story_5084_50840100_85_option_content = "「命運不容質疑」？",
  ui_story_5084_50840100_86_dialog_content = "聽妳這樣說，好像是某些小說裡寫的「穿越」回到過去？",
  ui_story_5084_50840100_87_dialog_content = "剛才還一副擔心的樣子，馬上就換上期待的表情了啊。",
  ui_story_5084_50840100_88_dialog_content = "法利亞，準備開啟。",
  ui_story_5084_50840100_89_dialog_content = "等等！可是我是空裔，我的血也可以嗎？",
  ui_story_5084_50840100_90_dialog_content = "嘿——！",
  ui_story_5084_50840100_91_dialog_content = "<size=45>哇啊！！！</size>",
  ui_story_5084_50840100_92_dialog_content = "剛才希卡蕾姐姐說法利亞要打開了，你沒聽到嗎？",
  ui_story_5084_50840100_93_dialog_content = "維多利亞大人，請帶梅和寶寶一起去吧！我們一定會乖乖聽話。",
  ui_story_5084_50840100_94_dialog_content = "妳獨自跑到這裡，蓮知道嗎？",
  ui_story_5084_50840100_95_dialog_content = "她知道！蓮說「梅要玩得開心一點唷」！",
  ui_story_5084_50840100_96_dialog_content = "我這裡存了很多寶寶的線，任何傷口都可以縫起來！",
  ui_story_5084_50840100_97_dialog_content = "PlayerName快過來，接下來就由我照顧你吧。",
  ui_story_5084_50840100_98_dialog_content = "喵～",
  ui_story_5084_50840100_99_dialog_content = "我還是離妳遠一點比較安全……",
  ui_story_5084_50840100_100_dialog_content = "既然大家都準備好了，法利亞，開啟！",
  ui_story_5084_50840100_101_dialog_content = "願真理之主，引我探得那疑問的盡頭。",
  ui_story_5084_50840100_102_dialog_content = "願真理之主，祝福我們的旅程順利。",
  ui_story_5084_50840100_103_dialog_content = "願真理之主，懲罰我的罪孽。",
  ui_story_5084_50840100_104_dialog_content = "願真理之主，帶小梅去好玩的地方。",
  ui_story_5084_50840100_105_dialog_content = "就算妳拉著我的衣角，我也……",
  ui_story_5084_50840100_106_dialog_content = "唔......！",
  ui_story_5084_50840100_107_dialog_content = "希卡蕾、希卡蕾……",
  ui_story_5084_50840100_108_dialog_content = "救救我！",
  ui_story_5084_50840100_109_dialog_content = "小白，你閉著眼一副很痛苦的樣子是在？",
  ui_story_5084_50840100_110_dialog_content = "把眼睛睜開吧，根本就沒有危險。",
  ui_story_5084_50840100_111_dialog_content = "但剛剛那密密麻麻的藤蔓，騷得我又癢又怕。",
  ui_story_5084_50840100_112_dialog_content = "你難道不想探究真理嗎？喔，差點忘了小白你還沒有加入真理結社了。",
  ui_story_5084_50840100_113_dialog_content = "……希卡蕾還真是什麼都不在乎啊。",
  ui_story_5084_50840100_114_dialog_content = "話說回來，他們還真的一轉眼就不見了？",
  ui_story_5084_50840100_115_dialog_content = "你還在，這才是問題。",
  ui_story_5084_50840100_116_dialog_content = "你一定聽過這樣一句話吧：「要接近真理，就必須停下思緒，任憑感官馳騁探索。」",
  ui_story_5084_50840100_117_dialog_content = "你是空裔，應該很擅長才對。",
  ui_story_5084_50840100_118_dialog_content = "你在哪裡？你是誰？你要去往何方？",
  ui_story_5084_50840100_119_dialog_content = "太深奧了啦，我只是因為浮士德說有難得一見的節日慶典才來的。",
  ui_story_5084_50840100_120_dialog_content = "那就想著慶典。若還是害怕，你可以在藤蔓之中摸索到一個燭台。",
  ui_story_5084_50840100_121_dialog_content = "燭台……",
  ui_story_5084_50840100_122_dialog_content = "好、好像真的有？",
  ui_story_5084_50840100_123_dialog_content = "燭台將指引你。但是切莫貪玩，燭台燃盡之前，記得回來。",
  ui_story_5084_50840100_124_dialog_content = "回、回來？怎麼回來？回哪裡來啊？",
  ui_story_5084_50840100_125_dialog_content = "希卡蕾？",
  ui_story_5084_50840100_126_dialog_content = "希卡蕾！",
  ui_story_5084_50840201_1_dialog_content = "（還好希卡蕾給了我一個燭台，否則這裡未免也太黑了。）",
  ui_story_5084_50840201_2_dialog_content = "（不知道要去哪裡找大家……）",
  ui_story_5084_50840201_3_dialog_content = "這裡是哪裡？",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>一輪血月鑲於夜幕之中。古老鐘聲敲響，一座座高聳的鐘樓瞬間拔地而起，聳向血月。</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>月光照耀著信徒踩過的每一塊石頭，照耀著雕花精緻的門牆。</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>傾聽著真理殿堂傳出的懺悔，也講述著血之一族的榮耀與祕密。</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>咚！咚！</color>",
  ui_story_5084_50840201_8_dialog_content = "這地面是真的，牆壁也是！好神奇！",
  ui_story_5084_50840201_9_dialog_content = "該不會也跟「真實之館」一樣，沒有來到這裡的人，就不會發覺這裡發生的一切吧？",
  ui_story_5084_50840201_10_dialog_content = "啊，血月出現了！三年一度的聖鳴節遊行儀式，馬上就要開始了。",
  ui_story_5084_50840201_11_dialog_content = "我準備好禱言了。遊行的時候，我會全心全意地唸誦給真理之主聽。",
  ui_story_5084_50840201_12_dialog_content = "只是在遊行中唸誦可不夠，你還得獲選為「受召者」才行。唯有獻祭自身，真理之主才能聽見並回應你。",
  ui_story_5084_50840201_13_dialog_content = "瓦拉吉鎮？這裡就是真理結社舉辦盛典的地方吧。聖鳴節、遊行……",
  ui_story_5084_50840201_14_dialog_content = "我是怎麼來的？大家都到哪裡去了……",
  ui_story_5084_50840201_15_dialog_content = "第一，讀書、學習、交流。真理結社有許多知識淵博的哥哥姐姐，可以教你們一輩子都學不完的知識。",
  ui_story_5084_50840201_16_dialog_content = "第二，吃飯、聚會、讚美真理之主。",
  ui_story_5084_50840201_17_dialog_content = "大家常問的「真理是什麼」，你們一定會在日復一日的聚會中想通。",
  ui_story_5084_50840201_18_dialog_content = "第三，挖掘、探險。只要有天賦，一定能發掘到備受眾人欣羨的寶物。",
  ui_story_5084_50840201_19_dialog_content = "但如果只是喜歡探險，就像我過去一樣，加入真理結社也是你們的不二選擇。",
  ui_story_5084_50840201_20_dialog_content = "自從加入真理結社後，我家寶寶的毛越來越有光澤了。",
  ui_story_5084_50840201_21_dialog_content = "我也很快獲得了維多利亞大人的認可。她常常把重要的工作交給我獨自完成。",
  ui_story_5084_50840201_22_dialog_content = "怎麼樣，迫不及待想加入真理結社了吧？",
  ui_story_5084_50840201_23_dialog_content = "喵～",
  ui_story_5084_50840201_24_dialog_content = "還真夠自信的。",
  ui_story_5084_50840201_25_dialog_content = "小妹妹，把衣服穿好再來可以嗎？",
  ui_story_5084_50840201_26_dialog_content = "妳說的那位「維多利亞大人」，是瓦拉吉家的千金吧？她真的會讓你這樣的小屁孩幫忙做事嗎？",
  ui_story_5084_50840201_27_dialog_content = "還有，妳是第一次來瓦拉吉鎮吧？",
  ui_story_5084_50840201_28_dialog_content = "不如換妳來聽我講述真理結社的起源、教義，以及沉睡在墓穴裡的祕密……",
  ui_story_5084_50840201_29_dialog_content = "妳、妳們都是真理結社的前輩？！但我怎麼覺得，和我認識的夥伴們不一樣？",
  ui_story_5084_50840201_30_dialog_content = "梅……",
  ui_story_5084_50840201_31_dialog_content = "PlayerName，幹嘛拉我？那兩人只差一點點就要加入我們了。",
  ui_story_5084_50840201_32_dialog_content = "先不說她們一點要加入的意思都沒有……",
  ui_story_5084_50840201_33_dialog_content = "難道妳沒聽到滿街的人都在談論遊行、聖鳴節嗎？我們來到維多利亞的故鄉，瓦拉吉鎮了！",
  ui_story_5084_50840201_34_dialog_content = "維多利亞大人的故鄉？好像有聽過。怎麼了？",
  ui_story_5084_50840201_35_dialog_content = "妳難道都不驚訝？不好奇其他人都去哪了嗎？",
  ui_story_5084_50840201_36_dialog_content = "啊哈哈，我知道了！要參加慶典，大家都得準備一套衣服！",
  ui_story_5084_50840201_37_dialog_content = "我們去問問看他們的衣服是在哪家店買的，我們也去買衣服！",
  ui_story_5084_50840201_38_dialog_content = "竟然這麼有興致？這裡比起商店，總覺得會出現什麼陰森裁縫鋪的樣子。",
  ui_story_5084_50840201_39_dialog_content = "咦？梅？",
  ui_story_5084_50840201_40_dialog_content = "你聽，遊行隊伍來啦！快抓緊我的手，不要走丟囉。",
  ui_story_5084_50840201_41_dialog_content = "聽說那口棺槨裡躺著瓦拉吉的先祖，那可是真理之主親自欽選的人喔！",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>在血月的見證下，一隊身著華麗罩袍的人緩緩行進，肩扛著一具尊貴且歷史悠久的棺木。</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>棺中之人正是瓦拉吉的「祖先」，懷抱神聖的典籍，與血月共同散播著真理。</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>信徒們敬畏地尾隨著，凝視棺木，不敢稍作眨眼。</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>隊伍穿越城鎮的大街小巷，直至抵達真理殿堂的宏偉大門前。</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>哐叩。</color>",
  ui_story_5084_50840201_47_dialog_content = "遊行儀式結束，真理已至。",
  ui_story_5084_50840201_48_dialog_content = "各位信徒已經接近主，完成了對主的交付。",
  ui_story_5084_50840201_49_dialog_content = "感謝真理之主！",
  ui_story_5084_50840201_50_dialog_content = "我願一生獻於真理之主！",
  ui_story_5084_50840201_51_dialog_content = "接下來......",
  ui_story_5084_50840201_52_dialog_content = "在場將有一位信徒獲得神聖選召，步入那充滿無窮啟示的虛空之棺，傾聽真理之聲。",
  ui_story_5084_50840201_53_dialog_content = "汝之洞察力卓越非凡，能在幽暗之地洞悉歷史謎團。",
  ui_story_5084_50840201_54_dialog_content = "汝不僅是行道者，更是真理結社集體智慧的體現。",
  ui_story_5084_50840201_55_dialog_content = "汝所經歷的一切，將引領真理結社踏上正途。",
  ui_story_5084_50840201_56_dialog_content = "汝將沉浸於虛無的河流。時空的界限將在汝身邊消融於無形。",
  ui_story_5084_50840201_57_dialog_content = "唯有真理之主降臨，洗滌自我，汝方能蛻變，直至剩下最純淨的本質。",
  ui_story_5084_50840201_58_dialog_content = "真理、聆聽、啟示、覺醒。",
  ui_story_5084_50840201_59_dialog_content = "屆時，汝便完成與神聖的共鳴。",
  ui_story_5084_50840201_60_dialog_content = "威廉大人，請看看我！",
  ui_story_5084_50840201_61_dialog_content = "我想聆聽更多真理！",
  ui_story_5084_50840201_62_dialog_content = "我想聆聽更多真理！",
  ui_story_5084_50840201_63_dialog_content = "噓！",
  ui_story_5084_50840201_64_dialog_content = "我們好不容易才混進來，小聲一點啦……",
  ui_story_5084_50840201_65_dialog_content = "可是梅要聆聽更多真理，才能成為真理結社的核心成員！這是大好機會啊！寶寶快去！",
  ui_story_5084_50840201_66_dialog_content = "「命運早已銘刻。不容質疑，不容憎惡，不容改變。」",
  ui_story_5084_50840201_67_dialog_content = "喵……？",
  ui_story_5084_50840201_68_dialog_content = "這是希卡蕾的囑咐，妳忘了嗎，梅？",
  ui_story_5084_50840201_69_dialog_content = "維、維多利亞大人？！",
  ui_story_5084_50840201_70_dialog_content = "咦？竟然穿著這套衣服？",
  ui_story_5084_50840201_71_dialog_content = "我才想問你們，這副模樣是怎麼進入這裡的？",
  ui_story_5084_50840201_72_dialog_content = "是梅抓著我一路跟著信徒擠進來的。",
  ui_story_5084_50840201_73_dialog_content = "你們已經知道這是哪裡了？",
  ui_story_5084_50840201_74_dialog_content = "聽信徒的議論，這裡是妳的家鄉瓦拉吉鎮。不過，我們該不會……",
  ui_story_5084_50840201_75_dialog_content = "這是過去。",
  ui_story_5084_50840201_76_dialog_content = "過去？",
  ui_story_5084_50840201_77_dialog_content = "當時的我還沒有加入真理結社，而是為了獲得真理，在世界各地遊歷。",
  ui_story_5084_50840201_78_dialog_content = "今年應是一九一五年。本次聖鳴節後，那位真理結社的領袖便失蹤了。",
  ui_story_5084_50840201_79_dialog_content = "他去哪裡了？",
  ui_story_5084_50840201_80_dialog_content = "真理之主透過那枚戒指引我來此。果然如希卡蕾所說，物品屬於時間，時間使物品歸位。",
  ui_story_5084_50840201_81_dialog_content = "此時邪典回歸先祖懷中，戒指則戴在領袖手上。",
  ui_story_5084_50840201_82_dialog_content = "瓦拉吉的血脈詛咒，無論過了多久，仍然無法擺脫。",
  ui_story_5084_50840201_83_dialog_content = "汝須獲神啟，去填補那跨越時間長河的疑竇。",
  ui_story_5084_50840201_84_dialog_content = "汝須讓真理進入，方可延展對世界的解讀。",
  ui_story_5084_50840201_85_dialog_content = "吾以真理結社領袖，威廉·瓦拉吉之名，聽從真理之主的指引，宣佈聖鳴節的受召者為……",
  ui_story_5084_50840201_86_dialog_content = "維多利亞·瓦拉吉。",
  ui_story_5084_50840201_87_dialog_content = "嗯……？",
  ui_story_5084_50840201_88_dialog_content = "維多利亞·瓦拉吉？她怎麼會在這裡？",
  ui_story_5084_50840201_89_dialog_content = "呵呵，有意思。",
  ui_story_5084_50840201_90_dialog_content = "……",
  ui_story_5084_50840201_91_dialog_content = "維多利亞小姐？她也來了！",
  ui_story_5084_50840201_92_dialog_content = "那位是瓦拉吉家的獨生女……",
  ui_story_5084_50840201_93_dialog_content = "但我聽說，家主們並未接受她……",
  ui_story_5084_50840201_94_dialog_content = "……",
  ui_story_5084_50840301_1_dialog_content = "<size=30>是維多利亞大人耶！</size>",
  ui_story_5084_50840301_2_dialog_content = "妳怎麼一副高興的樣子！這根本就是被過去的人認出來了啊！",
  ui_story_5084_50840301_3_dialog_content = "這不是破壞原則了嗎？",
  ui_story_5084_50840301_4_dialog_content = "跟著心的指引，啟示不會錯。除非，有人已經受到指引了。",
  ui_story_5084_50840301_5_dialog_content = "真理的信徒們，請期待下一輪血月。真理之主永遠注視著你。",
  ui_story_5084_50840301_6_dialog_content = "願真理祝福你。",
  ui_story_5084_50840301_7_dialog_content = "願真理祝福你。",
  ui_story_5084_50840301_8_dialog_content = "我們也要跟著他們離開嗎？",
  ui_story_5084_50840301_9_dialog_content = "聽隨心的指引，靜觀其變。",
  ui_story_5084_50840301_10_dialog_content = "如何？",
  ui_story_5084_50840301_11_dialog_content = "我並非真理結社的成員。這聆聽天啟的殊榮，不該賦予我。",
  ui_story_5084_50840301_12_dialog_content = "然而進入真理殿堂的殊榮賦予妳之時，妳卻沒有異議。",
  ui_story_5084_50840301_13_dialog_content = "求問真理，拉黨結派，妳是在為未來加入真理結社做準備。",
  ui_story_5084_50840301_14_dialog_content = "這一切，與你無關。",
  ui_story_5084_50840301_15_dialog_content = "妳還沒有回答我。真理，究竟是什麼？",
  ui_story_5084_50840301_16_dialog_content = "……",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>劈啪——</color>",
  ui_story_5084_50840301_18_dialog_content = "不過……妳說「天啟」？維多利亞·瓦拉吉，我倒想問問早慧的妳。妳認為，真理是什麼？",
  ui_story_5084_50840301_19_dialog_content = "真理……是知識。",
  ui_story_5084_50840301_20_dialog_content = "哼，維多利亞·瓦拉吉。妳我出身自相同血脈，但無論頭腦、力量、能力，甚至姿色，我都在妳之上。",
  ui_story_5084_50840301_21_dialog_content = "妳又憑什麼認為這枚戒指應屬於妳？",
  ui_story_5084_50840301_22_dialog_content = "我才是真正的瓦拉吉！真理結社的領袖！",
  ui_story_5084_50840301_23_dialog_content = "而妳，先努力證明給我看吧。證明妳配得上瓦拉吉這個姓氏，別令我蒙羞。",
  ui_story_5084_50840301_24_dialog_content = "……",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>劈啪——</color>",
  ui_story_5084_50840301_26_dialog_content = "從書籍中挑出高深的字句，從與共鳴的幻象中尋找答案……",
  ui_story_5084_50840301_27_dialog_content = "這是妳一貫的應對方式，不是嗎？",
  ui_story_5084_50840301_28_dialog_content = "剛剛又看到了什麼？想起了什麼？",
  ui_story_5084_50840301_29_dialog_content = "質疑？恐懼？拒絕？不是人挑選瓦拉吉的力量，維多利亞，是力量在挑選人。",
  ui_story_5084_50840301_30_dialog_content = "……",
  ui_story_5084_50840301_31_dialog_content = "（他戴著維多利亞的家傳戒指……）",
  ui_story_5084_50840301_32_dialog_content = "威廉，你之前不是告訴我，維多利亞離開瓦拉吉鎮了？",
  ui_story_5084_50840301_33_dialog_content = "呵呵，是啊。",
  ui_story_5084_50840301_34_dialog_content = "瓦拉吉，面對如此聰慧的小姐，你還是如此嚴厲啊。",
  ui_story_5084_50840301_35_dialog_content = "好久不見了，維多利亞小姐。",
  ui_story_5084_50840301_36_dialog_content = "嗯。",
  ui_story_5084_50840301_37_dialog_content = "波菲里歐，欽選她的是真理之主。於我，於瓦拉吉，只覺得無奈而已。",
  ui_story_5084_50840301_38_dialog_content = "呵呵，我不怨任何人。只怨吾等同源於「血之一族」，卻走上不同的岔道。",
  ui_story_5084_50840301_39_dialog_content = "真理之主還會降臨嗎？祂遴選的繼承人是不備資格，還是不備信仰？",
  ui_story_5084_50840301_40_dialog_content = "這是我們十二位家主的責任，不能全賴在你們瓦拉吉頭上。",
  ui_story_5084_50840301_41_dialog_content = "哈哈哈哈，真是漂亮又致命的責備啊，波菲里歐。",
  ui_story_5084_50840301_42_dialog_content = "好啦。啟示不得違背。那就來瞧瞧，真理之主究竟想傳遞些什麼給她吧。",
  ui_story_5084_50840301_43_dialog_content = "各位家主！",
  ui_story_5084_50840301_44_dialog_content = "對於本次聖鳴節的受召者，諸位可有異議？",
  ui_story_5084_50840301_45_dialog_content = "……",
  ui_story_5084_50840301_46_dialog_content = "無異議。",
  ui_story_5084_50840301_47_dialog_content = "即使有異議又能如何？",
  ui_story_5084_50840301_48_dialog_content = "哼。",
  ui_story_5084_50840301_49_dialog_content = "快開始吧，真理之主已經等不及了。",
  ui_story_5084_50840301_50_dialog_content = "不必緊張，維多利亞·瓦拉吉。",
  ui_story_5084_50840301_51_dialog_content = "我會牽著妳走上神聖大殿，送妳進入棺木。",
  ui_story_5084_50840301_52_dialog_content = "靜下心整理思緒，準備向主展示妳對真理的體悟。",
  ui_story_5084_50840301_53_dialog_content = "……",
  ui_story_5084_50840301_54_dialog_content = "（剛才在街上聽到信徒說「獻祭自己」，這儀式究竟是怎麼回事？）",
  ui_story_5084_50840301_55_dialog_content = "（總覺得家主各個都透露出一股危險的氣息。）",
  ui_story_5084_50840301_56_dialog_content = "（如果維多利亞真的被「獻祭」了，該怎麼辦？！）",
  ui_story_5084_50840301_57_dialog_content = "（不行，在維多利亞進入棺木之前，我得搞清楚狀況。）",
  ui_story_5084_50840301_58_option_content = "開始感應",
  ui_story_5084_50840301_59_dialog_content = "終於跟上來了。",
  ui_story_5084_50840301_60_dialog_content = "事情是不是不太對勁？妳真的要跟著這個人躺進棺木，接受「獻祭」嗎？",
  ui_story_5084_50840301_61_dialog_content = "嗯。",
  ui_story_5084_50840301_62_dialog_content = "那、那我和梅怎麼辦？！",
  ui_story_5084_50840301_63_dialog_content = "記得希卡蕾的話嗎？",
  ui_story_5084_50840301_64_dialog_content = "當然記得！命運早已銘刻，不容……質疑？",
  ui_story_5084_50840301_65_dialog_content = "不容質疑……",
  ui_story_5084_50840301_66_dialog_content = "看來你想通了。",
  ui_story_5084_50840301_67_dialog_content = "空裔，打從來到這裡開始，你就跟不上了。",
  ui_story_5084_50840301_68_dialog_content = "儘管不容質疑，你的心裡還是疑問滿滿。",
  ui_story_5084_50840301_69_dialog_content = "現在這種情況，很難沒有疑問吧！",
  ui_story_5084_50840301_70_dialog_content = "跟著直覺走，和我一起見證。",
  ui_story_5084_50840301_71_dialog_content = "維多利亞！",
  ui_story_5084_50840301_72_dialog_content = "那麼……",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>呼——呼——</color>",
  ui_story_5084_50840301_74_dialog_content = "即刻入棺！",
  ui_story_5084_50840301_75_dialog_content = "……",
  ui_story_5084_50840301_76_dialog_content = "有風……維多利亞大人真的躺進去了！",
  ui_story_5084_50840301_77_option_content = "開始感應",
  ui_story_5084_50840301_78_dialog_content = "（感應好像被隔絕開了……）",
  ui_story_5084_50840301_79_dialog_content = "哈哈……",
  ui_story_5084_50840301_80_dialog_content = "哈哈……哈哈哈哈……",
  ui_story_5084_50840301_81_dialog_content = "哈哈哈哈……哈哈哈哈哈……",
  ui_story_5084_50840301_82_dialog_content = "（這些笑聲……他們到底在做什麼？）",
  ui_story_5084_50840301_83_dialog_content = "哈哈哈哈哈……",
  ui_story_5084_50840301_84_dialog_content = "（怎麼連身為領袖的威廉也在笑？）",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>呼——呼——</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName？",
  ui_story_5084_50840301_87_dialog_content = "梅，別怕！我在這裡！",
  ui_story_5084_50840301_88_dialog_content = "怎麼……？",
  ui_story_5084_50840301_89_dialog_content = "蠟燭被那陣黑風吹熄了，整個殿堂都看不見了！",
  ui_story_5084_50840301_90_dialog_content = "那些人的笑聲好詭異……是在合謀些什麼嗎？",
  ui_story_5084_50840301_91_dialog_content = "那個威廉對維多利亞說的那些話……",
  ui_story_5084_50840301_92_dialog_content = "維多利亞不會有事吧？！他們到底在笑什麼？不，不對！",
  ui_story_5084_50840301_93_option_content = "強制感應——",
  ui_story_5084_50840301_94_dialog_content = "（只能勉強看到一點點。究竟是為什麼？）",
  ui_story_5084_50840301_95_dialog_content = "這些年來領導真理結社很辛苦吧？威廉·瓦拉吉。",
  ui_story_5084_50840301_96_dialog_content = "你明知道讓信徒進入棺木意味著什麼。選中<color=#FFB400>奧斯頓·瓦拉吉</color>的女兒，你還真是別有用心。",
  ui_story_5084_50840301_97_dialog_content = "他是真理結社前任領袖，也是我的兄長，照顧兄長的女兒，本來就是應該的。",
  ui_story_5084_50840301_98_dialog_content = "（威廉是維多利亞的……叔叔？）",
  ui_story_5084_50840301_99_dialog_content = "這種冠冕堂皇的話我不想聽了，瓦拉吉。",
  ui_story_5084_50840301_100_dialog_content = "我知道你沒有找到辦法。",
  ui_story_5084_50840301_101_dialog_content = "要一同享用你的姪女嗎？還是你們就一起……",
  ui_story_5084_50840301_102_dialog_content = "等等——",
  ui_story_5084_50840301_103_dialog_content = "威廉，你到底在做什麼？你和我說了那些話後，做的事情就是這樣嗎？",
  ui_story_5084_50840301_104_dialog_content = "沒錯。而你也已經做出你的選擇了，克萊維斯。",
  ui_story_5084_50840301_105_dialog_content = "……",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>呼——呼——</color>",
  ui_story_5084_50840301_107_dialog_content = "（糟糕，這陣風似乎是刻意想遮掩這些話……）",
  ui_story_5084_50840301_108_dialog_content = "（克萊維斯、威廉、維多利亞，他們到底在計劃些什麼？）",
  ui_story_5084_50840301_109_dialog_content = "哎唷，PlayerName，不要抓得那麼緊啦！不然我又要縫手臂了。",
  ui_story_5084_50840301_110_dialog_content = "抱歉，我……",
  ui_story_5084_50840301_111_dialog_content = "現在的力道剛剛好喔。",
  ui_story_5084_50840301_112_dialog_content = "快想辦法，快想辦法啊！現在到底是怎麼回事？",
  ui_story_5084_50840301_113_dialog_content = "維多利亞和她叔叔在計劃什麼？為什麼威廉要拿維多利亞獻祭？",
  ui_story_5084_50840301_114_dialog_content = "PlayerName，你在想辦法嗎？燭火搖晃起來了。你看，場景好像在變。",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>叩……叩……</color>",
  ui_story_5084_50840401_2_dialog_content = "這聲音……",
  ui_story_5084_50840401_3_dialog_content = "喵？",
  ui_story_5084_50840401_4_dialog_content = "寶寶別怕唷，小梅在這裡。",
  ui_story_5084_50840401_5_dialog_content = "你們一直沒說話，我還以為只剩我一個人呢。",
  ui_story_5084_50840401_6_dialog_content = "好像到了某個新地方……好香的味道，是衣服？",
  ui_story_5084_50840401_7_dialog_content = "欸？",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_5084_50840401_9_dialog_content = "有人來了！",
  ui_story_5084_50840401_10_dialog_content = "唔——不要摀我——唔！",
  ui_story_5084_50840401_11_dialog_content = "哼，這件衣服昨天穿過，今天就成了歷史。",
  ui_story_5084_50840401_12_dialog_content = "這件的面料像砂紙一樣，我可是藝術家，不是木工。",
  ui_story_5084_50840401_13_dialog_content = "這件……顏色不夠有想法。身為藝術家，我無法接受這種平庸的色彩。",
  ui_story_5084_50840401_14_dialog_content = "嘖，這些都是什麼啊？童裝店製作……我早就到了穿成熟衣服的年紀了！",
  ui_story_5084_50840401_15_dialog_content = "可惡！我為什麼要把父親的話當真！",
  ui_story_5084_50840401_16_dialog_content = "那兩個來拜訪的傢伙，配不上我卡戎大人的「正式」裝束！",
  ui_story_5084_50840401_17_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5084_50840401_18_dialog_content = "......？",
  ui_story_5084_50840401_19_dialog_content = "什……卡戎？！",
  ui_story_5084_50840401_20_dialog_content = "而且他……沒看到我們？",
  ui_story_5084_50840401_21_dialog_content = "呼——PlayerName終於放開我啦！你認識這個弟弟？",
  ui_story_5084_50840401_22_dialog_content = "藝術家……卡戎大人……那個頭髮、表情……何止是認識！",
  ui_story_5084_50840401_23_dialog_content = "他剛剛是站在我們面前，沒錯吧？",
  ui_story_5084_50840401_24_dialog_content = "是啊，正在挑衣服。這些香香的衣服的確很別緻，就連梅也縫不出來。",
  ui_story_5084_50840401_25_dialog_content = "卡戎的衣櫃啊。這時候的卡戎，外表也就十歲出頭吧？",
  ui_story_5084_50840401_26_dialog_content = "嗯，不過那傢伙的年齡不能細想，總之是過去的時間。",
  ui_story_5084_50840401_27_dialog_content = "剛才的聖鳴節，維多利亞說是一九一五年。",
  ui_story_5084_50840401_28_dialog_content = "說到底，這蠟燭到底是怎麼回事？燭光搖晃就變換場景，這一次還是和梅一起。",
  ui_story_5084_50840401_29_dialog_content = "PlayerName真笨啊，當然是因為你左手拿著蠟燭，右手拉著我和寶寶啊。",
  ui_story_5084_50840401_30_dialog_content = "希卡蕾姐姐有很多厲害的道具。如果你不相信魔法，那我和你沒什麼好說的。",
  ui_story_5084_50840401_31_dialog_content = "魔法？妳都不會對發生的這一切感到好奇嗎？",
  ui_story_5084_50840401_32_dialog_content = "你是說開心的好奇，還是恐懼的好奇？",
  ui_story_5084_50840401_33_dialog_content = "啊哈哈，不過梅都喜歡唷！",
  ui_story_5084_50840401_34_dialog_content = "那，卡戎會看不見、聽不見我們，也是因為蠟燭嗎？",
  ui_story_5084_50840401_35_dialog_content = "剛才混入真理殿堂也是，只有一起從未來來的維多利亞看得見我們。",
  ui_story_5084_50840401_36_dialog_content = "這蠟燭，就是那些故事書上說的「隱身道具」嘛！",
  ui_story_5084_50840401_37_dialog_content = "啊哈哈，真的耶！",
  ui_story_5084_50840401_38_dialog_content = "維多利亞進入棺木後不曉得怎麼樣了，聖釘和浮士德也不知道在哪裡。",
  ui_story_5084_50840401_39_dialog_content = "我們來到這裡，真的是聽從心的指引嗎？",
  ui_story_5084_50840401_40_dialog_content = "你剛剛心中在想什麼？",
  ui_story_5084_50840401_41_dialog_content = "蠟燭晃動的時候？似乎是……",
  ui_story_5084_50840401_42_dialog_content = "「克萊維斯、威廉、維多利亞，他們到底在計劃些什麼？」",
  ui_story_5084_50840401_43_dialog_content = "如果卡戎口中的父親，以及那兩個來拜訪的人是他們……",
  ui_story_5084_50840401_44_dialog_content = "希卡蕾說的「蠟燭會給我指引」，是這個意思！",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_5084_50840401_46_dialog_content = "我這麼做純粹是因為藝術不該有偏見。那雙襪子是我的珍藏，這次就勉強為了他們換上吧。",
  ui_story_5084_50840401_47_dialog_content = "（原來還真的有在認真換衣服啊……）",
  ui_story_5084_50840401_48_dialog_content = "「卡戎大人，您平常都在哪裡買這麼迷人的襪子？」",
  ui_story_5084_50840401_49_dialog_content = "「卡戎大人，您真是我所見過最有品味的人！」",
  ui_story_5084_50840401_50_dialog_content = "哼，這就是大人的世界嗎？煩惱真是多得數不清。",
  ui_story_5084_50840401_51_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5084_50840401_52_dialog_content = "……",
  ui_story_5084_50840401_53_dialog_content = "呃，還真是從小就與眾不同。",
  ui_story_5084_50840401_54_dialog_content = "梅，我們跟過去看看！別離我太遠。",
  ui_story_5084_50840401_55_dialog_content = "知道啦！",
  ui_story_5084_50840401_56_dialog_content = "好久不見了，克萊維斯。",
  ui_story_5084_50840401_57_dialog_content = "克萊維斯叔叔。",
  ui_story_5084_50840401_58_dialog_content = "是維多利亞大人！維——",
  ui_story_5084_50840401_59_dialog_content = "這個距離，她早該看見了。既然對我們沒反應，這應該是過去的她？",
  ui_story_5084_50840401_60_dialog_content = "雖然現在的她，跟我們認識的維多利亞相差無幾。",
  ui_story_5084_50840401_61_dialog_content = "笨蛋，維多利亞大人可是高貴的血族。從覺醒開始，她就不會再變老啦。",
  ui_story_5084_50840401_62_dialog_content = "啊，對了，PlayerName。如果過去的人都看不到我們，為什麼還要躲？",
  ui_story_5084_50840401_63_dialog_content = "嗯？！對喔。或許是因為這裡的人和事情都有點嚇人？",
  ui_story_5084_50840401_64_dialog_content = "哈哈，你們叔姪倆一同光臨，還真是罕見啊。",
  ui_story_5084_50840401_65_dialog_content = "哼……",
  ui_story_5084_50840401_66_dialog_content = "卡戎呢？",
  ui_story_5084_50840401_67_dialog_content = "那孩子你也知道，一見到外人就要忙著打扮。",
  ui_story_5084_50840401_68_dialog_content = "……",
  ui_story_5084_50840401_69_dialog_content = "喲，卡戎大人。襪子，很有品味。",
  ui_story_5084_50840401_70_dialog_content = "啊！就算妳這麼說，我也——",
  ui_story_5084_50840401_71_dialog_content = "還不打招呼？",
  ui_story_5084_50840401_72_dialog_content = "……威廉叔叔好。",
  ui_story_5084_50840401_73_dialog_content = "還有這位是威廉叔叔的姪女，維多利亞，是你的表姐。",
  ui_story_5084_50840401_74_dialog_content = "你好，遠親。",
  ui_story_5084_50840401_75_dialog_content = "……表姐好。",
  ui_story_5084_50840401_76_dialog_content = "卡戎，帶維多利亞表姐去吃些點心。",
  ui_story_5084_50840401_77_dialog_content = "……知道了。",
  ui_story_5084_50840401_78_dialog_content = "瓦拉吉鎮的事都弄完了嗎，有空到舊鎮來？",
  ui_story_5084_50840401_79_dialog_content = "確實並不輕鬆。但你也知道，克萊維斯，為了見你，無論多遠我都會來。",
  ui_story_5084_50840401_80_dialog_content = "……",
  ui_story_5084_50840401_81_dialog_content = "……",
  ui_story_5084_50840401_82_dialog_content = "你要盯著我看到什麼時候？",
  ui_story_5084_50840401_83_dialog_content = "你們和那些陰鬱的傢伙是一夥的？",
  ui_story_5084_50840401_84_dialog_content = "哪些陰鬱的傢伙？",
  ui_story_5084_50840401_85_dialog_content = "就是和威廉·瓦拉吉一樣，結社的那些傢伙。",
  ui_story_5084_50840401_86_dialog_content = "我不是真理結社的人。不過，直呼領袖的名字，你還真是沒禮貌。",
  ui_story_5084_50840401_87_dialog_content = "和他們走得近的傢伙都不是好人，這是來自藝術家的直覺。是父親要求，我才出來見你們的。",
  ui_story_5084_50840401_88_dialog_content = "你很討厭你父親的朋友，卻為了見他們精心打扮。",
  ui_story_5084_50840401_89_dialog_content = "這、這是為了藝術！",
  ui_story_5084_50840401_90_dialog_content = "噢？你懂藝術？藝術是什麼？",
  ui_story_5084_50840401_91_dialog_content = "我們總有一天都會死。但有一樣東西不會死，妳知道是什麼嗎？",
  ui_story_5084_50840401_92_dialog_content = "是藝術！",
  ui_story_5084_50840401_93_dialog_content = "藝術能從地獄開出禁忌之花，能從冥河開道駛出一輛永動列車。",
  ui_story_5084_50840401_94_dialog_content = "而我，會成為這架列車的車長，成為靈魂的擺渡人，成為藝術，獲得永生。",
  ui_story_5084_50840401_95_dialog_content = "永生？呵呵，看來我注定會成為你的乘客了。",
  ui_story_5084_50840401_96_dialog_content = "當然！不、不對，還不行。自從那些陰鬱的傢伙羞辱了我的傑作……",
  ui_story_5084_50840401_97_dialog_content = "那麼大的孩子了，怎麼會對小便池有別樣的熱愛？",
  ui_story_5084_50840401_98_dialog_content = "像酒過三巡的人找不著方向，原地撒潑。",
  ui_story_5084_50840401_99_dialog_content = "所以我決定，我的列車只接待能欣賞我藝術的人。",
  ui_story_5084_50840401_100_dialog_content = "活得太久，舉止粗魯，最重要的是沒有品味，這樣的傢伙我不接待。",
  ui_story_5084_50840401_101_dialog_content = "對自己很有自信嘛。",
  ui_story_5084_50840401_102_dialog_content = "那當然，整個舊鎮沒見過品味比我好的人。",
  ui_story_5084_50840401_103_dialog_content = "以後我會創辦自己的戲劇結社、音樂結社、列車模型結社、藝術結社……",
  ui_story_5084_50840401_104_dialog_content = "不怕告訴你，我早已悟透那些傢伙追求的真理。藝術就是真理。",
  ui_story_5084_50840401_105_dialog_content = "怎麼樣，看在妳還沒有找到組織的情況下，有膽量挑戰卡戎大人的入社考驗嗎？",
  ui_story_5084_50840401_106_dialog_content = "呵呵，有意思。說說看，什麼考驗？",
  ui_story_5084_50840401_107_dialog_content = "很簡單，在我的列車開過這裡時，調動感官進入我的藝術世界！然後，妳也要展現自己對藝術的覺悟。",
  ui_story_5084_50840401_108_dialog_content = "嗯，那就來吧。",
  ui_story_5084_50840401_109_dialog_content = "那妳等著吧，父親不讓我在外人面前展現這些東西。",
  ui_story_5084_50840401_110_dialog_content = "就讓妳看看列車長的表演，看看什麼是真正的藝術！",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>片刻之後……</color>",
  ui_story_5084_50840401_112_dialog_content = "聽，鐵軌上迴響著世界末日前的呼號！嗚嗚——",
  ui_story_5084_50840401_113_dialog_content = "目睹吧！這是末世前駛向永恆的終末列車！",
  ui_story_5084_50840401_114_dialog_content = "載著渴望不朽的藝術家們，穿越至光輝的天際！",
  ui_story_5084_50840401_115_dialog_content = "鏈條已斷，不再束縛其軀，只餘下無盡的車輪，永不停歇地向前馳騁！",
  ui_story_5084_50840401_116_dialog_content = "車首高昂，指向蒼穹！在我——卡戎列車長的引領下，我們將逃離被詛咒的深淵！",
  ui_story_5084_50840401_117_dialog_content = "我將命令地獄敞開門扉，迎接新世界的曙光！",
  ui_story_5084_50840401_118_dialog_content = "哇，我好像真的能看到列車在黑暗中行駛。",
  ui_story_5084_50840401_119_dialog_content = "不愧是卡戎，走到哪裡，哪裡就是他的舞台。",
  ui_story_5084_50840401_120_dialog_content = "叩隆叩隆——聽啊！我的口齒之間流瀉出舊世界與新世界的交響曲！無需恐慌！",
  ui_story_5084_50840401_121_dialog_content = "一直開，一直開，直至新世界的大門洞開！那裡是不朽的樂土！",
  ui_story_5084_50840401_122_dialog_content = "……",
  ui_story_5084_50840401_123_dialog_content = "換妳了，表姐！",
  ui_story_5084_50840401_124_dialog_content = "呵呵，雖然很有表演天賦。但新世界的出口不過是幻覺！",
  ui_story_5084_50840401_125_dialog_content = "你渴望的新世界大門，將是一道無形的壁壘，猛然往你的臉上砸下！",
  ui_story_5084_50840401_126_dialog_content = "列車軌道起火，紅黃相間的巨物將燃燒你的幻想。",
  ui_story_5084_50840401_127_dialog_content = "死亡才是真理！必須送上終結的序曲！而永生是深不見底的恐懼，無盡的恐慌！",
  ui_story_5084_50840401_128_dialog_content = "你在恐懼下潰縮成螞蟻，困在名為永生的牢籠裡，永遠尋不到出路。",
  ui_story_5084_50840401_129_dialog_content = "在巨物的凝視下，你成遭人玩弄的傀儡，掙扎無門，更無力反抗！",
  ui_story_5084_50840401_130_dialog_content = "抬頭吧！",
  ui_story_5084_50840401_131_dialog_content = "新世界的真相正是如此——一場無盡的操控！",
  ui_story_5084_50840401_132_dialog_content = "......！",
  ui_story_5084_50840401_133_dialog_content = "在那些看不見真容之人的囈語中，你的瘋狂只是他們的娛樂！",
  ui_story_5084_50840401_134_dialog_content = "激起恐懼，這才是真正的藝術！",
  ui_story_5084_50840401_135_dialog_content = "嗚哇啊啊啊——",
  ui_story_5084_50840401_136_dialog_content = "表姐，妳——！",
  ui_story_5084_50840401_137_dialog_content = "永生的藝術不如這刺激吧？",
  ui_story_5084_50840401_138_dialog_content = "哈哈哈哈哈哈哈！",
  ui_story_5084_50840401_139_dialog_content = "……嗚哇啊啊啊啊！！！",
  ui_story_5084_50840401_140_dialog_content = "讓我的列車停下來！快停！停下來！",
  ui_story_5084_50840401_141_dialog_content = "哈哈哈哈哈！",
  ui_story_5084_50840401_142_dialog_content = "維多利亞大人竟然有位那麼有趣的小表弟。",
  ui_story_5084_50840401_143_dialog_content = "欸？妳的重點錯了吧？不是應該說維多利亞竟然這樣捉弄卡戎嗎？",
  ui_story_5084_50840401_144_dialog_content = "難怪卡戎談起這位親戚的時候態度不怎麼好。這算什麼藝術啊？",
  ui_story_5084_50840401_145_dialog_content = "那也不成啊，威廉。",
  ui_story_5084_50840401_146_dialog_content = "你究竟在害怕什麼？克萊維斯，你難道看不出事情越來越不對勁了嗎？",
  ui_story_5084_50840401_147_dialog_content = "波菲里歐和那些家主們，從瓦拉吉血脈分化出去後，便不再遵循戒律了。",
  ui_story_5084_50840401_148_dialog_content = "你這麼做救不了任何人。",
  ui_story_5084_50840401_149_dialog_content = "但現在的真理結社，無論於你、於我、於其他市民都是禍害。血族的戒律，那從來都是牢籠！",
  ui_story_5084_50840401_150_dialog_content = "嗜血是血之一族的本性，你我皆然。只不過我們幸運一點罷了。",
  ui_story_5084_50840401_151_dialog_content = "血脈、血脈……什麼時候你也把這東西掛在嘴邊了？",
  ui_story_5084_50840401_152_dialog_content = "不要這麼說，威廉，我只是不會否認事實而已。",
  ui_story_5084_50840401_153_dialog_content = "那把<color=#FFB400>鑰匙</color>，真的只會害了你。",
  ui_story_5084_50840401_154_dialog_content = "我兄長臨終特地將它從<color=#FFB400>藤蔓人</color>手中取回交給你，顯然是為了確保它能傳到我手上。",
  ui_story_5084_50840401_155_dialog_content = "也可能只是為了避免你強行從<color=#FFB400>藤蔓人</color>手中搶走。",
  ui_story_5084_50840401_156_dialog_content = "無論如何離經叛道，身為繼承人的你，如今又已重新主持真理結社多年。",
  ui_story_5084_50840401_157_dialog_content = "這些事情，都刻印在古老的預言中。",
  ui_story_5084_50840401_158_dialog_content = "你比我清楚，命運的走向不可逆。",
  ui_story_5084_50840401_159_dialog_content = "不，並非如此！",
  ui_story_5084_50840401_160_dialog_content = "我信奉真理之主，瓦拉吉的存亡與我無關！至少，我不認可那所謂命運的走向。",
  ui_story_5084_50840401_161_dialog_content = "即使發生在我身上，也並非是我必定要承受。",
  ui_story_5084_50840401_162_dialog_content = "我從始至終只會聽從內心的指引，那才是真理。",
  ui_story_5084_50840401_163_dialog_content = "那維多利亞呢？那是你兄長對你的託付——",
  ui_story_5084_50840401_164_dialog_content = "別跟我提起他，克萊維斯。",
  ui_story_5084_50840401_165_dialog_content = "維多利亞比我還不屑於這身力量，比我對瓦拉吉鎮的一切更無感。她會照顧好她自己。",
  ui_story_5084_50840401_166_dialog_content = "呵呵。或許，這也是對我那兄長的一種懲罰。",
  ui_story_5084_50840401_167_dialog_content = "威廉……",
  ui_story_5084_50840401_168_dialog_content = "既然如此，希望你照顧好你的家人。",
  ui_story_5084_50840401_169_dialog_content = "嗚哇啊啊啊啊！！！",
  ui_story_5084_50840401_170_dialog_content = "……",
  ui_story_5084_50840401_171_dialog_content = "維多利亞·瓦拉吉，該走了。",
  ui_story_5084_50840401_172_dialog_content = "……",
  ui_story_5084_50840401_173_dialog_content = "這麼快就走了？我們還什麼都不知道！要跟上去嗎？快想呀……",
  ui_story_5084_50840401_174_dialog_content = "有效了！燭光又開始搖晃啦，你快——",
  ui_story_5084_50840401_175_dialog_content = "別哭了……",
  ui_story_5084_50840401_176_dialog_content = "瘋子……瘋女人！",
  ui_story_5084_50840401_177_dialog_content = "把你那些破爛東西收起來，立刻！",
  ui_story_5084_50840401_178_dialog_content = "嗚嗚……",
  ui_story_5084_50840501_1_dialog_content = "這一次我學會了。蠟燭搖晃的時候，我在想「威廉到底在想什麼」。",
  ui_story_5084_50840501_2_dialog_content = "所以這裡是……威廉大人的家吧？",
  ui_story_5084_50840501_3_dialog_content = "啊，是威廉大人！",
  ui_story_5084_50840501_4_dialog_content = "他緊捏著戒指，一臉惆悵的樣子。",
  ui_story_5084_50840501_5_dialog_content = "但是，就算你問他心裡在想什麼，我們也不知道啊。",
  ui_story_5084_50840501_6_dialog_content = "大名鼎鼎的空裔，偷聽到的話記得告訴我唷。",
  ui_story_5084_50840501_7_dialog_content = "誰、誰說我要用感應能力偷聽？",
  ui_story_5084_50840501_8_dialog_content = "不然你要怎麼知道他心裡在想什麼？",
  ui_story_5084_50840501_9_dialog_content = "……",
  ui_story_5084_50840501_10_dialog_content = "別蘑菇了，既然是大人，就要學會當機立斷！",
  ui_story_5084_50840501_11_dialog_content = "好吧，如果只是感應的話，應該不算違反希卡蕾說的規則吧？",
  ui_story_5084_50840501_12_option_content = "感應連結——",
  ui_story_5084_50840501_13_dialog_content = "遺物中蘊含的囈語，只有戴上後才知道。一瞬間產生被殺死一千次，啃食一萬次的痛苦……",
  ui_story_5084_50840501_14_dialog_content = "瓦拉吉、血之一族，就真的沒有出路了嗎？",
  ui_story_5084_50840501_15_dialog_content = "生為光靈，卻蟄伏在這暗無天日的小鎮，只能透過繼承獲得力量。",
  ui_story_5084_50840501_16_dialog_content = "甚至得在血族祖先的指引下躲避、逃離，過著生不如死的一生。",
  ui_story_5084_50840501_17_dialog_content = "什麼祖先的意志？什麼繼承力量？瓦拉吉為了維持統治，全然不顧後代的死活。",
  ui_story_5084_50840501_18_dialog_content = "雖然瓦拉吉一族已經學會食用替代血，但血族始終擺脫不了這罪惡之力的源頭。",
  ui_story_5084_50840501_19_dialog_content = "（替代血？維多利亞常常說的「生之甘露」，該不會真的是……）",
  ui_story_5084_50840501_20_dialog_content = "這戒指……",
  ui_story_5084_50840501_21_dialog_content = "可惡……",
  ui_story_5084_50840501_22_dialog_content = "近年來，家主們對血的渴望越發極端。",
  ui_story_5084_50840501_23_dialog_content = "唉，克萊維斯。自從那次爭執後都過去了三年，也不知道他現在在做些什麼。",
  ui_story_5084_50840501_24_dialog_content = "（維多利亞和威廉拜訪卡戎的父親是三年前？那今年是哪一年？）",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_5084_50840501_26_dialog_content = "……",
  ui_story_5084_50840501_27_dialog_content = "這個時候的維多利亞？",
  ui_story_5084_50840501_28_dialog_content = "看她的氣質，應該是過去的維多利亞沒錯。",
  ui_story_5084_50840501_29_dialog_content = "也是過去的維多利亞大人呢！你剛才有偷聽到什麼嗎？",
  ui_story_5084_50840501_30_dialog_content = "維多利亞進來時，威廉立刻把戒指推入中指，感應好像被什麼東西擋了一下。",
  ui_story_5084_50840501_31_dialog_content = "所以感應結束了？",
  ui_story_5084_50840501_32_dialog_content = "嗯。那個戒指似乎會對威廉的精神造成巨大傷害。但先看看他們說什麼吧。",
  ui_story_5084_50840501_33_dialog_content = "呃……",
  ui_story_5084_50840501_34_dialog_content = "你回來了？這次你出去了三個月，怎麼了？",
  ui_story_5084_50840501_35_dialog_content = "與妳無關。",
  ui_story_5084_50840501_36_dialog_content = "你那幽怨的眼神是怎麼回事？",
  ui_story_5084_50840501_37_dialog_content = "威廉·瓦拉吉，你在外面遇到了什麼事？",
  ui_story_5084_50840501_38_dialog_content = "誰准妳進我房間的？",
  ui_story_5084_50840501_39_dialog_content = "你身為真理結社的領袖，卻屢次外出，不理公事，待在家的時間一次比一次短。",
  ui_story_5084_50840501_40_dialog_content = "我說過很多遍，這與妳無關。馬上給我出去。",
  ui_story_5084_50840501_41_dialog_content = "確實，你拒絕過我的對話很多次了。但今天晚上就是聖鳴節，我還以為能和你有最後一次討論。",
  ui_story_5084_50840501_42_dialog_content = "關於真理，關於我們。",
  ui_story_5084_50840501_43_dialog_content = "滾出去！馬上給我滾出去！",
  ui_story_5084_50840501_44_dialog_content = "……",
  ui_story_5084_50840501_45_dialog_content = "威廉大人好兇，怎麼那麼突然？",
  ui_story_5084_50840501_46_dialog_content = "呃……<size=45>呃啊！</size>",
  ui_story_5084_50840501_47_dialog_content = "威廉大人不對勁！快想想辦法！",
  ui_story_5084_50840501_48_dialog_content = "是那枚戒指嗎？",
  ui_story_5084_50840501_49_option_content = "感應連接——",
  ui_story_5084_50840501_50_dialog_content = "哈哈哈哈哈哈哈！咬碎她的指頭！捏斷她的脖子！",
  ui_story_5084_50840501_51_dialog_content = "閉嘴……",
  ui_story_5084_50840501_52_dialog_content = "為了保住領袖之位，不惜在真正的領袖面前戴上足以讓你瘋狂的戒指？",
  ui_story_5084_50840501_53_dialog_content = "是想毀了她，還是毀了自己？",
  ui_story_5084_50840501_54_dialog_content = "呵呵，我對疼痛的感知，早已在你的影響下變得麻木不仁。",
  ui_story_5084_50840501_55_dialog_content = "瓦拉吉一族會毀在你的手上。",
  ui_story_5084_50840501_56_dialog_content = "呵，要毀了我，就連真理結社一起……",
  ui_story_5084_50840501_57_dialog_content = "她組織了自己的人馬，剷除瓦拉吉的血脈後，真理結社將重新誕生。",
  ui_story_5084_50840501_58_dialog_content = "她是終結瓦拉吉的人。",
  ui_story_5084_50840501_59_dialog_content = "包括我？",
  ui_story_5084_50840501_60_dialog_content = "你唯有被他們殺死才能活下來。",
  ui_story_5084_50840501_61_dialog_content = "你到底在說什麼鬼話！",
  ui_story_5084_50840501_62_dialog_content = "我說，你去死吧！",
  ui_story_5084_50840501_63_dialog_content = "（這些聲音好可怕，直接從精神層面打擊著威廉。）",
  ui_story_5084_50840501_64_dialog_content = "（難道遺物是力量的來源，卻會為佩戴者帶來強烈的折磨？）",
  ui_story_5084_50840501_65_dialog_content = "（這倒是很符合真理結社成員的一些刻板印象。）",
  ui_story_5084_50840501_66_dialog_content = "（這是誰的聲音呢？是戒指最初的擁有者？瓦拉吉的祖先？還是……）",
  ui_story_5084_50840501_67_dialog_content = "<size=45>呃——啊啊啊！</size>",
  ui_story_5084_50840501_68_dialog_content = "這就是你抗拒命運的下場。",
  ui_story_5084_50840501_69_dialog_content = "離——開！",
  ui_story_5084_50840501_70_dialog_content = "不自量力。",
  ui_story_5084_50840501_71_dialog_content = "從我身體裡——<size=45>離開！！</size>",
  ui_story_5084_50840501_72_dialog_content = "主啊！！！真理之途究竟在哪裡！！！",
  ui_story_5084_50840501_73_dialog_content = "（威廉快要失去意識了！）",
  ui_story_5084_50840501_74_dialog_content = "（這些聲音在意識裡具象化成了怪物，我或許可以幫上忙！）",
  ui_story_5084_50840502_1_dialog_content = "噢？你似乎還掌握了某種新的力量？",
  ui_story_5084_50840502_2_dialog_content = "平靜而隱密……",
  ui_story_5084_50840502_3_dialog_content = "……",
  ui_story_5084_50840502_4_dialog_content = "（糟糕！難道被發現了？）",
  ui_story_5084_50840502_5_dialog_content = "作為獎勵，讓你看點你感興趣的東西吧。",
  ui_story_5084_50840502_6_dialog_content = "願真理祝福他。",
  ui_story_5084_50840502_7_dialog_content = "終於，又完成一樁大事。",
  ui_story_5084_50840502_8_dialog_content = "信徒的鮮血……真是久違的美味呀。",
  ui_story_5084_50840502_9_dialog_content = "你，從中領悟到了什麼真理？",
  ui_story_5084_50840502_10_dialog_content = "我的領悟，唯有感激。",
  ui_story_5084_50840502_11_dialog_content = "只有在血月，血之一族的嗜血慾望才能獲得滿足。",
  ui_story_5084_50840502_12_dialog_content = "信眾在崇高的禱詞中狂舞、自殘，爭先恐後地獻祭，只為觸摸那位他們無法理解的主。",
  ui_story_5084_50840502_13_dialog_content = "百年如一日地，互相成就著。",
  ui_story_5084_50840502_14_dialog_content = "但美味又何止這些？",
  ui_story_5084_50840502_15_dialog_content = "既值聖鳴之夜，何不多添一些虔誠的信徒？",
  ui_story_5084_50840502_16_dialog_content = "這才是妳喝下信眾血液後的領悟吧？",
  ui_story_5084_50840502_17_dialog_content = "不盡然。",
  ui_story_5084_50840502_18_dialog_content = "當主流淌於他們身上之時，我們飲其鮮血，是為將領悟到的真理傳遞給後世。",
  ui_story_5084_50840502_19_dialog_content = "此為吾等家主與信徒間的契約。",
  ui_story_5084_50840502_20_dialog_content = "若不能從中窺見真理，再多的獻祭者也無用。",
  ui_story_5084_50840502_21_dialog_content = "你有領悟？",
  ui_story_5084_50840502_22_dialog_content = "當然。",
  ui_story_5084_50840502_23_dialog_content = "提醒各位，此為我們血之一族的戒律、祕密。",
  ui_story_5084_50840502_24_dialog_content = "還請正視家主的位置，切勿走上那嗜殺之徒的老路。",
  ui_story_5084_50840502_25_dialog_content = "願真理祝福你。",
  ui_story_5084_50840502_26_dialog_content = "願真理祝福你。",
  ui_story_5084_50840502_27_dialog_content = "在我的血脈覺醒之時，早就看過這些。",
  ui_story_5084_50840502_28_dialog_content = "這是聖鳴節的古老儀式，先祖們試圖飲盡羔羊之血，趁著快意獲得神啟。",
  ui_story_5084_50840502_29_dialog_content = "等等……這個意思是，聖鳴節的受召者會被那些家主吃掉嗎？！",
  ui_story_5084_50840502_30_dialog_content = "難怪剛剛離開之前，那些人笑得那麼猖狂。",
  ui_story_5084_50840502_31_dialog_content = "維多利亞原來是就是被這樣獻祭了？！",
  ui_story_5084_50840502_32_dialog_content = "誰？",
  ui_story_5084_50840502_33_dialog_content = "噢？你的房間裡好像有客人。",
  ui_story_5084_50840502_34_dialog_content = "……",
  ui_story_5084_50840502_35_dialog_content = "PlayerName，你做了什麼嗎？威廉大人是不是發現我們了？",
  ui_story_5084_50840502_36_dialog_content = "抱歉，可能是我剛剛太激動了。",
  ui_story_5084_50840502_37_dialog_content = "但在威廉的意識中，我看到了一些可怕的事情……",
  ui_story_5084_50840502_38_dialog_content = "我有點擔心維多利亞，我再看看！",
  ui_story_5084_50840502_39_option_content = "感應連接——",
  ui_story_5084_50840502_40_dialog_content = "那這些呢？",
  ui_story_5084_50840502_41_dialog_content = "即使獻上自己的姪女，你仍未能獲得主的啟示，所以開始發狂了嗎？",
  ui_story_5084_50840502_42_dialog_content = "也罷，我厭倦和你玩這無聊的遊戲了。",
  ui_story_5084_50840502_43_dialog_content = "威廉！邪典已在我手。真理為我所知！",
  ui_story_5084_50840502_44_dialog_content = "嗯？這是預言？聖鳴節……今晚……",
  ui_story_5084_50840502_45_dialog_content = "（是我在教堂見過的家主！今晚的聖鳴節會獻祭維多利亞？那現在是一九一五年！）",
  ui_story_5084_50840502_46_dialog_content = "不相信？",
  ui_story_5084_50840502_47_dialog_content = "這就是我威廉·瓦拉吉的結局？",
  ui_story_5084_50840502_48_dialog_content = "你還不夠瞭解瓦拉吉掌握的力量，卻以自己的遭遇替血之一族判了死刑。",
  ui_story_5084_50840502_49_dialog_content = "縱使年輕一輩總是會對戒律和教條嗤之以鼻。",
  ui_story_5084_50840502_50_dialog_content = "但真理結社的領袖，真的不是你。",
  ui_story_5084_50840502_51_dialog_content = "呵呵……哈哈哈哈……",
  ui_story_5084_50840502_52_dialog_content = "真理？荒唐！",
  ui_story_5084_50840502_53_dialog_content = "只不過在那尊貴的傢伙手上戴久了，就染上了他的脾氣嗎？",
  ui_story_5084_50840502_54_dialog_content = "留下詛咒，一邊讓我繼承家主，一邊逼我看著維多利亞成為領袖後主動請辭？",
  ui_story_5084_50840502_55_dialog_content = "讓目標窺見未來的假象，扭曲他的精神，進而操縱他去實現教唆者的目的。",
  ui_story_5084_50840502_56_dialog_content = "這種感覺再熟悉不過了。",
  ui_story_5084_50840502_57_dialog_content = "我犯過一次錯，可不會再犯第二次。",
  ui_story_5084_50840502_58_dialog_content = "你真的一點都不想殺了維多利亞嗎？",
  ui_story_5084_50840502_59_dialog_content = "不想。",
  ui_story_5084_50840502_60_dialog_content = "你在猶豫。",
  ui_story_5084_50840502_61_dialog_content = "想要殺了她的是那些家主。我是瓦拉吉的次子，死不足惜。但他們害怕維多利亞變得強大。",
  ui_story_5084_50840502_62_dialog_content = "如果預言是真的……",
  ui_story_5084_50840502_63_dialog_content = "維多利亞血脈覺醒比較晚，對我傳遞的真理也充耳不聞。",
  ui_story_5084_50840502_64_dialog_content = "如果我死了，這些蛀蟲哪會放過她？",
  ui_story_5084_50840502_65_dialog_content = "維多利亞，維多利亞……",
  ui_story_5084_50840502_66_dialog_content = "（咦？他是在擔心維多利亞？）",
  ui_story_5084_50840502_67_dialog_content = "對，身為真理結社的領袖，受召者是由我來宣佈！",
  ui_story_5084_50840502_68_dialog_content = "但她剛才是不是說，今晚不參加聖鳴節？我該去哪裡找她才好？",
  ui_story_5084_50840502_69_dialog_content = "糟糕，維多利亞正好去了教堂，所以才被獻祭了！？",
  ui_story_5084_50840502_70_dialog_content = "到底是誰在這裡？",
  ui_story_5084_50840502_71_dialog_content = "（糟了！）",
  ui_story_5084_50840502_72_dialog_content = "呵，留了一手嗎？",
  ui_story_5084_50840502_73_dialog_content = "PlayerName！你是不是又做了什麼？",
  ui_story_5084_50840502_74_dialog_content = "完了完了，他提到要獻祭維多利亞，我忍不住激動了。",
  ui_story_5084_50840502_75_dialog_content = "獻祭維多利亞大人？是今晚嗎？那不是跟之前發生的情況一樣？",
  ui_story_5084_50840502_76_dialog_content = "雖然威廉似乎很擔心維多利亞，但我必須知道，他到底想對維多利亞做什麼。",
  ui_story_5084_50840502_77_dialog_content = "這間書房，難道還留有<color=#FFB400>奧斯頓·瓦拉吉</color>的遺物？",
  ui_story_5084_50840502_78_dialog_content = "又或者……是主？",
  ui_story_5084_50840502_79_dialog_content = "主啊，您剛才說要獻祭維多利亞，是真的嗎？",
  ui_story_5084_50840502_80_dialog_content = "主？",
  ui_story_5084_50840502_81_dialog_content = "告訴我，剛才是誰在說話？",
  ui_story_5084_50840502_82_dialog_content = "是主，一定是！",
  ui_story_5084_50840502_83_dialog_content = "呃啊！<size=45>該死的戒指！！</size>",
  ui_story_5084_50840502_84_dialog_content = "殺了我吧！讓我解脫！",
  ui_story_5084_50840502_85_dialog_content = "瞧瞧你那扭曲的樣子。",
  ui_story_5084_50840502_86_dialog_content = "呃——啊啊啊啊！",
  ui_story_5084_50840502_87_dialog_content = "啊哈哈哈哈哈！真理結社的領袖是我！我！",
  ui_story_5084_50840502_88_dialog_content = "（戒指的力量又在傷害威廉了，該怎麼辦才好？）",
  ui_story_5084_50840502_89_dialog_content = "真沒出息。我說過，你只有死了才能活下來。",
  ui_story_5084_50840502_90_dialog_content = "我死了無所謂，但維多利亞怎麼辦？",
  ui_story_5084_50840502_91_dialog_content = "主啊……",
  ui_story_5084_50840502_92_dialog_content = "維多利亞今後該怎麼辦？",
  ui_story_5084_50840502_93_dialog_content = "他完全失控了，再這麼下去他會死的！",
  ui_story_5084_50840502_94_dialog_content = "PlayerName在感應中的精神活動似乎能傳遞給他，要不要再試試看？",
  ui_story_5084_50840502_95_dialog_content = "如果貿然說話，影響了過去的事情就糟了。",
  ui_story_5084_50840502_96_dialog_content = "梅，妳跟他一樣信仰真理之主，妳聽到什麼樣的話會感到平靜，不會再有痛苦和疑問呢？",
  ui_story_5084_50840502_97_dialog_content = "當然是「願真理祝福你」還有「皆當遵循指引」。",
  ui_story_5084_50840502_98_dialog_content = "這樣就可以嗎？那我試試看……",
  ui_story_5084_50840502_99_option_content = "感應連接——",
  ui_story_5084_50840502_100_dialog_content = "願真理祝福你們。",
  ui_story_5084_50840502_101_dialog_content = "……",
  ui_story_5084_50840502_102_dialog_content = "願真理祝福你們。",
  ui_story_5084_50840502_103_dialog_content = "願真理，祝福你。",
  ui_story_5084_50840502_104_dialog_content = "您……到底是誰？",
  ui_story_5084_50840502_105_dialog_content = "（似乎成功了，我一定不能再說錯話了。）",
  ui_story_5084_50840502_106_dialog_content = "恕我無法再相信那些操縱人心的「神明」。我心中的真理不證自明。",
  ui_story_5084_50840502_107_dialog_content = "真理結社不該再這樣下去。至少維多利亞的未來不可以。",
  ui_story_5084_50840502_108_dialog_content = "如果您也信仰真理之主，您一定也理解我說的。",
  ui_story_5084_50840502_109_dialog_content = "您這個時候出現，一定是想向我傳遞些什麼吧？",
  ui_story_5084_50840502_110_dialog_content = "……皆當遵循指引。",
  ui_story_5084_50840502_111_dialog_content = "您的意思是，我應該接受現實，等著被家主分食……",
  ui_story_5084_50840502_112_dialog_content = "讓維多利亞繼承血之一族的詛咒，慘遭那個吸血鬼殺害？",
  ui_story_5084_50840502_113_dialog_content = "（不是！怎麼感覺變糟了……）",
  ui_story_5084_50840502_114_dialog_content = "不……絕不！",
  ui_story_5084_50840502_115_dialog_content = "我能走到今天，全靠我被家族排擠後，獨自修行所信奉的真理。真理不是這樣的！",
  ui_story_5084_50840502_116_dialog_content = "都是因為聽信了這些所謂的「啟示」，真理結社才會淪落到這番田地。",
  ui_story_5084_50840502_117_dialog_content = "我必須，破除這道詛咒。",
  ui_story_5084_50840502_118_dialog_content = "我想想……",
  ui_story_5084_50840502_119_dialog_content = "要說還沒有染上領袖氣息的聖物，只有<color=#FFB400>那一件</color>了。",
  ui_story_5084_50840502_120_dialog_content = "血月……藤蔓幻化成人形時，守衛一族會等待墓穴的主人前來。",
  ui_story_5084_50840502_121_dialog_content = "但除了搬運先祖的棺木，就只有拿到<color=#FFB400>鑰匙</color>，或是所有家主同在，我才能進入陵墓。",
  ui_story_5084_50840502_122_dialog_content = "呵！威廉啊威廉，都要被分食了，還想著這些條例？活該被人耍著玩！",
  ui_story_5084_50840502_123_dialog_content = "即使克萊維斯不借我鑰匙，藤蔓人世代侍奉瓦拉吉……",
  ui_story_5084_50840502_124_dialog_content = "若他得知我獲得的這些啟示，一定會為我開啟墓門。",
  ui_story_5084_50840502_125_dialog_content = "我必須在遊行儀式開始之前，進入墓穴。",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>呼——！</color>",
  ui_story_5084_50840502_127_dialog_content = "梅，抓緊我！",
  ui_story_5084_50840502_128_dialog_content = "這次我們要去哪？",
  ui_story_5084_50840502_129_dialog_content = "瓦拉吉墓穴！",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>瓦拉吉鎮，裁縫鋪門口</color>",
  ui_story_5084_50840601_2_dialog_content = "願真理祝福妳，心靈手巧的夫人。",
  ui_story_5084_50840601_3_dialog_content = "願真理祝福您，慷慨的先生。您看起來真是聖潔，一定會成為今年的受召者。",
  ui_story_5084_50840601_4_dialog_content = "借您吉言。我先離開了，我們今夜盛典上見，別遲到。",
  ui_story_5084_50840601_5_dialog_content = "盛典上見。",
  ui_story_5084_50840601_6_dialog_content = "我怎麼……會來到這裡？",
  ui_story_5084_50840601_7_dialog_content = "這位先生，您也是來拿慶典長袍的嗎？",
  ui_story_5084_50840601_8_dialog_content = "慶典長袍？",
  ui_story_5084_50840601_9_dialog_content = "噢，那想必您是別家的客人。",
  ui_story_5084_50840601_10_dialog_content = "不過本店是鎮上歷史最悠久的裁縫鋪，聖鳴節時長袍的訂購量也數全鎮最多。",
  ui_story_5084_50840601_11_dialog_content = "許多住在偏遠小鎮的信徒，會在慶典當夜才來本鋪拿長袍。",
  ui_story_5084_50840601_12_dialog_content = "不然，您也可以在本鋪重新購買一件？價格包您滿意。",
  ui_story_5084_50840601_13_dialog_content = "……",
  ui_story_5084_50840601_14_dialog_content = "先生，您看，血月就要出現了。",
  ui_story_5084_50840601_15_dialog_content = "血月？看來今晚就是聖鳴節了。",
  ui_story_5084_50840601_16_dialog_content = "導師說，他會選我成為今年的受召者，所以我得事先準備一套聖潔的衣服。",
  ui_story_5084_50840601_17_dialog_content = "受召者！我沒聽錯吧？",
  ui_story_5084_50840601_18_dialog_content = "這件事可是由威廉·瓦拉吉大人宣佈，您怎麼知道自己會獲選呢？",
  ui_story_5084_50840601_19_dialog_content = "嗯，導師確實叫這個名字。我們在墓穴裡見過。",
  ui_story_5084_50840601_20_dialog_content = "瓦拉吉墓穴？那確實沒錯。可以請您告訴我，您是如何參透真理的嗎？",
  ui_story_5084_50840601_21_dialog_content = "……我常常懺悔，但大家好像都躲著我。除了導師。",
  ui_story_5084_50840601_22_dialog_content = "懺悔？今日是聖鳴節，血月……我好像懂了。",
  ui_story_5084_50840601_23_dialog_content = "受召者先生來到這裡，就是在向我傳遞這樣的真理。",
  ui_story_5084_50840601_24_dialog_content = "我以聖鳴節的名義收取信徒的錢財，因此被真理拒於門外。",
  ui_story_5084_50840601_25_dialog_content = "感謝您為我帶來此般啟示，受召者先生。",
  ui_story_5084_50840601_26_dialog_content = "方便在此休息一會嗎？我去找來我的媽媽、女兒，加緊為您縫製一套長袍！",
  ui_story_5084_50840601_27_dialog_content = "這、這怎麼可以。我只是偶然路過，為了去尋找我的導師。",
  ui_story_5084_50840601_28_dialog_content = "不是偶然，先生，是真理。真理引導您到此地！還請原諒我自作主張。",
  ui_story_5084_50840601_29_dialog_content = "您真的不必——",
  ui_story_5084_50840601_30_dialog_content = "媽媽？妳在這裡忙什麼呀，我們的客人都還在等呢！",
  ui_story_5084_50840601_31_dialog_content = "妳去跟顧客說，我們家的長袍免費送，不收錢！",
  ui_story_5084_50840601_32_dialog_content = "哈？",
  ui_story_5084_50840601_33_dialog_content = "之後，我們要為這位受召者先生製作一套長袍！",
  ui_story_5084_50840601_34_dialog_content = "現在？",
  ui_story_5084_50840601_35_dialog_content = "沒錯。",
  ui_story_5084_50840601_36_dialog_content = "婆婆一定會生氣的。",
  ui_story_5084_50840601_37_dialog_content = "照我說的做，我會和妳婆婆解釋的。",
  ui_story_5084_50840601_38_dialog_content = "好吧……",
  ui_story_5084_50840601_39_dialog_content = "主啊！我剛剛又犯下了錯誤……",
  ui_story_5084_50840601_40_dialog_content = "幸好，我身上還有一些錢，希望能填上她們少賺的部分。",
  ui_story_5084_50840601_41_dialog_content = "但我不能再辜負這對裁縫鋪母女的心意了。",
  ui_story_5084_50840601_42_dialog_content = "威廉。",
  ui_story_5084_50840601_43_dialog_content = "誰敢直呼我的名字，攔我的去路？讓開，我要去主持聖鳴節的儀式。",
  ui_story_5084_50840601_44_dialog_content = "你遺忘了真理的細節，目光被現實遮蔽。",
  ui_story_5084_50840601_45_dialog_content = "你還擔不起這份責任，讓我來代替你。",
  ui_story_5084_50840601_46_dialog_content = "是其他家主的爪牙嗎？放馬過來！",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>燭光再燃，周圍又現新景象。一座老舊的墓穴映入眼簾。</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>陰冷的氣息撲面而來，吹散藤蔓上久落的灰塵。</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>藤蔓驀然蠕動，盡情舒展，釋放出囚於懷中之人。</color>",
  ui_story_5084_50840601_50_dialog_content = "我們到了。那個人……是誰？",
  ui_story_5084_50840601_51_dialog_content = "我怎麼會來到這個地方？",
  ui_story_5084_50840601_52_dialog_content = "是剛剛遇上的那個人嗎？他用了某種祕法讓我來到這裡，他則代替我去參加儀式？",
  ui_story_5084_50840601_53_dialog_content = "血月被遮蔽了。現在幾點了？我不會錯過聖鳴節吧？",
  ui_story_5084_50840601_54_dialog_content = "你榮獲啟示。",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>墓穴口的藤蔓相擁緊纏，束成人形。他臉皮枯瘦，眼神昏暗。</color>",
  ui_story_5084_50840601_56_dialog_content = "大人，先祖的墓穴已為您敞開。",
  ui_story_5084_50840601_57_dialog_content = "這……為什麼？",
  ui_story_5084_50840601_58_dialog_content = "<color=#FFB400>鑰匙</color>就在這裡，我能感受到那抹火焰。",
  ui_story_5084_50840601_59_dialog_content = "火焰？但是這裡唯一燃燒著的，只有我們手上的燭台吧？",
  ui_story_5084_50840601_60_dialog_content = "難道是因為我？我之前的聲音把他引來這裡，我又幫他打開了這道門？",
  ui_story_5084_50840601_61_dialog_content = "我到底改變了什麼？",
  ui_story_5084_50840601_62_dialog_content = "等等，我並沒有——",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>不等威廉的話語，藤蔓人形再次消散成青苔遍佈的地面，化為沉默的看門人。</color>",
  ui_story_5084_50840601_64_dialog_content = "墓穴之門開了。守墓人准許我前進。",
  ui_story_5084_50840601_65_dialog_content = "但是，我什麼也不曾做過。難道這就是真理的旨意？",
  ui_story_5084_50840601_66_dialog_content = "命運將我引導至此，主希望我達成祂的使命。",
  ui_story_5084_50840601_67_dialog_content = "我必須前進。",
  ui_story_5084_50840601_68_dialog_content = "他要做什麼？梅，快跟上！",
  ui_story_5084_50840601_69_dialog_content = "瓦拉吉的先祖，如果真有啟示，請明確一點。",
  ui_story_5084_50840601_70_dialog_content = "先祖的棺木呢？！遊行結束後，棺木應該回到這裡才對。",
  ui_story_5084_50840601_71_dialog_content = "究竟是誰，膽敢褻瀆瓦拉吉的安眠之地？",
  ui_story_5084_50840601_72_dialog_content = "真的不見了……先祖的棺木，甚至邪典也都不見了！",
  ui_story_5084_50840601_73_dialog_content = "那些家主的手段來得這麼快？",
  ui_story_5084_50840601_74_dialog_content = "維多利亞……有危險！",
  ui_story_5084_50840601_75_dialog_content = "霜夜紳士！帶我回鎮上教堂！",
  ui_story_5084_50840601_76_dialog_content = "好帥的黑馬……不對，快追上去！",
  ui_story_5084_50840601_77_dialog_content = "死徒？為何在此徘徊？",
  ui_story_5084_50840601_78_dialog_content = "信徒的屍體？鎮上果然發生大事了。",
  ui_story_5084_50840601_79_dialog_content = "滿身污穢的下等之物，竟敢踏入此地，還傷害信徒！",
  ui_story_5084_50840601_80_dialog_content = "沒有意識的蠢物。看來你們的主人放你們出來了。",
  ui_story_5084_50840601_81_dialog_content = "那麼，我便順勢淨化汝等！",
  ui_story_5084_50840602_1_dialog_content = "天啊，那位領袖——威廉·瓦拉吉，真是充滿魅力！",
  ui_story_5084_50840602_2_dialog_content = "經由他的啟示，我亦窺得真理之門的縫隙。",
  ui_story_5084_50840602_3_dialog_content = "那些信徒，好像根本沒有注意到怪物的暴行。",
  ui_story_5084_50840602_4_dialog_content = "聖鳴節儀式已經結束了，家主們應該還在教堂裡。",
  ui_story_5084_50840602_5_dialog_content = "終、終於追上來了，呼，呼……",
  ui_story_5084_50840602_6_dialog_content = "梅，妳看！是之前聽妳傳教的那兩位信徒！這麼一來，時間就接上了！",
  ui_story_5084_50840602_7_dialog_content = "此時的我們應該在裡面！",
  ui_story_5084_50840602_8_dialog_content = "信眾紛紛離去，我還以為儀式已經落幕，沒想到您還在此等候我。",
  ui_story_5084_50840602_9_dialog_content = "聖釘！你怎麼在這裡？！",
  ui_story_5084_50840602_10_dialog_content = "你穿這是什麼啊？",
  ui_story_5084_50840602_11_dialog_content = "這是善良的裁縫為我量身製作的衣服，我深深感激。",
  ui_story_5084_50840602_12_dialog_content = "我的導師，感謝您讓我來到這裡。",
  ui_story_5084_50840602_13_dialog_content = "妳……",
  ui_story_5084_50840602_14_dialog_content = "啊？聖釘到底在說什麼啊？",
  ui_story_5084_50840602_15_dialog_content = "我平常也聽不懂聖釘先生說的話。",
  ui_story_5084_50840602_16_dialog_content = "我很高興能夠成為本次儀式的獻祭者。",
  ui_story_5084_50840602_17_dialog_content = "我不知道你在說什麼。失陪了。",
  ui_story_5084_50840602_18_dialog_content = "波菲里歐，邪典在哪裡？",
  ui_story_5084_50840602_19_dialog_content = "我才想問你，剛才的黑風是怎麼回事？維多利亞在哪裡！",
  ui_story_5084_50840602_20_dialog_content = "維多利亞？",
  ui_story_5084_50840602_21_dialog_content = "即使獻上自己的姪女，你仍未能獲得主的啟示，所以開始發狂了嗎？",
  ui_story_5084_50840602_22_dialog_content = "也罷，我厭倦和你玩這無聊的遊戲了。",
  ui_story_5084_50840602_23_dialog_content = "威廉！邪典已在我手。真理為我所知！",
  ui_story_5084_50840602_24_dialog_content = "不過，今年的儀式已經結束了，我想我們還能再談談。",
  ui_story_5084_50840602_25_dialog_content = "是預言中的場景。呵呵，談？是想對我下手吧！",
  ui_story_5084_50840602_26_dialog_content = "別再裝模作樣了。你吩咐僕從傷害無辜信徒，但牠們已經被我淨化了！",
  ui_story_5084_50840602_27_dialog_content = "話已至此……",
  ui_story_5084_50840602_28_dialog_content = "看來威廉不打算屈從我們。我還要聆聽聖語，有勞兩位了。",
  ui_story_5084_50840602_29_dialog_content = "你休想！",
  ui_story_5084_50840602_30_dialog_content = "沒用的，威廉。手持邪典，命運已站在我這邊。",
  ui_story_5084_50840602_31_dialog_content = "該幹活了，臭蛇。",
  ui_story_5084_50840602_32_dialog_content = "你們想對導師做什麼？受召者是我。",
  ui_story_5084_50840602_33_dialog_content = "哪裡來的外人？",
  ui_story_5084_50840602_34_dialog_content = "就算是威廉也有追隨者。那就先殺了他。",
  ui_story_5084_50840602_35_dialog_content = "你身為真理結社家主，竟敢傷害信徒！",
  ui_story_5084_50840602_36_dialog_content = "你還是想想你自己吧！哈哈哈哈！",
  ui_story_5084_50840602_37_dialog_content = "威廉！",
  ui_story_5084_50840602_38_dialog_content = "主啊，賜下您的苦痛，令我忍受煎熬。吞下吧！蛻化吧！真理將淩駕於暴行之上！",
  ui_story_5084_50840602_39_dialog_content = "不行啊，聖釘先生，快跑！",
  ui_story_5084_50840602_40_dialog_content = "梅，不可以！想想希卡蕾說過的話，我們不能介入他們！",
  ui_story_5084_50840602_41_dialog_content = "都怪我說的話才導致連鎖效應……我們得想別的辦法幫他們。我們還有燭台，一定有辦法。",
  ui_story_5084_50840602_42_dialog_content = "哼，真意外，是個虔誠的硬骨頭。",
  ui_story_5084_50840602_43_dialog_content = "受死吧！",
  ui_story_5084_50840602_44_dialog_content = "主啊，您的儀式竟如此殘酷。任何信眾都將經歷這種折磨嗎？他們又如何渡過此般苦難？",
  ui_story_5084_50840602_45_dialog_content = "我將忍受，吞咽苦痛之殤。我將洗滌罪孽，接納、受盡痛楚詛咒，燒去靈魂的創口。",
  ui_story_5084_50840602_46_dialog_content = "願我一併承受，不令這痛苦蔓延他者。來吧，以傷害抹去那厚重罪孽！",
  ui_story_5084_50840602_47_dialog_content = "我要以生的痛，贖他們的罪！",
  ui_story_5084_50840602_48_dialog_content = "（再這樣下去，聖釘真的會死在他們手上！我得想點辦法！燭台，快帶我去能改變的——）",
  ui_story_5084_50840602_49_dialog_content = "蠢貨！",
  ui_story_5084_50840602_50_dialog_content = "他們既不是執行儀式，也不是想幫你洗滌靈魂！他們只是想殺了你而已！",
  ui_story_5084_50840602_51_dialog_content = "你是苦修者吧？那就活下去，用這掙扎的生存去尋覓真理！",
  ui_story_5084_50840602_52_dialog_content = "導師？",
  ui_story_5084_50840602_53_dialog_content = "活下去！",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>威廉以驚人的力氣拉起聖釘，將他拋出門外。大門猛然被撞開，黑風趁隙而入。</color>",
  ui_story_5084_50840602_55_dialog_content = "啊，蠟燭熄滅了！",
  ui_story_5084_50840602_56_dialog_content = "還有什麼手段，儘管衝著我來！我——威廉·瓦拉吉，絕不會輕易屈服！",
  ui_story_5084_50840602_57_dialog_content = "讓你們這些宵小見識我劍術的厲害！",
  ui_story_5084_50840602_58_dialog_content = "現身吧，<color=#FF0000>赤流</color>！我的魔劍！噬我鮮血，亦奪走我敵人的生機！",
  ui_story_5084_50840602_59_dialog_content = "這是怎麼回事？他們好像打起來了？",
  ui_story_5084_50840602_60_dialog_content = "我看不見，我什麼也看不見！",
  ui_story_5084_50840602_61_dialog_content = "場景好像要開始變換了，但我得看到最後！我要控制住，絕不能被傳送走！",
  ui_story_5084_50840602_62_dialog_content = "梅，抓緊我，退到後面！",
  ui_story_5084_50840602_63_dialog_content = "可惡，這裡好黑。",
  ui_story_5084_50840602_64_dialog_content = "即使如此，他一個人也撐不了多久。",
  ui_story_5084_50840602_65_dialog_content = "啊！",
  ui_story_5084_50840602_66_dialog_content = "誰要成為下一個？",
  ui_story_5084_50840602_67_dialog_content = "克萊維斯，到我身後來！讓我們並肩作戰！",
  ui_story_5084_50840602_68_dialog_content = "……",
  ui_story_5084_50840602_69_dialog_content = "沒用的，就算你砍掉我的頭，我也不會死去。",
  ui_story_5084_50840602_70_dialog_content = "那我就砍到你無法承受這份痛楚！",
  ui_story_5084_50840602_71_dialog_content = "好厲害……他以一敵眾，還是在黑暗中……居然絲毫不落下風。",
  ui_story_5084_50840602_72_dialog_content = "幫手還不出力嗎？",
  ui_story_5084_50840602_73_dialog_content = "說得輕巧……",
  ui_story_5084_50840602_74_dialog_content = "你在指望誰？戴維，你的死期已至！你誰也無法指望！",
  ui_story_5084_50840602_75_dialog_content = "想想我們的交易吧。",
  ui_story_5084_50840602_76_dialog_content = "……",
  ui_story_5084_50840602_77_dialog_content = "<size=45>啊——！！！</size>",
  ui_story_5084_50840602_78_dialog_content = "怎麼回事？我忽然感應不到他的氣息了！",
  ui_story_5084_50840602_79_dialog_content = "抓緊我，我們好像快被傳送到下一個地方了！",
  ui_story_5084_50840602_80_dialog_content = "怎麼回事？怎麼會這樣？",
  ui_story_5084_50840602_81_dialog_content = "如果他真的死了……維多利亞該怎麼辦？",
  ui_story_5084_50840602_82_dialog_content = "PlayerName有沒有覺得，這個威廉大人一點也不冷酷？他真的獻祭了維多利亞大人嗎？",
  ui_story_5084_50840602_83_dialog_content = "我也有同樣的疑問。自從開始跟著蠟燭行動之後，我們遇到的威廉和儀式上的威廉完全判若兩人。",
  ui_story_5084_50840602_84_dialog_content = "是因為我說的話，才產生這一連串的變化嗎？",
  ui_story_5084_50840602_85_dialog_content = "還是這些威廉之間，有什麼關聯呢？",
  ui_story_5084_50840602_86_dialog_content = "維多利亞大人，現在究竟在哪裡？",
  ui_story_5084_50840602_87_dialog_content = "獻祭儀式上，維多利亞提過威廉的失蹤。這個時間點，她會不會在尋找威廉失蹤的真相？",
  ui_story_5084_50840602_88_dialog_content = "或許獻祭儀式並沒有那麼簡單。她選擇走進這一切，一定有想要探究的真相。",
  ui_story_5084_50840602_89_dialog_content = "她和威廉之間似乎長久有著誤解，有想說但沒說出口的話。",
  ui_story_5084_50840700_1_dialog_content = "這裡有好多蠟燭和花壇！PlayerName，那個是棺木嗎？",
  ui_story_5084_50840700_2_dialog_content = "應該是。",
  ui_story_5084_50840700_3_dialog_content = "這次我們又在哪裡？",
  ui_story_5084_50840700_4_dialog_content = "窗外也陰森森的。我看看……",
  ui_story_5084_50840700_5_dialog_content = "這是一座立在懸崖邊的古堡！誰會把家建在這種地方啊？",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5084_50840700_7_dialog_content = "啊，是維多利亞大人！",
  ui_story_5084_50840700_8_dialog_content = "怎麼會？是因為我剛剛想起了維多利亞嗎？",
  ui_story_5084_50840700_9_dialog_content = "等等，那邊還有一個人。",
  ui_story_5084_50840700_10_dialog_content = "妳也是來找威廉的嗎？",
  ui_story_5084_50840700_11_dialog_content = "會來到他住所的，不是仇敵，就只有親人了。",
  ui_story_5084_50840700_12_dialog_content = "他在哪裡？",
  ui_story_5084_50840700_13_dialog_content = "很遺憾，這次我也不知道。他的離去沒有任何蹤跡可循。",
  ui_story_5084_50840700_14_dialog_content = "那真是可惜。我以為就算是他，也至少會有一兩個知心好友。",
  ui_story_5084_50840700_15_dialog_content = "我們確實曾經算得上無話不談。",
  ui_story_5084_50840700_16_dialog_content = "要不是威廉的冒進，我們應該會是永遠的摯友。",
  ui_story_5084_50840700_17_dialog_content = "維多利亞，妳一點也不瞭解他，不瞭解自己的叔叔，對吧？",
  ui_story_5084_50840700_18_dialog_content = "我不想瞭解那樣的人。",
  ui_story_5084_50840700_19_dialog_content = "在妳父親還未成為真理結社的領袖前，威廉曾一心想坐上權位。",
  ui_story_5084_50840700_20_dialog_content = "他的雙眼被名利蒙蔽，篤信著過於激進的理論，將那種東西奉為真理。",
  ui_story_5084_50840700_21_dialog_content = "正因如此，他在繼承先祖的力量時才會接連失控。那時他已成為異化的血緣者，卻仍不甘心。",
  ui_story_5084_50840700_22_dialog_content = "那份不甘，令他成為野心家的傀儡，導致他遭到排擠，最終離開家族。",
  ui_story_5084_50840700_23_dialog_content = "我不關心他的故事。",
  ui_story_5084_50840700_24_dialog_content = "能逃離他的掌控，我其實非常開心。",
  ui_story_5084_50840700_25_dialog_content = "在外旅行時，我已得到主的啟示。我是來道別的。",
  ui_story_5084_50840700_26_dialog_content = "我將去往啟示之處，等候真理之主降臨。",
  ui_story_5084_50840700_27_dialog_content = "妳是瓦拉吉血脈的繼承者，一切由妳自己決定。",
  ui_story_5084_50840700_28_dialog_content = "對了，我想問一下。當初那個人——威廉，在您家中究竟想借走什麼？",
  ui_story_5084_50840700_29_dialog_content = "那把<color=#FFB400>鑰匙</color>，真的只會害了你。",
  ui_story_5084_50840700_30_dialog_content = "我兄長臨終特地將它從<color=#FFB400>藤蔓人</color>手中取回交給你，顯然是為了確保它能傳到我手上。",
  ui_story_5084_50840700_31_dialog_content = "也可能只是為了避免你強行從<color=#FFB400>藤蔓人</color>手中搶走。",
  ui_story_5084_50840700_32_dialog_content = "唔……那是一把萬門之鑰。燃燒野心的人，只會被它吞噬。",
  ui_story_5084_50840700_33_dialog_content = "照顧好自己吧，維多利亞·瓦拉吉。妳的重任才正上肩頭，尋覓真理之路還很長。",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>維多利亞目送克萊維斯離去，一直到他離開視線，才轉身進入威廉的房間。</color>",
  ui_story_5084_50840700_35_dialog_content = "我不瞭解的人……現在你會在哪裡？",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>她巡視了房間一圈，最終打開了那具華麗的棺木，輕身躺入其中。</color>",
  ui_story_5084_50840700_37_dialog_content = "如果像接近父母親那樣……我能明白你在追尋的一切嗎？",
  ui_story_5084_50840700_38_dialog_content = "（這種感覺……她在回憶。）",
  ui_story_5084_50840700_39_dialog_content = "今日我們齊聚一堂，緬懷瓦拉吉家主的長眠。",
  ui_story_5084_50840700_40_dialog_content = "從今往後，他們兩位將伴隨先祖，遺留可憐的小姐——維多利亞·瓦拉吉於世。",
  ui_story_5084_50840700_41_dialog_content = "來吧，請親手把這枚戒指放上您父親的墓碑。這是他榮譽的憑證，此刻也應隨他得到我們的敬意。",
  ui_story_5084_50840700_42_dialog_content = "父親、母親……",
  ui_story_5084_50840700_43_dialog_content = "慢慢來。我們可憐的小姐應該還沉浸在混亂與悲慟中。",
  ui_story_5084_50840700_44_dialog_content = "不要緊，小姐，我們會陪在您身旁，渡過這難熬的時光。對了，我的名字叫戴維·波菲里歐。",
  ui_story_5084_50840700_45_dialog_content = "您的父親曾幫助我壓制血脈中的混亂，令我得以掌握可貴的理智。",
  ui_story_5084_50840700_46_dialog_content = "小姐，我叫克萊維斯·亞伯拉罕。瓦拉吉與我的友誼，我永世不忘。",
  ui_story_5084_50840700_47_dialog_content = "若是您有任何需要幫助的地方，請儘管開口。",
  ui_story_5084_50840700_48_dialog_content = "瓦拉吉小姐，您無須知道在下的名字，叫在下傭人便可。",
  ui_story_5084_50840700_49_dialog_content = "父親也是這樣稱呼你的嗎？",
  ui_story_5084_50840700_50_dialog_content = "在下叫……格雷夫。",
  ui_story_5084_50840700_51_dialog_content = "時間是何其殘酷，我都忘了自己的名字。大家都叫我<color=#FFB400>蝰蛇</color>，小姐您也可以這麼稱呼我。",
  ui_story_5084_50840700_52_dialog_content = "儀式結束，瓦拉吉的家主已然安息。各位，我想是時候談談未來了。",
  ui_story_5084_50840700_53_dialog_content = "維多利亞小姐尚且年幼，這枚戒指的力量，恐怕您還無法承受。",
  ui_story_5084_50840700_54_dialog_content = "就由我暫且替您保管吧。不必擔心，這枚戒指對非瓦拉吉家族的人而言，就和普通的戒指沒兩樣。",
  ui_story_5084_50840700_55_dialog_content = "是嗎？那你又為什麼這麼想得到它呢？",
  ui_story_5084_50840700_56_dialog_content = "威廉·瓦拉吉？！",
  ui_story_5084_50840700_57_dialog_content = "哼，別忘了瓦拉吉家還有一名血脈。真理結社的領袖，只有瓦拉吉可以繼承。",
  ui_story_5084_50840700_58_dialog_content = "……",
  ui_story_5084_50840700_59_dialog_content = "被逐出瓦拉吉家族的異類，竟敢在維多利亞小姐面前口出狂言！",
  ui_story_5084_50840700_60_dialog_content = "看好了，此刻我將繼承先祖的智慧與力量！",
  ui_story_5084_50840700_61_dialog_content = "唔......",
  ui_story_5084_50840700_62_dialog_content = "哈哈哈哈！你那一臉失望的表情是怎麼回事？你好像很不想看到瓦拉吉家的人戴上這枚戒指呢。",
  ui_story_5084_50840700_63_dialog_content = "見證我！現在我威廉·瓦拉吉，正以陰影籠罩汝等！",
  ui_story_5084_50840700_64_dialog_content = "我已獲得先祖認可，是瓦拉吉的新任家主！",
  ui_story_5084_50840700_65_dialog_content = "威廉……你的野心居然還未消減。",
  ui_story_5084_50840700_66_dialog_content = "哼，哈哈哈哈！維多利亞小姐，看來您的叔叔不願把屬於您的位置讓出來。",
  ui_story_5084_50840700_67_dialog_content = "這是瓦拉吉家的事，吾等不該隨意插手。告辭了。",
  ui_story_5084_50840700_68_dialog_content = "威廉·瓦拉吉……我的叔叔……",
  ui_story_5084_50840700_69_dialog_content = "你要去哪裡？",
  ui_story_5084_50840700_70_dialog_content = "當然是離開這裡，前往我所繼承的領地。",
  ui_story_5084_50840700_71_dialog_content = "維多利亞·瓦拉吉，從今天起，我就是妳的監護者。只要我身為家主一日，妳便要事事聽服於我。",
  ui_story_5084_50840700_72_dialog_content = "總有一天，我會獲得天啟。那枚戒指是我父親的遺物，應該屬於我。",
  ui_story_5084_50840700_73_dialog_content = "隨便你。不過戒指現在戴在我手上。",
  ui_story_5084_50840700_74_dialog_content = "不過……妳說「天啟」？維多利亞·瓦拉吉，我倒想問問早慧的妳。妳認為，真理是什麼？",
  ui_story_5084_50840700_75_dialog_content = "真理……是知識。",
  ui_story_5084_50840700_76_dialog_content = "哼，維多利亞·瓦拉吉。妳我出身自相同血脈，但無論頭腦、力量、能力，甚至姿色，我都在妳之上。",
  ui_story_5084_50840700_77_dialog_content = "妳又憑什麼認為這枚戒指應屬於妳？",
  ui_story_5084_50840700_78_dialog_content = "我才是真正的瓦拉吉！真理結社的領袖！",
  ui_story_5084_50840700_79_dialog_content = "而妳，先努力證明給我看吧。證明妳配得上瓦拉吉這個姓氏。別令我蒙羞。",
  ui_story_5084_50840700_80_dialog_content = "（這威廉嘴巴也太毒了吧，他認真的嗎？跟一個小孩子比較這些？）",
  ui_story_5084_50840700_81_dialog_content = "（不過，那個小孩畢竟是維多利亞。奇怪，我們見過的威廉又好像沒有這麼……）",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>外頭電閃雷鳴，年幼的維多利亞推開父母的棺槨，爬入其中。</color>",
  ui_story_5084_50840700_83_dialog_content = "父親、母親……",
  ui_story_5084_50840700_84_dialog_content = "請你們指引我。我該怎麼做？",
  ui_story_5084_50840700_85_dialog_content = "這裡是……家？我怎麼回來了？",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>窸窸窣窣——</color>",
  ui_story_5084_50840700_87_dialog_content = "是誰在瓦拉吉家吵鬧——",
  ui_story_5084_50840700_88_dialog_content = "嗯？怎麼是你？家僕們呢？",
  ui_story_5084_50840700_89_dialog_content = "全部遣散了。從今以後，時間就是我們的僕從，要多少有多少。",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>威廉·瓦拉吉，這個忽然闖入維多利亞生命的人就此住下來，以叔叔的身分時刻監管著她。</color>",
  ui_story_5084_50840700_91_dialog_content = "噢，可憐的維多利亞小姐。生活在這樣的牢籠中。吾等實在痛心，但請您寬恕，吾等對此無能為力。",
  ui_story_5084_50840700_92_dialog_content = "只要威廉仍身為家主，吾等就必須聽從他。都是他要求吾等不得靠近……",
  ui_story_5084_50840700_93_dialog_content = "我冒昧前來，祈望您還健康，現在終於能寬心了。",
  ui_story_5084_50840700_94_dialog_content = "那個人只是在提防我，怕我和你們合謀，搶走他的位置。",
  ui_story_5084_50840700_95_dialog_content = "是的，他在恐懼。您的父親天賦遠勝於他，他不過是一位昔日的異類。",
  ui_story_5084_50840700_96_dialog_content = "維多利亞小姐，我想確認，您的天賦應當如您父親一般讓人驚豔。請問，您可曾與先祖的聖杯共鳴？",
  ui_story_5084_50840700_97_dialog_content = "那種感覺，是怎麼樣的？",
  ui_story_5084_50840700_98_dialog_content = "感覺……彷彿有人進入我的大腦，告訴我它曾盛起過怎樣的瓊漿。",
  ui_story_5084_50840700_99_dialog_content = "有些故事在悄然述說，好像是在說……",
  ui_story_5084_50840700_100_dialog_content = "喂！誰准你踏入我威廉·瓦拉吉的領地？",
  ui_story_5084_50840700_101_dialog_content = "呵呵，威廉，我只是來看看維多利亞小姐過得怎麼樣。我馬上就走。",
  ui_story_5084_50840700_102_dialog_content = "她過得很好，你最好別對一個「新鮮血液」有什麼期待。",
  ui_story_5084_50840700_103_dialog_content = "更別用你的期待引誘她胡思亂想！",
  ui_story_5084_50840700_104_dialog_content = "我和誰說話不用你允許。",
  ui_story_5084_50840700_105_dialog_content = "妳還是太天真了。鎮日伏首於古老的典籍，只會把妳變成不諳世事的學究。",
  ui_story_5084_50840700_106_dialog_content = "妳可知道，先祖的墳墓中有一本「血色邪典」？那當中的啟示，妳看再多古籍也無法獲得。",
  ui_story_5084_50840700_107_dialog_content = "自妳父母長眠以來，妳從未去過祖先的陵墓。",
  ui_story_5084_50840700_108_dialog_content = "但是沒關係，討厭真理結社沒有錯。但妳必須找出情感之外的理由。",
  ui_story_5084_50840700_109_dialog_content = "否則，這也不過是妳在耍孩子脾氣而已。",
  ui_story_5084_50840700_110_dialog_content = "為了不再受人掌控，我必須變得強大。",
  ui_story_5084_50840700_111_dialog_content = "於是我開始試著透過一些儀式與上古遺物共鳴，去尋找真理的所在。",
  ui_story_5084_50840700_112_dialog_content = "在哪裡？「上古的密宗」究竟在哪裡？",
  ui_story_5084_50840700_113_dialog_content = "真理之主親臨我的夢境，要我在威廉·瓦拉吉發現我不見之前找到祂的密宗……",
  ui_story_5084_50840700_114_dialog_content = "啊！",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>星星</color>……它在吞噬<color=#FFB400>星星</color>……沒有時間了，沒有時間了……<color=#FFB400>重啟之時</color>要來了……",
  ui_story_5084_50840700_116_dialog_content = "<size=45>終結的真諦，就在那片黑暗中——</size>",
  ui_story_5084_50840700_117_dialog_content = "蠢貨！妳手裡拿著什麼！竟敢隨便和上古遺物共鳴！",
  ui_story_5084_50840700_118_dialog_content = "舊日的智慧，狂人的啟示——以威廉·瓦拉吉的名義，給我離她遠一點！",
  ui_story_5084_50840700_119_dialog_content = "……啊！",
  ui_story_5084_50840700_120_dialog_content = "回歸安眠吧。",
  ui_story_5084_50840700_121_dialog_content = "是你救了我？你怎麼知道我在……",
  ui_story_5084_50840700_122_dialog_content = "學會分辨遺物的特性是妳的第一課。否則下一次，我就要為妳收屍了。",
  ui_story_5084_50840700_123_dialog_content = "妳也別誤會。我畢竟是真理結社的領袖，可不想讓人懷疑我對兄長的女兒不利。",
  ui_story_5084_50840700_124_dialog_content = "留著妳，對我坐穩這位置還有用。",
  ui_story_5084_50840700_125_dialog_content = "況且，血之一族看見瀕死之人時，比起拯救，不如捏死後品嚐鮮血要愉悅得多。",
  ui_story_5084_50840700_126_dialog_content = "威廉·瓦拉吉……！",
  ui_story_5084_50840700_127_dialog_content = "自大、傲慢，可恨的威廉·瓦拉吉。他擅自掌管我的人生，還常說出一些奇怪的理由。",
  ui_story_5084_50840700_128_dialog_content = "但除了那個討人厭的叔叔，其他人也沒好到哪去。",
  ui_story_5084_50840700_129_dialog_content = "所有家主都心懷鬼胎，怪異而愚蠢。個別家族更是猶如蛆蟲，毫無智慧，在鎮上行屍走肉。",
  ui_story_5084_50840700_130_dialog_content = "他們所宣揚的理念愚昧而邪惡，對信眾尋求真理毫無意義。這樣的人無法拯救迷途的羔羊。",
  ui_story_5084_50840700_131_dialog_content = "我必須警惕，必須小心翼翼，避免沾染上真理結社的任何陋習。",
  ui_story_5084_50840700_132_dialog_content = "為了聆聽真理之主的啟示，為了解決我所見到的「終結」。",
  ui_story_5084_50840700_133_dialog_content = "妳最近總是悶在家裡。是對上古遺物失去興趣了嗎？",
  ui_story_5084_50840700_134_dialog_content = "在妳這個年紀，無論是妳的父親還是我，都早已覺醒血脈，對真理之途充滿好奇。",
  ui_story_5084_50840700_135_dialog_content = "又或者，妳仍然愚昧，仍無法給出「真理是什麼」的答案？",
  ui_story_5084_50840700_136_dialog_content = "我……決定外出旅行，尋找真理的足跡。",
  ui_story_5084_50840700_137_dialog_content = "嗯，隨便妳。",
  ui_story_5084_50840700_138_dialog_content = "於是我開始旅行，尋覓自己的真理啟示。",
  ui_story_5084_50840700_139_dialog_content = "走出家門，我開始對這個世界有了更深的理解。",
  ui_story_5084_50840700_140_dialog_content = "伴隨我對真理的感悟，我的血脈也終於開始覺醒。但我仍警示自己，不要加入真理結社。",
  ui_story_5084_50840700_141_dialog_content = "只是當我獲得感悟想要告訴他，我已經找到答案的時候，他卻不再期待我的回答了。",
  ui_story_5084_50840700_142_dialog_content = "你回來了？這次你出去了三個月，怎麼了？",
  ui_story_5084_50840700_143_dialog_content = "與妳無關。",
  ui_story_5084_50840700_144_dialog_content = "你那幽怨的眼神是怎麼回事？",
  ui_story_5084_50840700_145_dialog_content = "威廉·瓦拉吉，你在外面遇到了什麼事？",
  ui_story_5084_50840700_146_dialog_content = "誰准妳進我房間的？",
  ui_story_5084_50840700_147_dialog_content = "你身為真理結社的領袖，卻屢次外出，不理公事，待在家的時間一次比一次短。",
  ui_story_5084_50840700_148_dialog_content = "我說過很多遍，這與妳無關。馬上給我出去。",
  ui_story_5084_50840700_149_dialog_content = "確實，你拒絕過我的對話很多次了。但今天晚上就是聖鳴節，我還以為能和你有最後一次討論。",
  ui_story_5084_50840700_150_dialog_content = "關於真理，關於我們。",
  ui_story_5084_50840700_151_dialog_content = "滾出去！馬上給我滾出去！",
  ui_story_5084_50840700_152_dialog_content = "……",
  ui_story_5084_50840700_153_dialog_content = "到頭來，我還是沒能瞭解他。",
  ui_story_5084_50840700_154_dialog_content = "恐怕我也確實錯過那最後一次的機會了。",
  ui_story_5084_50840700_155_dialog_content = "自大、傲慢、可恨的威廉·瓦拉吉。我不瞭解的人，我最後的親人，如今你又去了哪裡？",
  ui_story_5084_50840700_156_dialog_content = "（在維多利亞的記憶裡，她和威廉的相處模式竟然是這樣。）",
  ui_story_5084_50840700_157_dialog_content = "（但明明在威廉那邊，他一心只想保護維多利亞。）",
  ui_story_5084_50840700_158_dialog_content = "（他獨自承受失控，不願和家主們共飲信徒鮮血，直到最後還想著他人，甚至救了聖釘。）",
  ui_story_5084_50840700_159_dialog_content = "（這樣的誤解一直持續了那麼多年，直到威廉遇害……）",
  ui_story_5084_50840700_160_dialog_content = "（不知道維多利亞能不能看到這些。）",
  ui_story_5084_50840801_1_dialog_content = "燭火又開始閃爍了。我們又被送到哪個時間點？",
  ui_story_5084_50840801_2_dialog_content = "是維多利亞，還有那些家主們。他們怎麼會聚在一起？",
  ui_story_5084_50840801_3_dialog_content = "嗯？維多利亞大人身邊的人……是浮士德？他好像看過來了？",
  ui_story_5084_50840801_4_dialog_content = "難道說……",
  ui_story_5084_50840801_5_option_content = "感應",
  ui_story_5084_50840801_6_dialog_content = "浮士德，你聽得見我的聲音嗎？",
  ui_story_5084_50840801_7_dialog_content = "當然。我也知曉你此時的疑惑。",
  ui_story_5084_50840801_8_dialog_content = "現在在這裡的維多利亞大人，正是你所熟知的那位維多利亞大人。",
  ui_story_5084_50840801_9_dialog_content = "是和我們一起穿越時間的維多利亞？那她怎麼又和這些人……",
  ui_story_5084_50840801_10_dialog_content = "威廉已經失蹤三年了。瓦拉吉家的後代，如今僅剩亞伯拉罕，以及威廉的姪女維多利亞。",
  ui_story_5084_50840801_11_dialog_content = "（三年？威廉遇害的時間是一九一五年，那現在就是一九一八年？）",
  ui_story_5084_50840801_12_dialog_content = "克萊維斯·亞伯拉罕不願讓他的孩子加入真理結社，這裡自然不會有他的位置。",
  ui_story_5084_50840801_13_dialog_content = "如今領袖之位空缺，吾等也始終尋不回那枚家主的戒指，想來它也與威廉一起下落不明了。",
  ui_story_5084_50840801_14_dialog_content = "那麼，維多利亞，妳便也失去了繼承先祖智慧的機會。",
  ui_story_5084_50840801_15_dialog_content = "噢？召集這麼多位家主，就只為了說這個嗎？",
  ui_story_5084_50840801_16_dialog_content = "聽說妳喜歡外出旅行，尋求真理，那妳便去吧。",
  ui_story_5084_50840801_17_dialog_content = "想離開這裡也好，想併入我波菲里歐家族也行。反正，妳失去成為領袖的資格了。",
  ui_story_5084_50840801_18_dialog_content = "今天是聖鳴節。這真理結社領袖的位置——",
  ui_story_5084_50840801_19_dialog_content = "威廉不在了，這些年來你們舉行的會議就是如此寂寥腐朽，醜態畢露嗎？",
  ui_story_5084_50840801_20_dialog_content = "若是喝了不該喝的血，即使是血之一族，也得付出代價。",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>維多利亞將手上那杯鮮紅漿液潑到桌上，杯底赫然露出那枚威廉曾佩戴過的戒指。</color>",
  ui_story_5084_50840801_22_dialog_content = "......？",
  ui_story_5084_50840801_23_dialog_content = "是……威廉的戒指。",
  ui_story_5084_50840801_24_dialog_content = "早在威廉離開之前，他就把戒指交給我了。祖先的言語，早已耳濡目染。",
  ui_story_5084_50840801_25_dialog_content = "至於真理結社領袖的位置，你還有什麼想說的嗎？",
  ui_story_5084_50840801_26_dialog_content = "這不可能！",
  ui_story_5084_50840801_27_dialog_content = "計劃生變了……",
  ui_story_5084_50840801_28_dialog_content = "「計劃」。在場的各位家主都參與了一場「計劃」。",
  ui_story_5084_50840801_29_dialog_content = "這是三年前的聖鳴節上，我獻祭自己所得到的啟示。",
  ui_story_5084_50840801_30_dialog_content = "三年前的獻祭……",
  ui_story_5084_50840801_31_dialog_content = "不，這怎麼可能！？",
  ui_story_5084_50840801_32_dialog_content = "你在指望誰？戴維，你的死期已至！你誰也無法指望！",
  ui_story_5084_50840801_33_dialog_content = "想想我們的交易吧。",
  ui_story_5084_50840801_34_dialog_content = "……",
  ui_story_5084_50840801_35_dialog_content = "<size=45>啊——！！！</size>",
  ui_story_5084_50840801_36_dialog_content = "噢，可憐的威廉，不受承認的威廉，就這樣死在故鄉。",
  ui_story_5084_50840801_37_dialog_content = "……",
  ui_story_5084_50840801_38_dialog_content = "沒有子嗣繼承，這枚瓦拉吉的戒指傳下去也毫無意義。",
  ui_story_5084_50840801_39_dialog_content = "你在做什麼？你把戒指碾碎了，以後不就——",
  ui_story_5084_50840801_40_dialog_content = "這枚戒指，對吾等毫無用處。就讓它的碎屑陪伴威廉的屍體長眠吧。",
  ui_story_5084_50840801_41_dialog_content = "從今往後，吾等再也不必提心吊膽了。",
  ui_story_5084_50840801_42_dialog_content = "名為瓦拉吉大家主的枷鎖，將從此成為歷史！",
  ui_story_5084_50840801_43_dialog_content = "那枚戒指……應該早就和威廉一起……",
  ui_story_5084_50840801_44_dialog_content = "妳都……知道了？",
  ui_story_5084_50840801_45_dialog_content = "喔？有什麼我不該知道的內幕嗎？",
  ui_story_5084_50840801_46_dialog_content = "那枚戒指，妳真的戴上過嗎？妳有獲得過啟示嗎？",
  ui_story_5084_50840801_47_dialog_content = "未獲得先祖承認，妳憑什麼繼承！",
  ui_story_5084_50840801_48_dialog_content = "先祖賦予我瓦拉吉之名，賜予我這枚失而復得的戒指，便是承認。我，現在就戴上。",
  ui_story_5084_50840801_49_dialog_content = "PlayerName！那枚戒指會讓維多利亞大人失控吧？！",
  ui_story_5084_50840801_50_dialog_content = "梅，我知道怎麼做了！甚至，我也逐漸明白自己為什麼會來這裡了。",
  ui_story_5084_50840801_51_option_content = "感應連接——",
  ui_story_5084_50840801_52_dialog_content = "唔，又來了……",
  ui_story_5084_50840801_53_dialog_content = "那些囈語……舊日的啟示……",
  ui_story_5084_50840801_54_dialog_content = "別擔心，維多利亞，我會幫妳壓制住那些聲音！",
  ui_story_5084_50840801_55_dialog_content = "空裔？！原來如此，這就是真理之主的安排。那就有勞你了。",
  ui_story_5084_50840801_56_dialog_content = "她戴上了，她真的戴上了！",
  ui_story_5084_50840801_57_dialog_content = "你們在擔心什麼呢？身為真正的瓦拉吉，怎可能承受不住先祖的囈語？",
  ui_story_5084_50840801_58_dialog_content = "呵呵呵——哈哈哈哈哈哈！",
  ui_story_5084_50840801_59_dialog_content = "那個笑聲……",
  ui_story_5084_50840801_60_dialog_content = "見證我！現在我威廉·瓦拉吉，正以陰影籠罩汝等！",
  ui_story_5084_50840801_61_dialog_content = "我已獲得先祖認可，是瓦拉吉的新任家主！",
  ui_story_5084_50840801_62_dialog_content = "瓦拉吉……！",
  ui_story_5084_50840801_63_dialog_content = "見證吧，瓦拉吉的繼承人！",
  ui_story_5084_50840802_1_dialog_content = "那麼，我便順勢淨化汝等！",
  ui_story_5084_50840802_2_dialog_content = "怎麼回事？這畫面……",
  ui_story_5084_50840802_3_dialog_content = "我已經盡力壓制了，這些畫面卻還是不斷從戒指傳輸過來。",
  ui_story_5084_50840802_4_dialog_content = "這些似乎無關他者的意志，而是一種更高層面的雜音。",
  ui_story_5084_50840802_5_dialog_content = "它們沒有惡意，請讓我看下去吧。",
  ui_story_5084_50840802_6_dialog_content = "<size=45>啊——！！！</size>",
  ui_story_5084_50840802_7_dialog_content = "把你的血給我，讓我得到那份資格吧！",
  ui_story_5084_50840802_8_dialog_content = "威廉·瓦拉吉，你就是我打開先祖啟示的那把<color=#FFB400>鑰匙</color>！哈哈哈哈哈！",
  ui_story_5084_50840802_9_dialog_content = "威廉·瓦拉吉！他……",
  ui_story_5084_50840802_10_dialog_content = "威廉，你寫信告訴我要離開，我還以為你找到了能和維多利亞安家的地方。",
  ui_story_5084_50840802_11_dialog_content = "但你這笨蛋，為什麼又要回到這裡？",
  ui_story_5084_50840802_12_dialog_content = "哼，我也是個蠢貨，竟然就這樣輕信了<color=#FFB400>那個傢伙</color>。",
  ui_story_5084_50840802_13_dialog_content = "諸位先祖，願你們還能接納威廉·瓦拉吉。他不曾愧對瓦拉吉之名，唯有野心是他血中燃燒的雜質。",
  ui_story_5084_50840802_14_dialog_content = "如今他遭受我這罪人的背叛，願他的罪得以洗滌，我願全數承擔。",
  ui_story_5084_50840802_15_dialog_content = "惟願在我靈魂受盡詛咒之後，卡戎和夫人能夠順利脫離此地。",
  ui_story_5084_50840802_16_dialog_content = "威廉·瓦拉吉，我曾經的摯友，請在這具棺木中安息吧。",
  ui_story_5084_50840802_17_dialog_content = "他……死了？威廉·瓦拉吉……竟然真的死了……",
  ui_story_5084_50840802_18_dialog_content = "這就是這枚戒指想告訴我的真相？",
  ui_story_5084_50840802_19_dialog_content = "三年前把戒指交給我的人，真的已經死了……？",
  ui_story_5084_50840802_20_dialog_content = "妳……打算怎麼做？",
  ui_story_5084_50840802_21_dialog_content = "我有預感，我們離真相越來越近了。",
  ui_story_5084_50840802_22_dialog_content = "我以為真理之主引我至此，是因身為真理結社領袖的我，有某些瞬間必須見證。",
  ui_story_5084_50840802_23_dialog_content = "但此前的獻祭和你的加入讓我醒悟，我必須參與這些過往。既帶著主的恩賜，也帶著無法剝離的恨意。",
  ui_story_5084_50840802_24_dialog_content = "這是只有能掌控力量，足夠理智的我，才能完成的事情。",
  ui_story_5084_50840802_25_dialog_content = "感謝真理之主解答我的疑問，並賜我復仇的快意。",
  ui_story_5084_50840802_26_dialog_content = "正值聖鳴節，吾等的恩怨因乞求先祖啟示而起，就讓它在先祖的見證下結束吧。",
  ui_story_5084_50840802_27_dialog_content = "諸位，久等了。",
  ui_story_5084_50840802_28_dialog_content = "我已獲得真理之主的啟示，明曉自身使命。",
  ui_story_5084_50840802_29_dialog_content = "那枚戒指……妳沒有感到疼痛嗎？",
  ui_story_5084_50840802_30_dialog_content = "威廉戴上那枚戒指時，可沒有妳這麼輕鬆。",
  ui_story_5084_50840802_31_dialog_content = "妳，獲得了怎樣的啟示？",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>維多利亞起身，走向長桌最前端。</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>肅清門派。</color>",
  ui_story_5084_50840802_34_dialog_content = "什麼？！",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>黑風灌入，門窗作響。這位駕馭著遠超時代力量的繼承人，彷彿在對眾家主下達最後通牒。</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5084_50840802_37_dialog_content = "蝰蛇家主，為何驚落手中的杯子？未免太不優雅了。",
  ui_story_5084_50840802_38_dialog_content = "……",
  ui_story_5084_50840802_39_dialog_content = "那枚戒指，究竟向妳展現了什麼！？",
  ui_story_5084_50840802_40_dialog_content = "戴維！這裡是真理殿堂！",
  ui_story_5084_50840802_41_dialog_content = "......！",
  ui_story_5084_50840802_42_dialog_content = "一切既由先祖的節日誕生，那就在今夜先祖的節日結束。",
  ui_story_5084_50840802_43_dialog_content = "身為瓦拉吉的新任家主，我該為今夜的聖鳴節做準備了。",
  ui_story_5084_50840802_44_dialog_content = "各位。血月當空，鐘聲響徹教堂之時，吾等還需齊聚一堂，了卻長夜。",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>昏暗夜燈下，戴維浸泡在血池中。而同處一室的，除了他的狂信者之外，便是被折磨得不成人形的克萊維斯。</color>",
  ui_story_5084_50840900_2_dialog_content = "威廉到底有沒有死？！",
  ui_story_5084_50840900_3_dialog_content = "快……說！",
  ui_story_5084_50840900_4_dialog_content = "你再折磨我……也沒有用。我知道的全都告訴你了。",
  ui_story_5084_50840900_5_dialog_content = "我親手將他的屍體放入棺木，確認了他的死亡。",
  ui_story_5084_50840900_6_dialog_content = "三年前的聖鳴節儀式上，威廉放維多利亞從棺木中離開。",
  ui_story_5084_50840900_7_dialog_content = "我們忍無可忍，終於決定對他出手，也毀掉了那枚束縛吾等的戒指。",
  ui_story_5084_50840900_8_dialog_content = "但為什麼，三年後的今天，維多利亞居然會帶著那枚戒指回來？",
  ui_story_5084_50840900_9_dialog_content = "這對叔姪到底在搞什麼鬼？",
  ui_story_5084_50840900_10_dialog_content = "這本邪典上沒有任何文字。根本沒有你期待的「聖言」。",
  ui_story_5084_50840900_11_dialog_content = "倒是那位瓦拉吉家的小姐，很有她父親的風範。",
  ui_story_5084_50840900_12_dialog_content = "呵……呵呵呵！哈哈哈哈——",
  ui_story_5084_50840900_13_dialog_content = "怎麼？",
  ui_story_5084_50840900_14_dialog_content = "我們真是可笑，過去竟然恐懼於威廉的虛張聲勢，遲遲不敢動手，才會淪落到這般束手無策的地步。",
  ui_story_5084_50840900_15_dialog_content = "那兩個老傢伙死掉時，我們就該殺了維多利亞和威廉。",
  ui_story_5084_50840900_16_dialog_content = "彼時維多利亞還未覺醒，沒有如今這麼棘手。",
  ui_story_5084_50840900_17_dialog_content = "戴維，我們對瓦拉吉卑躬屈膝太久，早已忘了所謂的「真理」，只不過是外來的糟粕。",
  ui_story_5084_50840900_18_dialog_content = "是啊。靠近鮮血，從鮮血汲取力量，才是我們血族的生存方式！",
  ui_story_5084_50840900_19_dialog_content = "缺乏力量，只會利用「斷言」、「重複」、「封閉」、「慾望」來傳播對<color=#FFB400>真理之主</color>的信奉，根本就是邪門歪道！",
  ui_story_5084_50840900_20_dialog_content = "太遲了。她獲得那戒指中的力量了。她是做好準備要來剿滅我們的。",
  ui_story_5084_50840900_21_dialog_content = "只剩下不到半天的時間，再怎麼準備，我們也……",
  ui_story_5084_50840900_22_dialog_content = "閉嘴！當初威廉不也同樣戴著那枚破戒指嗎？最終不也被我吸光了鮮血！",
  ui_story_5084_50840900_23_dialog_content = "哼，只恨他並沒有獲得承認。我喝乾了他的血，還是無法與邪典簽下契約。",
  ui_story_5084_50840900_24_dialog_content = "倒是多虧不斷送上門來的信眾，讓我得以不停補充力量，現在總算能隱隱聽見邪典的召喚了。",
  ui_story_5084_50840900_25_dialog_content = "只差一步……只差一步，我就能讓那本邪典浮現啟示。",
  ui_story_5084_50840900_26_dialog_content = "都怪瓦拉吉壓制了吾等血脈，才讓吾等始終享受不到任何特權。",
  ui_story_5084_50840900_27_dialog_content = "我們生來就要飲血，那些人卻限制我們的天性。如此看來，瓦拉吉這麼做只是畏懼我們的力量。",
  ui_story_5084_50840900_28_dialog_content = "你還想要做什麼？",
  ui_story_5084_50840900_29_dialog_content = "照計劃進行。今晚我必須出席，主持儀式，讓所有信徒看到邪典對我的認可。",
  ui_story_5084_50840900_30_dialog_content = "維多利亞沒有後援，我才不會亂了陣腳。",
  ui_story_5084_50840900_31_dialog_content = "那對叔姪現在僅有的後盾，也就只剩那座墓穴了。藤蔓人一向膽小，淘金鬼、蝰蛇、水鬼，他就交給你們。",
  ui_story_5084_50840900_32_dialog_content = "嗯。",
  ui_story_5084_50840900_33_dialog_content = "我能殺掉威廉，就能殺維多利亞。",
  ui_story_5084_50840900_34_dialog_content = "我現在只需補充力量，靜待她今晚能玩出什麼花樣。",
  ui_story_5084_50840900_35_dialog_content = "唔……戴維……",
  ui_story_5084_50840900_36_dialog_content = "……事情就是這樣了。我們經歷了好幾次時空跳躍，一時也不知道自己來到了哪裡。",
  ui_story_5084_50840900_37_dialog_content = "啟示雖然深奧，但它的安排自有用意。",
  ui_story_5084_50840900_38_dialog_content = "「現在」的三年前——也就是一九一五年，當時我在聖鳴節上和威廉相遇，在他的安排下入棺。",
  ui_story_5084_50840900_39_dialog_content = "那時候，我看見他在轉動這枚戒指。在我記憶中，他從未有過這種動作。",
  ui_story_5084_50840900_40_dialog_content = "這讓我發現，他想向我傳達些什麼，於是我才會走進那場儀式。",
  ui_story_5084_50840900_41_dialog_content = "我醒來之後，就身處在這個時間點了。",
  ui_story_5084_50840900_42_dialog_content = "我跨越了三年的時間，從家中的床上甦醒，手中僅有這枚家傳戒指。",
  ui_story_5084_50840900_43_dialog_content = "在那場儀式的最後，威廉將這枚戒指交給了我。",
  ui_story_5084_50840900_44_dialog_content = "我醒過來時也在那幢大宅裡。有人送來一封信，要我轉交給維多利亞大人。",
  ui_story_5084_50840900_45_dialog_content = "那人走後，我還在思考這是何處，維多利亞大人就推開房門與我相見。",
  ui_story_5084_50840900_46_dialog_content = "信中只要我來參加聖鳴節前夕的家主會議。顯然，家主們完全沒料到我會出現。",
  ui_story_5084_50840900_47_dialog_content = "送這封信的人知道「我」在這裡——而且是「現在的我」，而非該時代的維多利亞。",
  ui_story_5084_50840900_48_dialog_content = "對了，維多利亞大人，我們還遇到聖釘先生，但他好像……很奇怪？",
  ui_story_5084_50840900_49_dialog_content = "他對著並不認識他的威廉說：「感謝您讓我來到這裡。」",
  ui_story_5084_50840900_50_dialog_content = "這個安排了一切的人，會不會是三年前聖鳴節上的威廉？",
  ui_story_5084_50840900_51_dialog_content = "他在我們看到的畫面中已死，但在過去依然活著。",
  ui_story_5084_50840900_52_dialog_content = "三年前的聖鳴節上，他一定做了什麼，只是身處其中的我們還無法理解。",
  ui_story_5084_50840900_53_dialog_content = "不過我有預感，我們離真相越來越近了。",
  ui_story_5084_50840900_54_dialog_content = "維多利亞大人，我一直有個疑問。現在是一九一八年的聖鳴節，當初的您所經歷的情況又是如何？",
  ui_story_5084_50840900_55_dialog_content = "在我記憶中，一九一八年我還在外遊歷，並沒有參與會議。",
  ui_story_5084_50840900_56_dialog_content = "那年聖鳴節，我在漩渦鎮落腳，夜裡卻忽聞天啟，命我回到此地取得邪典。",
  ui_story_5084_50840900_57_dialog_content = "當我醒來，便已身處瓦拉吉墓穴的<color=#FFB400>棺木</color>裡，手中握著那本邪典。",
  ui_story_5084_50840900_58_dialog_content = "邪典驚現啟示，承認漩渦鎮這個地方，並奉我為真理結社的領袖。",
  ui_story_5084_50840900_59_dialog_content = "這正是我們出發之前，我觸碰這枚戒指時看到的，屬於我自己的回憶。",
  ui_story_5084_50840900_60_dialog_content = "您說是瓦拉吉墓穴的<color=#FFB400>棺木</color>？但為什麼是<color=#FFB400>棺木</color>呢？",
  ui_story_5084_50840900_61_dialog_content = "或許是因為……我也有在棺木中睡覺的習慣吧。",
  ui_story_5084_50840900_62_dialog_content = "（嗯，包括父母的棺木、威廉的棺木……）",
  ui_story_5084_50840900_63_dialog_content = "難道說，瓦拉吉家族的棺木有著我們無從得知的力量？",
  ui_story_5084_50840900_64_dialog_content = "某種通往不同時空的力量？",
  ui_story_5084_50840900_65_dialog_content = "包括空裔手中的燭台，也在燃盡之前帶你們穿梭到不同的地方。",
  ui_story_5084_50840900_66_dialog_content = "它還在三年前的聖鳴節，幫助威廉打開了墓穴的門。",
  ui_story_5084_50840900_67_dialog_content = "希卡蕾姐姐那裡，究竟有多少寶物啊！",
  ui_story_5084_50840900_68_dialog_content = "希卡蕾一族世代守護墓穴，不讓維多利亞大人窺探。",
  ui_story_5084_50840900_69_dialog_content = "一直以來，她都說是時候未到。不過那個「時間點」，為什麼會是現在？",
  ui_story_5084_50840900_70_dialog_content = "威廉的失蹤，甚至是他的死，背後或許另有深意。",
  ui_story_5084_50840900_71_dialog_content = "他似乎早已預見今日的危機，彷彿在一旁等著我們一同進入。",
  ui_story_5084_50840900_72_dialog_content = "他曾問過我真理的意義，讓我苦苦追尋答案。但現在我想，他並非是期待我說出正確答案。",
  ui_story_5084_50840900_73_dialog_content = "因為，真理永遠沒有答案。",
  ui_story_5084_50840900_74_dialog_content = "唯有不停回答的堅定信念。",
  ui_story_5084_50840900_75_dialog_content = "我領悟了這份答案的力量，所以我毫無畏懼，決心剷除那些家主。",
  ui_story_5084_50840900_76_dialog_content = "只是對我個人而言，若是三年前他能與我對話，明白我的探索……",
  ui_story_5084_50840900_77_dialog_content = "（明明兩人都只是倔強而已，卻跨越了這麼久都無法和解……）",
  ui_story_5084_50840900_78_dialog_content = "無論如何，這次我一定會搞清楚，這枚戒指回到我手中的用意。",
  ui_story_5084_50840900_79_dialog_content = "（奔波了這麼久，我也想知道確定的答案。）",
  ui_story_5084_50840900_80_dialog_content = "（我見到的威廉明明很努力為維多利亞付出，為什麼和維多利亞回憶裡的樣子不一樣？）",
  ui_story_5084_50840900_81_dialog_content = "（就差一點了。如果能找到那把迷霧中的鑰匙，也許維多利亞還有機會說出答案。）",
  ui_story_5084_50840900_82_dialog_content = "（燭台，你每次都能為我的疑問找到去向，這一次怎麼不動了？）",
  ui_story_5084_50840900_83_dialog_content = "（唉，我好像有點能理解真理結社成員的執念了。）",
  ui_story_5084_50840900_84_dialog_content = "夜幕降臨，聖鳴節的儀式就要開始了，我們的時間也所剩不多。",
  ui_story_5084_50840900_85_dialog_content = "對啊，我的燭台也只剩三分之一了。",
  ui_story_5084_50840900_86_dialog_content = "不必擔心，我知道該怎麼做了。",
  ui_story_5084_50840900_87_dialog_content = "我在家主會議上的恐嚇只會令他們更加渴望力量，想不惜一切與我對抗。",
  ui_story_5084_50840900_88_dialog_content = "萬一他們逃跑怎麼辦？妳的氣勢那麼嚇人。",
  ui_story_5084_50840900_89_dialog_content = "戴維不會逃的。他充滿野心，不達目的絕不會罷休。",
  ui_story_5084_50840900_90_dialog_content = "「如今」的血色邪典，恐怕也已落入他之手。",
  ui_story_5084_50840900_91_dialog_content = "為了登上大家主的位置，為了奪得真理結社，他一定會留下來主持今晚的儀式。",
  ui_story_5084_50840900_92_dialog_content = "因為野心就是如此可怕。野心曾吞噬過威廉，也會吞噬他。",
  ui_story_5084_50840900_93_dialog_content = "那我們要去哪裡？",
  ui_story_5084_50840900_94_dialog_content = "我先祖的墓地。我有想確定的東西。如果我預料的沒錯，戴維也會派人過去。",
  ui_story_5084_50840900_95_dialog_content = "請等一下，維多利亞大人，聖釘先生該怎麼辦？",
  ui_story_5084_50840900_96_dialog_content = "他還留在鎮上呢。",
  ui_story_5084_50840900_97_dialog_content = "別擔心，主為他降下了庇佑。真理會指引他前往該去之處。",
  ui_story_5084_50840900_98_dialog_content = "可是維多利亞大人，我目睹了聖釘先生受到家主傷害……",
  ui_story_5084_50840900_99_dialog_content = "我很擔心，一直很想去找他，只是不知道我這麼做會不會影響到大家。",
  ui_story_5084_50840900_100_dialog_content = "心懷迷惘也不要緊，體貼他人是美好的品德。梅，照妳想做的去做吧。",
  ui_story_5084_50840900_101_dialog_content = "浮士德，你和梅一起留下來照看聖釘。",
  ui_story_5084_50840900_102_dialog_content = "我會和空裔一起，在今夜的教堂與你們相見。",
  ui_story_5084_50841001_1_dialog_content = "入口處的藤蔓竟然在流血……棺木也都被撬開了。看來家主早了我們一步。",
  ui_story_5084_50841001_2_dialog_content = "藐視血族戒律，侵擾先人骸骨。",
  ui_story_5084_50841001_3_dialog_content = "應該就是這裡！我們之前看到的地方！",
  ui_story_5084_50841001_4_dialog_content = "克萊維斯把威廉放進棺木裡……",
  ui_story_5084_50841001_5_dialog_content = "但是這裡沒有那具棺木。",
  ui_story_5084_50841001_6_dialog_content = "大、大小姐？維多利亞大小姐？",
  ui_story_5084_50841001_7_dialog_content = "格雷夫？你竟然還在。那些流血的藤蔓，我還以為連你也……",
  ui_story_5084_50841001_8_dialog_content = "三年來，瓦拉吉的家主都未曾掌管此地，一切都失控了。",
  ui_story_5084_50841001_9_dialog_content = "威廉死了，您又下落不明。那些傢伙不惜一切代價想得到先祖的遺物。",
  ui_story_5084_50841001_10_dialog_content = "他們抓住了我的家人，折磨他們，也折磨我……",
  ui_story_5084_50841001_11_dialog_content = "是戴維。戴維想要奪走一切，剝奪我擔任瓦拉吉家僕的力量。",
  ui_story_5084_50841001_12_dialog_content = "抱歉，沒想到我出走多年，卻害你的家族受到折磨。",
  ui_story_5084_50841001_13_dialog_content = "格雷夫，威廉他……真的死了嗎？",
  ui_story_5084_50841001_14_dialog_content = "克萊維斯……你做了什麼？",
  ui_story_5084_50841001_15_dialog_content = "不過是為此處多添一具屍體而已。",
  ui_story_5084_50841001_16_dialog_content = "請你照看我愚蠢的朋友吧。",
  ui_story_5084_50841001_17_dialog_content = "克萊維斯，克萊維斯……",
  ui_story_5084_50841001_18_dialog_content = "我親眼見到死去的威廉。克萊維斯擅自用那把「鑰匙」進入墓穴，埋葬了他。",
  ui_story_5084_50841001_19_dialog_content = "到裡面去看看吧，空裔。",
  ui_story_5084_50841001_20_dialog_content = "格雷夫，請放心，今夜一切紛爭都會在主的見證下劃上句點。",
  ui_story_5084_50841001_21_dialog_content = "大小姐，請務必小心。",
  ui_story_5084_50841001_22_dialog_content = "他們正在深處破壞墓穴，尋找著什麼……",
  ui_story_5084_50841001_23_dialog_content = "喲，看看是誰來了。",
  ui_story_5084_50841001_24_dialog_content = "是我們的瓦拉吉大小姐。",
  ui_story_5084_50841001_25_dialog_content = "大、大小姐！",
  ui_story_5084_50841001_26_dialog_content = "藤蔓人，沒想到你還沒死透？",
  ui_story_5084_50841001_27_dialog_content = "戴維有說過，要殺了瓦拉吉小姐嗎？",
  ui_story_5084_50841001_28_dialog_content = "先下手為強。",
  ui_story_5084_50841001_29_dialog_content = "愚昧之徒……",
  ui_story_5084_50841001_30_dialog_content = "竟敢闖入瓦拉吉墓穴，打擾先祖安眠！",
  ui_story_5084_50841001_31_dialog_content = "我本打算在今夜的儀式上懲戒你們所有人，沒想到你們竟提前動手。",
  ui_story_5084_50841002_1_dialog_content = "維多利亞，那位叫「水鬼」的家主滲入地下逃走了。",
  ui_story_5084_50841002_2_dialog_content = "哼，所以留下的你們兩位，準備好迎接終結了嗎？",
  ui_story_5084_50841002_3_dialog_content = "等等……瓦拉吉家的大小姐果然長大了。或許妳該和戴維好好談談。",
  ui_story_5084_50841002_4_dialog_content = "不可能！妳在外遊歷不過三年，怎麼會獲得這種力量！",
  ui_story_5084_50841002_5_dialog_content = "三年？你們被自我困在狹窄的世界裡，無法理解外界的劇烈變化。",
  ui_story_5084_50841002_6_dialog_content = "這份力量，何止三年的沉澱。不過，我無意向你們揭示奧祕。",
  ui_story_5084_50841002_7_dialog_content = "受慾望驅使，悖離真理的狂徒！死於聖鳴節的前奏吧！",
  ui_story_5084_50841002_8_dialog_content = "（希卡蕾說過不能改變命運，維多利亞卻打算殺死他們，這難道不是改變嗎？）",
  ui_story_5084_50841002_9_dialog_content = "（還是說，維多利亞下意識的行為，其實早已寫在命運當中？）",
  ui_story_5084_50841002_10_dialog_content = "嗯？",
  ui_story_5084_50841002_11_dialog_content = "嘿嘿……蛇的祕法，妳也無法理解吧？",
  ui_story_5084_50841002_12_dialog_content = "斬去頭顱，蛇亦能蛻皮再生……",
  ui_story_5084_50841002_13_dialog_content = "那麼，就多斬幾次！",
  ui_story_5084_50841002_14_dialog_content = "住、住手！妳是殺不死我的！",
  ui_story_5084_50841002_15_dialog_content = "我沒有想過要殺死你。但頭顱落地的痛楚，你承受得住嗎？",
  ui_story_5084_50841002_16_dialog_content = "你將嘶吼著求饒！<size=45>會自己乞求解脫！</size>",
  ui_story_5084_50841002_17_dialog_content = "（維多利亞居然也有這麼殘酷的一面……）",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>幽深的墓穴內，依牆的棺木猛然炸開，從中走出一個人。</color>",
  ui_story_5084_50841002_19_dialog_content = "不必費勁折磨他了。",
  ui_story_5084_50841002_20_dialog_content = "？！",
  ui_story_5084_50841002_21_dialog_content = "威、威廉？！",
  ui_story_5084_50841002_22_dialog_content = "怎麼可能！你明明早就死了！",
  ui_story_5084_50841002_23_dialog_content = "……你果然還活著。",
  ui_story_5084_50841002_24_dialog_content = "不，我曾死去，卻在時間長流中漂泊多年，如今終於稍微領悟了主的用意。",
  ui_story_5084_50841002_25_dialog_content = "三年前的聖鳴節……是你。",
  ui_story_5084_50841002_26_dialog_content = "是命運引導我來到此時此地。三年，不過一瞬。這或許是我最後一站了。",
  ui_story_5084_50841002_27_dialog_content = "……？！",
  ui_story_5084_50841002_28_dialog_content = "（原來如此，我看見的果然是不一樣的威廉先生！）",
  ui_story_5084_50841002_29_dialog_content = "（獻祭維多利亞、設下這一切的人，都是這位曾經死去的威廉先生！）",
  ui_story_5084_50841002_30_dialog_content = "拿去吧。這是命運自己想跟隨妳。",
  ui_story_5084_50841002_31_dialog_content = "這是……血色邪典？",
  ui_story_5084_50841002_32_dialog_content = "不，這並非我熟知的那本聖物。",
  ui_story_5084_50841002_33_dialog_content = "嶄新的邪典，必須交給未來的引路者。",
  ui_story_5084_50841002_34_dialog_content = "拿好，這是只有妳能駕馭的力量。",
  ui_story_5084_50841002_35_dialog_content = "用它殺死眼前的小丑吧。",
  ui_story_5084_50841002_36_dialog_content = "……不。",
  ui_story_5084_50841002_37_dialog_content = "……？！",
  ui_story_5084_50841002_38_dialog_content = "我不需要由你交給我的力量。殺死你的人是他們。你的仇，自己去報。",
  ui_story_5084_50841002_39_dialog_content = "到底怎麼回事？我們竟然沒有一戰之力。",
  ui_story_5084_50841002_40_dialog_content = "那個威廉，不是我們殺死的威廉。",
  ui_story_5084_50841002_41_dialog_content = "威廉，你死後到底發生了什麼事？至少告訴我這個！把你看到的真理告訴我！",
  ui_story_5084_50841002_42_dialog_content = "——吵死了！",
  ui_story_5084_50841002_43_dialog_content = "真理不需要你理解！",
  ui_story_5084_50841002_44_dialog_content = "只需以你們的血，償還你們對瓦拉吉祖先的褻瀆之罪！",
  ui_story_5084_50841002_45_dialog_content = "瓦……拉吉……",
  ui_story_5084_50841002_46_dialog_content = "（一劍就消滅了兩位家主，威廉先生的實力好強！）",
  ui_story_5084_50841002_47_dialog_content = "威廉·瓦拉吉，這具棺木本是先祖安息的地方。在你身上，究竟發生了什麼事？",
  ui_story_5084_50841002_48_dialog_content = "你為何消失，如今又為什麼能再次出現？",
  ui_story_5084_50841002_49_dialog_content = "你是復活了，還是一抹幻影？",
  ui_story_5084_50841002_50_dialog_content = "妳還是如我記憶中一樣，一開口就是諸多問題。",
  ui_story_5084_50841002_51_dialog_content = "可惜事過境遷，我也早已死去，討論這些也沒有意義了。",
  ui_story_5084_50841002_52_dialog_content = "永別了，維多利亞。",
  ui_story_5084_50841002_53_dialog_content = "（兩人明明都在乎對方，好不容易才見到一面，怎麼能這麼快結束對話……）",
  ui_story_5084_50841002_54_dialog_content = "威廉先生，請等一下！",
  ui_story_5084_50841002_55_dialog_content = "空裔……",
  ui_story_5084_50841002_56_dialog_content = "你是……",
  ui_story_5084_50841002_57_dialog_content = "那個聲音？",
  ui_story_5084_50841002_58_dialog_content = "啊，原來如此。",
  ui_story_5084_50841002_59_dialog_content = "這，就是命運啊。",
  ui_story_5084_50841002_60_dialog_content = "命運，呵呵。",
  ui_story_5084_50841002_61_dialog_content = "威廉先生！就算你把這些事情稱為「命運」……",
  ui_story_5084_50841002_62_dialog_content = "但那時的你聽見「命運」的指引，仍追尋你信奉的真理，因擔心著維多利亞的未來才前往墓穴。",
  ui_story_5084_50841002_63_dialog_content = "維多利亞走進這安排好的「命運」之中，寧願承受囈語，也要冒險戴上戒指，查明你的去向。",
  ui_story_5084_50841002_64_dialog_content = "連時間都跨越了，你們真的不能跨越隔閡，好好聊一聊嗎？",
  ui_story_5084_50841002_65_dialog_content = "對付那些家主，你們戰鬥、揮劍的時候，我切實看到了推動著你們行動的情感。",
  ui_story_5084_50841002_66_dialog_content = "抱歉，我可能又說了不該說的話，永遠改變了什麼……",
  ui_story_5084_50841002_67_dialog_content = "但我此刻無比相信，自己接下來要說出的話——",
  ui_story_5084_50841002_68_dialog_content = "我覺得語言才是最好的祕法！什麼也不說的話，就永遠錯過瞭解對方的機會了。",
  ui_story_5084_50841002_69_dialog_content = "……",
  ui_story_5084_50841002_70_dialog_content = "……",
  ui_story_5084_50841002_71_dialog_content = "我想，問題和答案或許並不重要，重要的是兩位現在同時站在這裡。",
  ui_story_5084_50841002_72_dialog_content = "不論是否是「命運」的安排，兩位每一次行動，應該都是發自肺腑的選擇。",
  ui_story_5084_50841002_73_dialog_content = "空裔，你啊……",
  ui_story_5084_50841002_74_dialog_content = "呵呵，要是世上的人們都如你這般赤誠，便不會輕易誤入歧途了。",
  ui_story_5084_50841002_75_dialog_content = "赤誠，那是只有空裔這樣的年輕人才擁有的寶藏了。",
  ui_story_5084_50841002_76_dialog_content = "唉。該從何說起呢？",
  ui_story_5084_50841002_77_dialog_content = "我已經在時光之外漂泊許久了。從未如此渴望安息。",
  ui_story_5084_50841002_78_dialog_content = "維多利亞，我現在終於能夠明白，兄長祈求的長眠了。我想，如今的妳一定也能明白。",
  ui_story_5084_50841002_79_dialog_content = "發自肺腑的選擇我曾有過很多，多過天上的星辰。",
  ui_story_5084_50841002_80_dialog_content = "但我想說，謝謝妳。正因妳讓瓦拉吉家族從血脈的詛咒中解脫，我才得以在未來順利死去。",
  ui_story_5084_50841002_81_dialog_content = "你居然也會向人道謝。不過，讓瓦拉吉家族從血脈詛咒中解脫的人，是我嗎？",
  ui_story_5084_50841002_82_dialog_content = "空裔說的沒錯。能看見妳走到這裡，問題和答案早已不——",
  ui_story_5084_50841002_83_dialog_content = "當然重要！",
  ui_story_5084_50841002_84_dialog_content = "真理因人而異，未有最終的答案，只有不斷追尋的信念為真實。",
  ui_story_5084_50841002_85_dialog_content = "……那，繼續說下去吧。",
  ui_story_5084_50841002_86_dialog_content = "這世上有「分歧」，有「苦難」。長生的種族囿於對死的渴望，蜉蝣卻又祈求更多的未來。",
  ui_story_5084_50841002_87_dialog_content = "這個艾歐里亞，真的有<color=#FFB400>救世主</color>嗎？",
  ui_story_5084_50841002_88_dialog_content = "我曾目睹預言中的巨大苦難，但也因而確信了<color=#FFB400>救贖</color>確實存在。",
  ui_story_5084_50841002_89_dialog_content = "所以我追尋的真理，乃是足以消弭天下墮落之種的<color=#FFB400>救贖</color>。",
  ui_story_5084_50841002_90_dialog_content = "跨越物質的限制，意識的禁錮，完成至高的進化，光靈邁向群星，僅有無上的真理能夠抵達。",
  ui_story_5084_50841002_91_dialog_content = "一如啟示所揭露那般，你果然已經成長，獲得了足夠的資格。",
  ui_story_5084_50841002_92_dialog_content = "你說的「群星」，在我死去時，在黑暗中曾目睹一道河流。",
  ui_story_5084_50841002_93_dialog_content = "世間的因果在那之上流淌，稍有波動便有可能釀成大難。",
  ui_story_5084_50841002_94_dialog_content = "吾等長生血族窮盡近似無限的時光，所追尋的不過是那河流中的一粒塵沙。",
  ui_story_5084_50841002_95_dialog_content = "即使如此，我追尋的執念仍令我抵達那條河流。",
  ui_story_5084_50841002_96_dialog_content = "故而，我堅定了我的真理。踐行之路雖有無盡艱辛，但掃清苦難，心願也必將左右因果流轉。",
  ui_story_5084_50841002_97_dialog_content = "你認為，你的信念仍舊長存，超越你所仇視的「命運桎梏」？",
  ui_story_5084_50841002_98_dialog_content = "我服從它，我踐行它，然後我將找尋出窺破命運的契機，親手扭轉因果的流轉。",
  ui_story_5084_50841002_99_dialog_content = "妳走吧，維多利亞。踐行妳的道路，解決沿途的阻礙。",
  ui_story_5084_50841002_100_dialog_content = "那是當然。",
  ui_story_5084_50841002_101_dialog_content = "在戴維讓我們的小鎮變成死域之前，妳必須阻止這一切。",
  ui_story_5084_50841002_102_dialog_content = "你又要去哪裡？",
  ui_story_5084_50841002_103_dialog_content = "我漂泊於時間之外已久，不能肆意改變，除非命運如此。",
  ui_story_5084_50841002_104_dialog_content = "沒想到我們最後還是完成了那次「對話」，叔父。",
  ui_story_5084_50841002_105_dialog_content = "維多利亞，妳成長了。真好。",
  ui_story_5084_50841002_106_dialog_content = "這本「災典」就給妳吧。妳會需要它的。",
  ui_story_5084_50841002_107_dialog_content = "我已擁有探求真理所需的力量，於我無益。",
  ui_story_5084_50841002_108_dialog_content = "命運會指引你們相遇的。",
  ui_story_5084_50841002_109_dialog_content = "維多利亞·瓦拉吉，再見了。",
  ui_story_5084_50841002_110_dialog_content = "你的信徒……那位「聖釘」，孺子可教。",
  ui_story_5084_50841002_111_dialog_content = "未來的真理結社，就交給你們了。",
  ui_story_5084_50841002_112_dialog_content = "我們還會再見嗎？",
  ui_story_5084_50841002_113_dialog_content = "我已完成祂給予的試煉，現在，我要為自己做一些事。",
  ui_story_5084_50841002_114_dialog_content = "一切結束以後，在這裡見吧。",
  ui_story_5084_50841002_115_dialog_content = "還有，謝謝你用赤誠指引了那時的我，來自未來的空裔。",
  ui_story_5084_50841101_1_dialog_content = "都怪婆婆啦，堅持要我聽完她想跟真理之主說的話之後，才肯放我出門。",
  ui_story_5084_50841101_2_dialog_content = "現在只能擠在這麼後面，根本看不見遊行隊伍。",
  ui_story_5084_50841101_3_dialog_content = "婆婆她已經走不動路，沒辦法來參加聖鳴節了。",
  ui_story_5084_50841101_4_dialog_content = "但是她為信徒做了一輩子的衣服，希望妳能帶著她的那一份心意前來。",
  ui_story_5084_50841101_5_dialog_content = "待會媽媽會把妳舉高，不過妳必須記住婆婆的話，要虔誠，不能當作玩耍哦。",
  ui_story_5084_50841101_6_dialog_content = "我知道了啦。",
  ui_story_5084_50841101_7_dialog_content = "是這條熟悉的街道！我就是在這裡遇到PlayerName的。",
  ui_story_5084_50841101_8_dialog_content = "但人那麼多，我們要上哪去找聖釘呢？",
  ui_story_5084_50841101_9_dialog_content = "梅，你們當時也有看到這些穿著怪異斗篷的人嗎？",
  ui_story_5084_50841101_10_dialog_content = "我想一下喔。",
  ui_story_5084_50841101_11_dialog_content = "啊——！！！",
  ui_story_5084_50841101_12_dialog_content = "那是……？快過去看看！",
  ui_story_5084_50841101_13_dialog_content = "死徒！是死徒啊！",
  ui_story_5084_50841101_14_dialog_content = "偉大的主，我知道是您在懲罰我……我是偷看了姐姐的日記，並當眾拆穿她的虛偽……",
  ui_story_5084_50841101_15_dialog_content = "但真理結社的家主都說我生了病，我的鮮血已經沒有受您垂青的可能。",
  ui_story_5084_50841101_16_dialog_content = "我會割下我的肉作為懲罰！",
  ui_story_5084_50841101_17_dialog_content = "媽媽……？",
  ui_story_5084_50841101_18_dialog_content = "但請別奪去我唯一的女兒，她是無罪的！",
  ui_story_5084_50841101_19_dialog_content = "主啊！",
  ui_story_5084_50841101_20_dialog_content = "這些是您派來懲罰我的對吧？偉大的真理之主！",
  ui_story_5084_50841101_21_dialog_content = "我明白，我絕對不會皺一下眉頭！請您懲罰我！",
  ui_story_5084_50841101_22_dialog_content = "——！",
  ui_story_5084_50841101_23_dialog_content = "媽媽！",
  ui_story_5084_50841101_24_dialog_content = "啊……！！！",
  ui_story_5084_50841101_25_dialog_content = "快、快跑啊！",
  ui_story_5084_50841101_26_dialog_content = "這些斗篷怪物，還有沿街流過來的鮮血……有人遇害了！",
  ui_story_5084_50841101_27_dialog_content = "梅，要準備戰鬥了！",
  ui_story_5084_50841101_28_dialog_content = "果然，從維多利亞大人開始，「命運」允許了我們的干涉。",
  ui_story_5084_50841101_29_dialog_content = "沒問題！壞孩子，受罰吧！",
  ui_story_5084_50841101_30_dialog_content = "不痛！",
  ui_story_5084_50841101_31_dialog_content = "還有很多！",
  ui_story_5084_50841101_32_dialog_content = "啊……！！！",
  ui_story_5084_50841101_33_dialog_content = "媽媽啊——！",
  ui_story_5084_50841101_34_dialog_content = "迷途的羔羊，別怕……「聖血」就要凝聚成形……",
  ui_story_5084_50841101_35_dialog_content = "受召者先生……是您！您為什麼在傷害自己？",
  ui_story_5084_50841101_36_dialog_content = "傻孩子，這不是我的力量。我不是受召者，我是聖釘。",
  ui_story_5084_50841101_37_dialog_content = "真理之主告訴我不要自責和憐憫。",
  ui_story_5084_50841101_38_dialog_content = "即使您的母親像我一樣是罪惡之人，也由我——",
  ui_story_5084_50841101_39_dialog_content = "替罪惡之人回答！",
  ui_story_5084_50841101_40_dialog_content = "先生？這是什麼啊……？",
  ui_story_5084_50841101_41_dialog_content = "是罪孽，亦是祝福……",
  ui_story_5084_50841101_42_dialog_content = "它，是導師所說的「聖血」之力！",
  ui_story_5084_50841101_43_dialog_content = "主正從我的身體裡流過，滾燙而鮮活，燃燒我，讓我感到無比溫熱！",
  ui_story_5084_50841101_44_dialog_content = "迷途的羔羊，看啊！",
  ui_story_5084_50841101_45_dialog_content = "真理之主會赦免我們的罪孽！",
  ui_story_5084_50841101_46_dialog_content = "......！",
  ui_story_5084_50841101_47_dialog_content = "是您，那時的受召者先生！想必您已經成為主的聖徒了！",
  ui_story_5084_50841101_48_dialog_content = "不，別這麼稱呼我，我還——",
  ui_story_5084_50841101_49_dialog_content = "您還穿著這身衣服。我和媽媽、婆婆一起為您縫製的聖徒之衣。",
  ui_story_5084_50841101_50_dialog_content = "感謝您和您家人的饋贈，我才得以蛻變為這個模樣。",
  ui_story_5084_50841101_51_dialog_content = "當時或許威廉大人有別的考量，但今年的受召者一定是您！",
  ui_story_5084_50841101_52_dialog_content = "導師向我傳遞的也是崇高的真理。如今我已充滿感激。",
  ui_story_5084_50841101_53_dialog_content = "趁還沒有危險，快離開這裡吧。一定會沒事的。",
  ui_story_5084_50841101_54_dialog_content = "嗯！願真理祝福你，「聖徒」聖釘先生。",
  ui_story_5084_50841101_55_dialog_content = "願真理祝福您，聖釘先生！",
  ui_story_5084_50841101_56_dialog_content = "願真理祝福妳們。",
  ui_story_5084_50841101_57_dialog_content = "「聖徒」聖釘先生！",
  ui_story_5084_50841101_58_dialog_content = "我們遠遠就看到你消滅了那怪物。",
  ui_story_5084_50841101_59_dialog_content = "喔，是梅，還有浮士德。好久不見。",
  ui_story_5084_50841101_60_dialog_content = "你竟然沒事！",
  ui_story_5084_50841101_61_dialog_content = "我和PlayerName都好擔心你！",
  ui_story_5084_50841101_62_dialog_content = "都是當時的我不自量力。讓你們牽掛了，我懺悔……",
  ui_story_5084_50841101_63_dialog_content = "可是，你剛才的力量看起來好驚人！難道是因為這身衣服嗎？",
  ui_story_5084_50841101_64_dialog_content = "想必也有原因吧。這三年間，我一直穿著前面那對裁縫鋪母女為我縫的衣服。",
  ui_story_5084_50841101_65_dialog_content = "你……你沒有去任何地方？你就在瓦拉吉鎮待了三年？！",
  ui_story_5084_50841101_66_dialog_content = "原來都修行三年了啊……導師還真是帶我去過鎮內外不少地方呢。",
  ui_story_5084_50841101_67_dialog_content = "導師？",
  ui_story_5084_50841101_68_dialog_content = "這麼說，你的「稀血」會凝聚成新的形狀，是因為跟著這位導師修行？",
  ui_story_5084_50841101_69_dialog_content = "是啊。我的導師說，「稀血」不是詛咒。",
  ui_story_5084_50841101_70_dialog_content = "「在彼失去，在此得到。在彼贖罪，在此獲膏澤。」",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>三年前……</color>",
  ui_story_5084_50841102_2_dialog_content = "偉大的真理之主，您的信徒聖釘再次請求您賜我解脫。",
  ui_story_5084_50841102_3_dialog_content = "我的體內流著污穢之血，早已做好準備……",
  ui_story_5084_50841102_4_dialog_content = "這裡是……",
  ui_story_5084_50841102_5_dialog_content = "雖然維多利亞大人曾說虔誠會為我指引方向，但我願意犧牲……",
  ui_story_5084_50841102_6_dialog_content = "我會……",
  ui_story_5084_50841102_7_dialog_content = "……",
  ui_story_5084_50841102_8_dialog_content = "主？",
  ui_story_5084_50841102_9_dialog_content = "是您！偉大的真理之主！",
  ui_story_5084_50841102_10_dialog_content = "你剛才說，維多利亞大人？",
  ui_story_5084_50841102_11_dialog_content = "我是罪惡的，但不關維多利亞大人的事。",
  ui_story_5084_50841102_12_dialog_content = "維多利亞大人接納我，真理結社的同伴們愛護我，但除了用骯髒的血污染世界之外，我這個人別無用處。",
  ui_story_5084_50841102_13_dialog_content = "真理結社的領袖維多利亞，以及你，真理結社的成員？",
  ui_story_5084_50841102_14_dialog_content = "聖釘。我叫聖釘，偉大的主。",
  ui_story_5084_50841102_15_dialog_content = "這墓穴裡，只有你一人？",
  ui_story_5084_50841102_16_dialog_content = "有維多利亞大人、浮士德、梅、空裔。我們進入星空墓穴後，便走散了。",
  ui_story_5084_50841102_17_dialog_content = "一定是您把他們引到其他地方去了。他們善良又勇敢……",
  ui_story_5084_50841102_18_dialog_content = "「身為真理的引路人。」",
  ui_story_5084_50841102_19_dialog_content = "指引的是你們，真理結社竟然還有空裔加入？",
  ui_story_5084_50841102_20_dialog_content = "「真理已在他心中顯現。他是真理結社的變革之力，是受到真理祝福之人。」",
  ui_story_5084_50841102_21_dialog_content = "受到真理祝福？",
  ui_story_5084_50841102_22_dialog_content = "你想向真理之主懺悔什麼？",
  ui_story_5084_50841102_23_dialog_content = "懺悔。懺悔我自出生以來的罪過。",
  ui_story_5084_50841102_24_dialog_content = "不信您看，只有我這樣的怪物身上，才會流出這樣的血液。我有罪。",
  ui_story_5084_50841102_25_dialog_content = "一派胡言。",
  ui_story_5084_50841102_26_dialog_content = "您、您說什麼？",
  ui_story_5084_50841102_27_dialog_content = "我說，太陽還未下山，我有時間聽你講述自己罪孽深重的過往。",
  ui_story_5084_50841102_28_dialog_content = "不用管我做什麼，只管說吧。",
  ui_story_5084_50841102_29_dialog_content = "但是我有一個要求：把那釘子收起來。這裡是瓦拉吉墓穴，不得濺出一滴鮮血。",
  ui_story_5084_50841102_30_dialog_content = "是！我偉大的真理之主。",
  ui_story_5084_50841102_31_dialog_content = "還有，我不是真理之主。",
  ui_story_5084_50841102_32_dialog_content = "那您是？",
  ui_story_5084_50841102_33_dialog_content = "威廉。當然，我有一個配不上我的姓：瓦拉吉。",
  ui_story_5084_50841102_34_dialog_content = "瓦、瓦拉吉！和維多利亞大人同樣的尊姓！",
  ui_story_5084_50841102_35_dialog_content = "呵呵，尊姓？不過是些震懾人心的代號罷了。",
  ui_story_5084_50841102_36_dialog_content = "如今的我，不僅與真理結社淵源匪淺，更在時間之外漂泊已久。",
  ui_story_5084_50841102_37_dialog_content = "來到我面前的你啊，先告訴我，是誰稱你為怪物？",
  ui_story_5084_50841102_38_dialog_content = "我的弟弟、我的父母親，整個家族都如此。",
  ui_story_5084_50841102_39_dialog_content = "僅僅因為你剛剛流出的所謂「稀血」？",
  ui_story_5084_50841102_40_dialog_content = "當然還因為我的所作所為。我傷害了我弟弟，令我的家族蒙羞。",
  ui_story_5084_50841102_41_dialog_content = "我弟弟他，本來和結社的朋友們一樣善良、勇敢。",
  ui_story_5084_50841102_42_dialog_content = "我則因為這力量飛黃騰達，甚至輕鬆在騎士對決中勝出。",
  ui_story_5084_50841102_43_dialog_content = "他的一切卻沒有那麼順利。",
  ui_story_5084_50841102_44_dialog_content = "敵對家族的公子對他下手，我沒有認清自己的力量，擅自上前保護他！",
  ui_story_5084_50841102_45_dialog_content = "結果……",
  ui_story_5084_50841102_46_dialog_content = "弟弟他一定是為了家族考慮吧。知道我這樣的人出現在那座純淨的高城裡，是何等的罪孽。",
  ui_story_5084_50841102_47_dialog_content = "於是他便給我解脫，讓我的「稀血」現出原形，讓我被逐出白夜城。",
  ui_story_5084_50841102_48_dialog_content = "似曾相識的經歷……",
  ui_story_5084_50841102_49_dialog_content = "然後你就四處輾轉流浪，最終受到維多利亞邀請，加入真理結社？",
  ui_story_5084_50841102_50_dialog_content = "沒錯。雖然我曾想在光靈與暗鬼的戰爭中死去……",
  ui_story_5084_50841102_51_dialog_content = "不過，主想必是認為我罪孽深重，讓「稀血」一次次把我從昏死中拉回來。",
  ui_story_5084_50841102_52_dialog_content = "祂在提醒我，我的懺悔還不夠，還沒有辦法回到真理之主的懷抱。",
  ui_story_5084_50841102_53_dialog_content = "……",
  ui_story_5084_50841102_54_dialog_content = "我說太多了嗎？抱歉，威廉先生。我剛剛還以為我終於獲得原諒，回到主的懷抱了。",
  ui_story_5084_50841102_55_dialog_content = "聽下來，你的故事無非就是你生於貴族之家，天賦異稟。",
  ui_story_5084_50841102_56_dialog_content = "而你無能的弟弟對你心生不滿，想要奪得家主的位置，於是千方百計要謀害你。",
  ui_story_5084_50841102_57_dialog_content = "他現在繼承你們家主的席位了，沒錯吧？",
  ui_story_5084_50841102_58_dialog_content = "那是我弟弟應得的。而且他也沒有「謀害」……",
  ui_story_5084_50841102_59_dialog_content = "呵，我很懷疑。白夜城的子弟，善良？勇敢？",
  ui_story_5084_50841102_60_dialog_content = "真理結社的第十二位家主，正是一位被白夜城排斥的異端。",
  ui_story_5084_50841102_61_dialog_content = "若是沒有這名異端，就不會有如今的真理結社。",
  ui_story_5084_50841102_62_dialog_content = "我的確是受白夜城排斥的異端，但弟弟他……",
  ui_story_5084_50841102_63_dialog_content = "告訴我，你離開之時，他是什麼表情？",
  ui_story_5084_50841102_64_dialog_content = "……",
  ui_story_5084_50841102_65_dialog_content = "我想你一輩子都不會忘記，這位不惜當眾毀滅你的弟弟，看著你離開的表情吧？",
  ui_story_5084_50841102_66_dialog_content = "弟弟他……笑著祝福我。",
  ui_story_5084_50841102_67_dialog_content = "哈哈哈哈！無論實質上是欺辱或迫害，那些人總會找到罪由。",
  ui_story_5084_50841102_68_dialog_content = "於是你以為自己罪孽深重，加入了真理結社，這麼多年仍信奉著那套懺悔、自殘的陋習。",
  ui_story_5084_50841102_69_dialog_content = "懺悔的根源是自我厭惡。厭惡「稀血」的人，是你自己！",
  ui_story_5084_50841102_70_dialog_content = "而自我厭惡的根源，是你對那邪惡之人的期待。邪惡之人對你口出惡言，你還信以為真。",
  ui_story_5084_50841102_71_dialog_content = "但我告訴你。「稀血」不是怪物，是真理之主的祝福。",
  ui_story_5084_50841102_72_dialog_content = "稀血助你殺滅暗鬼就是證據。聽清楚，你沒有自我厭惡的理由。",
  ui_story_5084_50841102_73_dialog_content = "聖釘，是他不配做你弟弟。但悲劇的是，你卻是一個好哥哥。",
  ui_story_5084_50841102_74_dialog_content = "兄弟決裂，彼此反目成仇。威廉·瓦拉吉，命運安排我們在此相遇。",
  ui_story_5084_50841102_75_dialog_content = "還真是不忘再次嘲弄我啊！",
  ui_story_5084_50841102_76_dialog_content = "聖釘，你聽好。你才是善良、勇敢之人。「神聖」吧，神聖怎麼樣？就像你的名字一樣。",
  ui_story_5084_50841102_77_dialog_content = "你若是將這「稀血」之力用於加護他人，便能獲得真正的救贖。",
  ui_story_5084_50841102_78_dialog_content = "您能這麼想很勇敢，但我……",
  ui_story_5084_50841102_79_dialog_content = "你可以。",
  ui_story_5084_50841102_80_dialog_content = "……",
  ui_story_5084_50841102_81_dialog_content = "主不會偏袒任何人。若你心中無法原諒自己，主又怎麼能救贖你？",
  ui_story_5084_50841102_82_dialog_content = "記住，你必須先認可自己，主才會認可你。",
  ui_story_5084_50841102_83_dialog_content = "威廉先生，您為什麼對我說這些？",
  ui_story_5084_50841102_84_dialog_content = "因為我知道，我們此刻的相逢，永遠改寫了命運。",
  ui_story_5084_50841102_85_dialog_content = "是主將你送到我身邊。我敢確信。",
  ui_story_5084_50841102_86_dialog_content = "所以，現在可不是自我了結的時候，聖釘，而是你奉獻一生的開始。你願不願意隨我修行？",
  ui_story_5084_50841102_87_dialog_content = "只要能洗清身上的罪孽，無論如何我都願意。",
  ui_story_5084_50841102_88_dialog_content = "好，那麼即刻開始吧。我們還有很多事情要做，但不是這裡。",
  ui_story_5084_50841102_89_dialog_content = "這裡是結束的時間。而你修行的三年是始於那年的聖鳴節，從你們的到來開始。",
  ui_story_5084_50841102_90_dialog_content = "你的領袖回到了那裡。躺進我身後的棺木中，想著瓦拉吉鎮上的聖鳴節，那裡有你的同伴。",
  ui_story_5084_50841102_91_dialog_content = "等你再次睜開眼後，就到聖鳴節的儀式去找我。我會讓你成為儀式的受召者，接受真理的祝福。",
  ui_story_5084_50841102_92_dialog_content = "我應該怎麼去到那裡呢？",
  ui_story_5084_50841102_93_dialog_content = "你的信念，聖釘。",
  ui_story_5084_50841102_94_dialog_content = "你能來到這裡，正是因你有著懺悔的信念。用自己的身體去感受吧。",
  ui_story_5084_50841102_95_dialog_content = "直到你能夠祝福自身的存在時，哪怕只有一刻，你便發現了真理。",
  ui_story_5084_50841102_96_dialog_content = "您是說，信念？",
  ui_story_5084_50841102_97_dialog_content = "沒錯，從現在起，我就是你的導師了。",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>瓦拉吉鎮，裁縫鋪門口</color>",
  ui_story_5084_50841102_99_dialog_content = "怎麼……會來到這裡？",
  ui_story_5084_50841102_100_dialog_content = "這位先生，您也是來拿慶典長袍的嗎？",
  ui_story_5084_50841102_101_dialog_content = "慶典長袍？",
  ui_story_5084_50841102_102_dialog_content = "難怪當時你說著我們聽不懂的話，原來你早就認識那位威廉大人了。",
  ui_story_5084_50841102_103_dialog_content = "而且還是更神祕的那一位。",
  ui_story_5084_50841102_104_dialog_content = "我竟然真以為自己獲選成為受召者，還帶著這樣的想法，進入了真理殿堂。",
  ui_story_5084_50841102_105_dialog_content = "想來還是覺得發生的一切很不可思議。初遇導師時，我不知道是什麼時候。",
  ui_story_5084_50841102_106_dialog_content = "導師將我送回聖鳴節當天，那位導師卻不認識我。",
  ui_story_5084_50841102_107_dialog_content = "後來呢，聖釘？你被威廉大人扔出教堂之後，發生了什麼事？",
  ui_story_5084_50841102_108_dialog_content = "……",
  ui_story_5084_50841102_109_dialog_content = "啊，罪惡的血液全部流盡吧……我不再祈求主的豁免。",
  ui_story_5084_50841102_110_dialog_content = "我有罪，我罪孽深重……",
  ui_story_5084_50841102_111_dialog_content = "我無非就是為世界帶來災難的怪物，即使來到這裡也不例外。",
  ui_story_5084_50841102_112_dialog_content = "為了急著參加聖鳴節，辜負了那對裁縫鋪母女的心意。",
  ui_story_5084_50841102_113_dialog_content = "而她們遇到我之後，從此失去賺錢的機會。",
  ui_story_5084_50841102_114_dialog_content = "剛剛那些人看穿了我的本質。他們不承認我是受召者，想要置我於死地。",
  ui_story_5084_50841102_115_dialog_content = "我不是受召者。我害得導師與同門起衝突……",
  ui_story_5084_50841102_116_dialog_content = "無論去到哪裡，我都會受到厭棄……",
  ui_story_5084_50841102_117_dialog_content = "呃啊……啊……",
  ui_story_5084_50841102_118_dialog_content = "手腳開始感到麻木了。從剛剛的寒冷，到現在竟會感到一股久違的溫暖……",
  ui_story_5084_50841102_119_dialog_content = "也好。",
  ui_story_5084_50841102_120_dialog_content = "我會帶著這種罪惡的心靜靜死去，不再為這世界帶來災難。",
  ui_story_5084_50841102_121_dialog_content = "我......",
  ui_story_5084_50841102_122_dialog_content = "我在想，我是不是沒有把話說清楚。",
  ui_story_5084_50841102_123_dialog_content = "......？",
  ui_story_5084_50841102_124_dialog_content = "如此美妙的「稀血」之力，就那麼令你厭惡？",
  ui_story_5084_50841102_125_dialog_content = "導師？我的導師！您、您沒事？！",
  ui_story_5084_50841102_126_dialog_content = "別動，讓我看看你傷口癒合的狀況。",
  ui_story_5084_50841102_127_dialog_content = "剛剛你遇到的，是我。但不是最開始，或是現在的我。",
  ui_story_5084_50841102_128_dialog_content = "我始終在此觀察著裡面發生的事情，實在看不出你有何罪過。",
  ui_story_5084_50841102_129_dialog_content = "我……您一定看得出來，我身上有怪物。",
  ui_story_5084_50841102_130_dialog_content = "怪物？即使以我過去的眼光來看，你這能力也強得嚇人，而且注定會和真理結社結下不解之緣。",
  ui_story_5084_50841102_131_dialog_content = "要知道，我所看到的真理結社的未來，是由一群怪異又不失端莊，感性又不失智慧之人組成。",
  ui_story_5084_50841102_132_dialog_content = "只要你持續探索自身的獨特力量，時間的長流一定會把你推到正確的位置，讓你遇到正確的人。",
  ui_story_5084_50841102_133_dialog_content = "我說過你接下來要跟我一起修行，那麼你的親身經歷，也是修行的一部分。",
  ui_story_5084_50841102_134_dialog_content = "擅自想帶著罪惡的心赴死，看來你沒把我說的話聽進去啊。",
  ui_story_5084_50841102_135_dialog_content = "我的導師，請懲罰我吧！是我沒有踐行承諾。",
  ui_story_5084_50841102_136_dialog_content = "罷了，此前的你心靈受盡屈辱，身體也跟著受罪、漂泊。這不怪你。",
  ui_story_5084_50841102_137_dialog_content = "但如今你來到了正確的地方，是時候運用你獨特的能力發光發熱了。",
  ui_story_5084_50841102_138_dialog_content = "我……？",
  ui_story_5084_50841102_139_dialog_content = "仔細想想，在不考慮他人的情況下，這「稀血」可曾傷害過你？",
  ui_story_5084_50841102_140_dialog_content = "……",
  ui_story_5084_50841102_141_dialog_content = "養尊處優之人不惜陷害彼此也要爭搶的寶物，或許也是顛沛之人的救命稻草。",
  ui_story_5084_50841102_142_dialog_content = "你傷害自己的靈魂，用他人的罪惡綁架自己，也因此辜負了「稀血」想拯救你和他人的心。",
  ui_story_5084_50841102_143_dialog_content = "你為什麼不願意相信，這「稀血」能夠殺害怪物，拯救世人呢？",
  ui_story_5084_50841102_144_dialog_content = "別人會避開我，會討厭我的……",
  ui_story_5084_50841102_145_dialog_content = "又在提別人。聽清楚，這麼想的是過去的你。未來不要再這樣了。",
  ui_story_5084_50841102_146_dialog_content = "「只要能洗清身上的罪孽，無論如何我都願意」，這是你自己說的。那麼第一步，就相信自己沒有背負罪孽。",
  ui_story_5084_50841102_147_dialog_content = "做得到嗎？",
  ui_story_5084_50841102_148_dialog_content = "導師？",
  ui_story_5084_50841102_149_dialog_content = "好了，我知道聰慧的你一定明白我的意思。",
  ui_story_5084_50841102_150_dialog_content = "隨我前往我的住所吧。那是個適合隱修的地方。",
  ui_story_5084_50841102_151_dialog_content = "從那裡出發，你可以到各個城鎮尋找迷途的羔羊。",
  ui_story_5084_50841102_152_dialog_content = "用你的力量救助他們、指引他們，讓他人祝福你的「稀血」。",
  ui_story_5084_50841102_153_dialog_content = "讓「稀血」沐浴在真理的祝福中，假以時日，你便能領會這場修行。",
  ui_story_5084_50841102_154_dialog_content = "聖釘明白了。",
  ui_story_5084_50841102_155_dialog_content = "所以這三年中，我一直在四處漂泊。收斂自己的脾性，傾聽他人的聲音，治癒他人的痛苦。",
  ui_story_5084_50841102_156_dialog_content = "在此期間，我發現身上的「稀血」之力，漸漸產生了變化。",
  ui_story_5084_50841102_157_dialog_content = "但是直到剛才幫助那對裁縫母女時，我才察覺，這三年的修行有了成果。",
  ui_story_5084_50841102_158_dialog_content = "加入真理結社多年，我總是緊閉自己的耳朵，一個勁地訴說和懺悔。",
  ui_story_5084_50841102_159_dialog_content = "導師發現我罪惡的根源，是我的滔滔不絕阻絕了真理之聲。",
  ui_story_5084_50841102_160_dialog_content = "我消極的話語形塑了這種思想，讓我的罪孽越發深重。",
  ui_story_5084_50841102_161_dialog_content = "我對真理的領悟過於膚淺，所以真理才不願在我身上顯化。",
  ui_story_5084_50841102_162_dialog_content = "真理，原來就存在於我的信念裡啊。",
  ui_story_5084_50841102_163_dialog_content = "真理和痛苦一樣，從來不會偏袒任何人。",
  ui_story_5084_50841102_164_dialog_content = "在彼失去，那是我該失去的。在此得到，也是我該得到的。",
  ui_story_5084_50841102_165_dialog_content = "在彼贖罪，必須有實質的罪過。在此獲得聖血膏澤，都是信徒給我的祝福。",
  ui_story_5084_50841102_166_dialog_content = "聖釘先生說的話，雖然梅有一半都聽不懂……",
  ui_story_5084_50841102_167_dialog_content = "但看到你的神情，總覺得心裡面暖洋洋的，像洗了個舒服的熱水澡一樣。",
  ui_story_5084_50841102_168_dialog_content = "是導師讓我相信「稀血」並非罪孽，而是神聖。因為真理之主時刻籠罩著我。",
  ui_story_5084_50841102_169_dialog_content = "維多利亞大人一定會為你的成長感到高興。",
  ui_story_5084_50841102_170_dialog_content = "只是不知道她那邊順不順利。",
  ui_story_5084_50841102_171_dialog_content = "我相信維多利亞大人！更重要的是，我相信我能為維多利亞大人做重要的事！",
  ui_story_5084_50841102_172_dialog_content = "導師也說修行暫時告一段落。我必須利用這份力量，為真理結社做一件重要的事情。",
  ui_story_5084_50841102_173_dialog_content = "走吧，我想把我的喜悅傳遞給維多利亞大人，傳遞給更多信徒。",
  ui_story_5084_50841201_1_dialog_content = "就算再也沒人坐上列車，我也答應你，我一定會說服父親，帶你去艾斯特拉大陸旅行。",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>啪嗒啪嗒——</color>",
  ui_story_5084_50841201_3_dialog_content = "稍等一下，我去關窗戶。",
  ui_story_5084_50841201_4_dialog_content = "啊——！",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5084_50841201_6_dialog_content = "奇怪，最近這些討厭的傢伙老是在附近徘徊。",
  ui_story_5084_50841201_7_dialog_content = "但是父親只吩咐我關上窗戶，說一切都沒事。也不知道他現在在哪裡……",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>血月高懸於瓦拉吉鎮上空，如不捨晝夜的歷史鐘擺，為聖鳴節敲響午夜的鐘聲。</color>",
  ui_story_5084_50841201_9_dialog_content = "多麼如夢似幻的景象啊。真希望這樣的夜晚能出現在我生命中的每一天。",
  ui_story_5084_50841201_10_dialog_content = "您是說真理結社確立新領袖的今天嗎？有信徒說不久前有人遇害了。",
  ui_story_5084_50841201_11_dialog_content = "領袖更替不足為奇。我比較關心眾家主將非瓦拉吉血脈的信徒排除在外這件事。",
  ui_story_5084_50841201_12_dialog_content = "或許是因為，血月的紅輝只能映照那獨特的血脈。",
  ui_story_5084_50841201_13_dialog_content = "想要進入真理殿堂的棺木，聆聽主的教誨，本非我們能掌控之事。",
  ui_story_5084_50841201_14_dialog_content = "大可不必信奉這些血統論。三年前，真理之主就拒絕了瓦拉吉家的大小姐，轉而降臨在一位隱修的信徒身上。",
  ui_story_5084_50841201_15_dialog_content = "如今那人已成為聖徒，運用主的力量救贖著眾人。",
  ui_story_5084_50841201_16_dialog_content = "據說是外鎮的信徒。瓦拉吉鎮之外，或許有著更廣闊的真理之地。",
  ui_story_5084_50841201_17_dialog_content = "這件事確實對我們很有啟發。瓦拉吉鎮的家主似乎也面臨著一場變革。",
  ui_story_5084_50841201_18_dialog_content = "如果今夜宣佈的領袖真的是波菲里歐大人，那真理結社的未來將更加艱險。",
  ui_story_5084_50841201_19_dialog_content = "世界在變，真理也在變。願真理祝福本鎮。",
  ui_story_5084_50841201_20_dialog_content = "還沒看到維多利亞大人和PlayerName，他們該不會出事了吧？",
  ui_story_5084_50841201_21_dialog_content = "維多利亞大人從未食言，或許是因為人多眼雜，她要等信徒離開之後才會現身。",
  ui_story_5084_50841201_22_dialog_content = "不，如今的情況，我覺得維多利亞大人沒有遮掩的必要。",
  ui_story_5084_50841201_23_dialog_content = "PlayerName也在，應該一眼就能從人群中看見了。",
  ui_story_5084_50841201_24_dialog_content = "浮士德先生說得有道理！我有預感，今夜我將見證真理結社的奇蹟！",
  ui_story_5084_50841201_25_dialog_content = "哈哈，回去之後一定有很多故事可以跟蓮分享。",
  ui_story_5084_50841201_26_dialog_content = "只是鎮上頻頻傳出死徒傷人事件，信徒們卻為了這節日仍然冒險加入。",
  ui_story_5084_50841201_27_dialog_content = "畢竟是真理結社一直延續到晨光曆兩千年的盛會啊。",
  ui_story_5084_50841201_28_dialog_content = "我會時刻警惕，保護遊行儀式上的信徒安全。",
  ui_story_5084_50841201_29_dialog_content = "好久啊，維多利亞怎麼還沒來？",
  ui_story_5084_50841201_30_dialog_content = "你們看到了嗎？那位瓦拉吉家的大小姐來參加儀式了！",
  ui_story_5084_50841201_31_dialog_content = "是啊，還穿著一襲華麗的衣服……這種事情有違真理結社的規矩啊！",
  ui_story_5084_50841201_32_dialog_content = "（是回去換衣服了？人呢？）",
  ui_story_5084_50841201_33_dialog_content = "她一直都和她那位叔叔有隔閡，不遵守結社規矩也正常。",
  ui_story_5084_50841201_34_dialog_content = "瓦拉吉家族是不是真的要退出家主之位了？",
  ui_story_5084_50841201_35_dialog_content = "不可能吧？我聽說維多利亞小姐這次回來，正是為了領導真理結社。",
  ui_story_5084_50841201_36_dialog_content = "真的嗎？那三年前的聖鳴節上，她不是還……",
  ui_story_5084_50841201_37_dialog_content = "誰知道呢？畢竟是她進入棺木，而不是我們其他人。",
  ui_story_5084_50841201_38_dialog_content = "但不知道為什麼，幾百年過去了，我還是覺得真理結社必須由瓦拉吉家領導才安心。",
  ui_story_5084_50841201_39_dialog_content = "讓你久等了。",
  ui_story_5084_50841201_40_dialog_content = "哇……妳、妳還特地換上節日的禮服？",
  ui_story_5084_50841201_41_dialog_content = "不盡然。這套衣服應該是還惦念瓦拉吉家的人得知我在鎮上，特別送來的禮物。",
  ui_story_5084_50841201_42_dialog_content = "這做工，不是一兩個人能在短時間內完成的。",
  ui_story_5084_50841201_43_dialog_content = "背後的製作者，或許是想藉此對勢頭正盛的家主們表達不滿吧。",
  ui_story_5084_50841201_44_dialog_content = "所以為了回應這些信徒的期待，也證明妳具有能領導真理結社的力量……",
  ui_story_5084_50841201_45_dialog_content = "便打算穿著這套衣服，參加今晚的典禮？",
  ui_story_5084_50841201_46_dialog_content = "力量與衣服無關。無論是舊服還是新服，都配得上我的力量。",
  ui_story_5084_50841201_47_dialog_content = "不過這座歷史悠久的小鎮，也確實缺少鼓舞人心的變化。",
  ui_story_5084_50841201_48_dialog_content = "如同邪典、戒指、血月一樣，形式只是為了標記那些人們認為重要的瞬間。",
  ui_story_5084_50841201_49_dialog_content = "如果家主們忌憚這種惹人注目的變化，那我更要展現給他們看。",
  ui_story_5084_50841201_50_dialog_content = "畢竟在他們眼中，女人換身顯耀的造型，就象徵著揮別柔弱的過往。",
  ui_story_5084_50841201_51_dialog_content = "嗯……我只是想說，這套衣服很適合妳。",
  ui_story_5084_50841201_52_dialog_content = "PlayerName！PlayerName！",
  ui_story_5084_50841201_53_dialog_content = "是你們！",
  ui_story_5084_50841201_54_dialog_content = "哼哼！梅一眼就從人群中發現了閃閃發亮的維多利亞大人！",
  ui_story_5084_50841201_55_dialog_content = "遠遠看到，我還真不敢相信是您呢。",
  ui_story_5084_50841201_56_dialog_content = "現在呢？",
  ui_story_5084_50841201_57_dialog_content = "是維多利亞大人！比從前更美麗了！",
  ui_story_5084_50841201_58_dialog_content = "維多利亞大人，看來一切都進展得很順利。恭喜您。",
  ui_story_5084_50841201_59_dialog_content = "聖釘也有了巨大的變化。",
  ui_story_5084_50841201_60_dialog_content = "許久未見，維多利亞大人！這一切都是導師的功勞。",
  ui_story_5084_50841201_61_dialog_content = "我、我有好多話想對您說！",
  ui_story_5084_50841201_62_dialog_content = "嗯，我在街上看過你。之後我很樂意聽聽你的感悟。",
  ui_story_5084_50841201_63_dialog_content = "時間差不多了。",
  ui_story_5084_50841201_64_dialog_content = "但是維多利亞大人，我們剛剛看到死徒傷人。",
  ui_story_5084_50841201_65_dialog_content = "我現在知道瓦拉吉鎮流傳的黑騎傳說是怎麼來的了。",
  ui_story_5084_50841201_66_dialog_content = "走吧，威廉會確保街上的信徒們平安無事。",
  ui_story_5084_50841201_67_dialog_content = "真理結社需要在今晚展現力量。隨我一起去教堂吧。",
  ui_story_5084_50841201_68_dialog_content = "嗯！",
  ui_story_5084_50841201_69_dialog_content = "願真理，永遠祝福真理結社。",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_5084_50841201_71_dialog_content = "這些人……",
  ui_story_5084_50841201_72_dialog_content = "全部倒在地上，好像……",
  ui_story_5084_50841201_73_dialog_content = "……",
  ui_story_5084_50841201_74_dialog_content = "維多利亞大人，這些信徒都斷氣了。",
  ui_story_5084_50841201_75_dialog_content = "......！",
  ui_story_5084_50841201_76_dialog_content = "讓我試著拯救他們……我願意替他們承受痛苦。",
  ui_story_5084_50841201_77_dialog_content = "喔？瓦拉吉的家主和她的走狗終於來了。",
  ui_story_5084_50841201_78_dialog_content = "這是屬於真理結社的盛會，我怎麼可能缺席呢。",
  ui_story_5084_50841201_79_dialog_content = "維多利亞……小姐……我……",
  ui_story_5084_50841201_80_dialog_content = "……",
  ui_story_5084_50841201_81_dialog_content = "克萊維斯的身上有許多傷口……",
  ui_story_5084_50841201_82_dialog_content = "這就是背叛我的下場。",
  ui_story_5084_50841201_83_dialog_content = "都可以……都沒關係……只求妳不要傷害卡戎和夫人……",
  ui_story_5084_50841201_84_dialog_content = "在真理殿堂傷人——",
  ui_story_5084_50841201_85_dialog_content = "站住別動，瓦拉吉！",
  ui_story_5084_50841201_86_dialog_content = "你——！",
  ui_story_5084_50841201_87_dialog_content = "梅，到我身後。",
  ui_story_5084_50841201_88_dialog_content = "血族的戒律想必妳都忘光了吧。就由亞伯拉罕來告訴妳，妳觸犯了什麼戒律。",
  ui_story_5084_50841201_89_dialog_content = "妳不該回來啊，維多利亞。",
  ui_story_5084_50841201_90_dialog_content = "如今就算妳來到我面前也沒用，儀式結束了。該獻祭給主的禮物都獻祭了。",
  ui_story_5084_50841201_91_dialog_content = "現在，我是在教育我的小鬼們不要浪費糧食。",
  ui_story_5084_50841201_92_dialog_content = "光靈是真理之主的饋贈，你認為他們是糧食？",
  ui_story_5084_50841201_93_dialog_content = "瓦拉吉家的小姐，妳深夜裡也一定會饑餓難耐，派下人四處為妳尋覓新鮮的血液吧？",
  ui_story_5084_50841201_94_dialog_content = "屬於我的那位獻祭者，我可是一滴也沒浪費。",
  ui_story_5084_50841201_95_dialog_content = "亞伯拉罕可不一樣了，不僅浪費糧食，還欺瞞了我，哈哈哈哈哈！",
  ui_story_5084_50841201_96_dialog_content = "——！",
  ui_story_5084_50841201_97_dialog_content = "啊——啊！住手啊，波菲里歐！住手……",
  ui_story_5084_50841201_98_dialog_content = "威廉在哪裡！",
  ui_story_5084_50841201_99_dialog_content = "戴維·波菲里歐，住手！",
  ui_story_5084_50841201_100_dialog_content = "這裡是妳說了算嗎？",
  ui_story_5084_50841201_101_dialog_content = "抬過來。",
  ui_story_5084_50841201_102_dialog_content = "遵命，維多利亞大人。",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>匡當——</color>",
  ui_story_5084_50841201_104_dialog_content = "藤蔓人，你在做什麼？",
  ui_story_5084_50841201_105_dialog_content = "在下只是按照瓦拉吉小姐的吩咐，將遊行的棺木送到波菲里歐大人面前。",
  ui_story_5084_50841201_106_dialog_content = "妳不會以為瓦拉吉先祖的遺骸能對我造成威脅吧？",
  ui_story_5084_50841201_107_dialog_content = "呵，又或是想用威廉·瓦拉吉過去那一招逃跑？",
  ui_story_5084_50841201_108_dialog_content = "棺內躺著的人，正是威廉。",
  ui_story_5084_50841201_109_dialog_content = "......？",
  ui_story_5084_50841201_110_dialog_content = "你們對他痛下殺手，還敢向我尋人？",
  ui_story_5084_50841201_111_dialog_content = "呵呵，我的耐心所剩無幾了。",
  ui_story_5084_50841201_112_dialog_content = "這瓶血喝完之後，我就只能從妳身上汲取養分了。",
  ui_story_5084_50841201_113_dialog_content = "來，靠過來點。告訴我，妳和威廉究竟在玩什麼把戲？",
  ui_story_5084_50841201_114_dialog_content = "威廉死了。",
  ui_story_5084_50841201_115_dialog_content = "妳撒謊！",
  ui_story_5084_50841201_116_dialog_content = "維多利亞，小心！",
  ui_story_5084_50841201_117_dialog_content = "休得靠近維多利亞大人！",
  ui_story_5084_50841201_118_dialog_content = "想自行籌建真理的人馬，這樣的場景並不新鮮。但像妳這些下人般護主心切的，當真少見。",
  ui_story_5084_50841201_119_dialog_content = "不過，別把我當傻瓜。我親眼看見你們叔姪殺害了蝰蛇和淘金鬼。",
  ui_story_5084_50841201_120_dialog_content = "怕了嗎？不只蝰蛇和淘金鬼，你們所有圖謀不軌的人，都會死在他的劍下。",
  ui_story_5084_50841201_121_dialog_content = "所以無論你們如何折磨、謀害、掩埋他，你們永遠殺不死威廉·瓦拉吉。",
  ui_story_5084_50841201_122_dialog_content = "威廉……沒死？他真的沒死？！",
  ui_story_5084_50841201_123_dialog_content = "……",
  ui_story_5084_50841201_124_dialog_content = "怎麼會沒死？難道瓦拉吉家族死後會變成鬼魂？",
  ui_story_5084_50841201_125_dialog_content = "這世上沒有鬼魂！這些死徒還是吸食了波菲里歐的力量才能變成的樣子。",
  ui_story_5084_50841201_126_dialog_content = "這是我波菲里歐所掌握的死徒之力，即使在血族歷史中也是獨一無二！",
  ui_story_5084_50841201_127_dialog_content = "至於死而復生的能力，別開玩笑了，絕無可能。",
  ui_story_5084_50841201_128_dialog_content = "難道你以為瓦拉吉所掌握的力量，僅有繼承先祖之力，或是用遺物預示未來嗎？",
  ui_story_5084_50841201_129_dialog_content = "......？",
  ui_story_5084_50841201_130_dialog_content = "就在剛才，我與邪典簽下了契約。我已獲得邪典認可，成為真理結社新一任的領袖。",
  ui_story_5084_50841201_131_dialog_content = "信徒跪拜，在虔誠的讚頌中回歸真理……",
  ui_story_5084_50841201_132_dialog_content = "我早就該明白，什麼非瓦拉吉血脈不可這種話，只是瓦拉吉獨攬權柄的話術罷了。",
  ui_story_5084_50841201_133_dialog_content = "我波菲里歐早該肩負此職責的殊榮，帶領真理結社重回真理之道。",
  ui_story_5084_50841201_134_dialog_content = "吸血鬼是血的主宰、夜的主宰，憑什麼屈尊於向光生長之徒的統治！",
  ui_story_5084_50841201_135_dialog_content = "我該接獲此殊榮，按照祖先選定的方式普渡眾生！邪典如此啟示我！",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>激烈的打鬥令人殺紅了眼，棺木猛然被打翻。</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>只見一本嶄新的邪典從棺木中飛出，恰好落在維多利亞的腳旁邊。</color>",
  ui_story_5084_50841301_3_dialog_content = "真理冀望完成救贖之道，它的意圖顯然是讓我代行。",
  ui_story_5084_50841301_4_dialog_content = "災典，具現！",
  ui_story_5084_50841301_5_dialog_content = "……",
  ui_story_5084_50841301_6_dialog_content = "那是什麼？",
  ui_story_5084_50841301_7_dialog_content = "預示未來的邪典令你能一窺未來景象，你卻無力把握，好似蹣跚學步的嬰兒。",
  ui_story_5084_50841301_8_dialog_content = "而這本經原始長流淘洗過的災典則明曉一切，亦無所不能。",
  ui_story_5084_50841301_9_dialog_content = "新的篇章昭然若揭，由我來翻開下一頁！",
  ui_story_5084_50841301_10_dialog_content = "想不想目睹災典揭示你何時生，何時死，何時下跪悔過？",
  ui_story_5084_50841301_11_dialog_content = "......！",
  ui_story_5084_50841301_12_dialog_content = "其餘與波菲里歐勾結的家主，聽清楚了。",
  ui_story_5084_50841301_13_dialog_content = "真理結社十二大家主之第三家主，波菲里歐。",
  ui_story_5084_50841301_14_dialog_content = "於血月之時嗜血成性，殺害大量信徒，飲其鮮血，更以傳家物「金煙斗」操縱死徒。",
  ui_story_5084_50841301_15_dialog_content = "其與真理結社廢黜的第十三家主勾結，引邪神進入瓦拉吉鎮，虐殺信徒。",
  ui_story_5084_50841301_16_dialog_content = "那名被廢黜的孩童……？",
  ui_story_5084_50841301_17_dialog_content = "第十三家主曾於暗面尋找真理之主降臨之地。",
  ui_story_5084_50841301_18_dialog_content = "引邪神入鎮，殺害信徒，破壞真理之主降臨儀式。",
  ui_story_5084_50841301_19_dialog_content = "戴維·波菲里歐為其屠鎮製造契機，飲下大量受傷信徒之血。",
  ui_story_5084_50841301_20_dialog_content = "犯下種種罪孽，還有擔當真理結社領袖、擔當大家主的資格嗎？",
  ui_story_5084_50841301_21_dialog_content = "……",
  ui_story_5084_50841301_22_dialog_content = "胡說八道！",
  ui_story_5084_50841301_23_dialog_content = "在<color=#FFB400>瓦拉吉之戒</color>的力量下，顯現你的<color=#FFB400>本質</color>吧！",
  ui_story_5084_50841301_24_dialog_content = "——！",
  ui_story_5084_50841301_25_dialog_content = "我以為和第十三家主勾結，飲下聖徒的鮮血能助我增長力量。",
  ui_story_5084_50841301_26_dialog_content = "其餘家主都獲得了真理之主的祝福，改食其他血漿。",
  ui_story_5084_50841301_27_dialog_content = "唯獨我對血液的渴望越來越大，到了需要這浮空血瓶才能勉強活下去的地步。",
  ui_story_5084_50841301_28_dialog_content = "你似乎還不明白。第十三家主從未認為這一切是與你的契約。",
  ui_story_5084_50841301_29_dialog_content = "殺你和殺萬物並無區別。第十三家主只是在利用你。",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>她</color>能加入日蝕，成為<color=#FFB400>罪靈</color>，你還自以為能揣測她的心思？",
  ui_story_5084_50841301_31_dialog_content = "住、住口！",
  ui_story_5084_50841301_32_dialog_content = "妳……維多利亞·瓦拉吉，竟然操控戒指來束縛我？",
  ui_story_5084_50841301_33_dialog_content = "不、不！從前的瓦拉吉之戒不是這樣的。",
  ui_story_5084_50841301_34_dialog_content = "我已駕馭戒指，與瓦拉吉先祖並行。",
  ui_story_5084_50841301_35_dialog_content = "此時此刻，你面對的是瓦拉吉一族的力量。在吾等面前承認罪孽吧！",
  ui_story_5084_50841301_36_dialog_content = "哈哈哈！哈哈哈哈哈！",
  ui_story_5084_50841301_37_dialog_content = "沒錯！我殺了威廉！",
  ui_story_5084_50841301_38_dialog_content = "但我是在替真理結社掃清真正的阻礙！",
  ui_story_5084_50841301_39_dialog_content = "區區一個心理扭曲、離群索居，坑害兄長的瓦拉吉次子，憑什麼擔任真理結社的領袖？",
  ui_story_5084_50841301_40_dialog_content = "威廉……沒有坑害任何人！",
  ui_story_5084_50841301_41_dialog_content = "輪不到你插嘴——",
  ui_story_5084_50841301_42_dialog_content = "——！",
  ui_story_5084_50841301_43_dialog_content = "邪典是瓦拉吉的聖物，能夠給予掌控者力量，讓我不再恐懼未來。",
  ui_story_5084_50841301_44_dialog_content = "即使我嗜血，殺人，但它認可我，為我提供力量。",
  ui_story_5084_50841301_45_dialog_content = "真理結社沒有人奈何得了我！",
  ui_story_5084_50841301_46_dialog_content = "血色邪典！請賜我肅清瓦拉吉的力量！",
  ui_story_5084_50841301_47_dialog_content = "……",
  ui_story_5084_50841301_48_dialog_content = "血色邪典！",
  ui_story_5084_50841301_49_dialog_content = "你自始至終都沒有理解，瓦拉吉家族為何能成為真理結社的領袖。",
  ui_story_5084_50841301_50_dialog_content = "瓦拉吉一族從來不曾仰仗邪典的力量傷人。",
  ui_story_5084_50841301_51_dialog_content = "正好相反，是邪典在汲取瓦拉吉的血液，藉以啟示未來。",
  ui_story_5084_50841301_52_dialog_content = "......？",
  ui_story_5084_50841301_53_dialog_content = "無論是先祖，還是我的父母親，亦或是威廉·瓦拉吉和我，無一例外。",
  ui_story_5084_50841301_54_dialog_content = "這些聖物殘留著歷代家主的意識。理性的意識、瘋狂的意識。",
  ui_story_5084_50841301_55_dialog_content = "契約者必須有強大的精神力，才能不受那些附著的囈語干擾，抵達真理之境。",
  ui_story_5084_50841301_56_dialog_content = "從更高的面向，解讀真理之主的啟示。",
  ui_story_5084_50841301_57_dialog_content = "妳……究竟獲得了什麼啟示？",
  ui_story_5084_50841301_58_dialog_content = "……",
  ui_story_5084_50841301_59_dialog_content = "別過來！妳、妳要做什麼？！",
  ui_story_5084_50841301_60_dialog_content = "你忘了嗎？上一次的家主會議。",
  ui_story_5084_50841301_61_dialog_content = "妳，獲得了怎樣的啟示？",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>肅清門派。</color>",
  ui_story_5084_50841301_63_dialog_content = "妳……！",
  ui_story_5084_50841301_64_dialog_content = "真理的信徒，與我一同誦念契語！",
  ui_story_5084_50841301_65_dialog_content = "聖釘將用生命誦念契語！",
  ui_story_5084_50841301_66_dialog_content = "梅和寶寶一同誦念契語！",
  ui_story_5084_50841301_67_dialog_content = "信徒浮士德，與維多利亞大人一同誦念契語！",
  ui_story_5084_50841301_68_dialog_content = "戴維，認輸吧。",
  ui_story_5084_50841301_69_dialog_content = "你也是膽小之輩嗎？真理結社必須由波菲里歐家主執掌！",
  ui_story_5084_50841301_70_dialog_content = "告辭。",
  ui_story_5084_50841301_71_dialog_content = "你們……明明答應過我！",
  ui_story_5084_50841301_72_dialog_content = "算了吧，我們的交易只到血月為止。我果然沒有押錯對象，哈哈。祝你常飲鮮血。",
  ui_story_5084_50841301_73_dialog_content = "小鬼們！",
  ui_story_5084_50841301_74_dialog_content = "真理結社的家主們，邀請你們一同見證——",
  ui_story_5084_50841301_75_dialog_content = "……",
  ui_story_5084_50841301_76_dialog_content = "所有流淌在信徒血脈裡的真理之靈，起身！",
  ui_story_5084_50841301_77_dialog_content = "與我一同聆聽真理！",
  ui_story_5084_50841301_78_dialog_content = "隨我起舞的長流漣漪，衝破虛空，凝聚於此。",
  ui_story_5084_50841301_79_dialog_content = "我即是真理之主手握的符文，在聖地等祂顯現。",
  ui_story_5084_50841301_80_dialog_content = "我是光之迎者，暗之奏者。永生之境，再啟死星。",
  ui_story_5084_50841301_81_dialog_content = "至聖的真理之主，請將啟示流淌過瓦拉吉之血脈，允我顯神國之力！",
  ui_story_5084_50841301_82_dialog_content = "「聖血」就要凝聚成形，我將傾聽受難者的懺悔！",
  ui_story_5084_50841301_83_dialog_content = "藤曼已然甦醒，真理之主請降臨在梅身上！",
  ui_story_5084_50841301_84_dialog_content = "這是真實的噩夢，朝我來吧！我將解放遠古的力量！",
  ui_story_5084_50841301_85_dialog_content = "連接原始河流的橋樑，洞穿宇宙真理的導航員，請助我們一臂之力！",
  ui_story_5084_50841301_86_dialog_content = "什麼連接橋樑？洞穿真理？",
  ui_story_5084_50841301_87_dialog_content = "我當然會幫助大家！",
  ui_story_5084_50841301_88_dialog_content = "祂會看到您的奉獻，契約已經完成，您將與我一同靜候神的降臨！",
  ui_story_5084_50841302_1_dialog_content = "同樣是嗜血的種族，骯髒的種族，從出生起便身負詛咒的種族……",
  ui_story_5084_50841302_2_dialog_content = "憑什麼你們瓦拉吉能一直大權獨攬？",
  ui_story_5084_50841302_3_dialog_content = "問出這問題的霎那，答案便已明擺在你面前。",
  ui_story_5084_50841302_4_dialog_content = "瓦拉吉……",
  ui_story_5084_50841302_5_dialog_content = "嗜血、長壽、詛咒。血之一族獲得力量的同時，也須付出某種代價。",
  ui_story_5084_50841302_6_dialog_content = "這樣的念頭，自我出生之時便跟隨著我，形塑著我。",
  ui_story_5084_50841302_7_dialog_content = "但近來我已領悟真理。我經歷的一切不是代價，而是我身為配得之人所獲得的餽贈和指引。",
  ui_story_5084_50841302_8_dialog_content = "真理之主欽選血之一族，贈予引領變革的力量，贈予開闢時代的機遇。",
  ui_story_5084_50841302_9_dialog_content = "暗鬼、舊文明的武器、邪神，任何一樣東西都足以挑戰光靈的存亡。",
  ui_story_5084_50841302_10_dialog_content = "更別說光靈本身也有眾多你這樣褻瀆主的邪惡之人。",
  ui_story_5084_50841302_11_dialog_content = "不曾走出瓦拉吉鎮去觀測水流、星象。",
  ui_story_5084_50841302_12_dialog_content = "不曾觀測在主眼中，艾歐里亞這顆受眷顧的孤星究竟如何運轉。",
  ui_story_5084_50841302_13_dialog_content = "你永遠不會明白，從歷史的角度看，孤星的覆滅早已發生不下千百回。",
  ui_story_5084_50841302_14_dialog_content = "光靈再次面臨傾覆之力時，唯有獲主欽選的瓦拉吉能夠阻止艾歐里亞毀滅。",
  ui_story_5084_50841302_15_dialog_content = "面對未知的恐懼時，能否用更強大的力量將其嚇退，是配得之人的基本條件。",
  ui_story_5084_50841302_16_dialog_content = "戴維·波菲里歐。你身為尊貴的血之一族，卻未曾領悟真理，理應交還主所贈予的力量。",
  ui_story_5084_50841302_17_dialog_content = "無關領悟和真理之主的選擇……血之一族只認瓦拉吉。",
  ui_story_5084_50841302_18_dialog_content = "波菲里歐本是瓦拉吉先祖的後裔。",
  ui_story_5084_50841302_19_dialog_content = "是瓦拉吉迫害我的前輩，褫奪他們尊名，連帶讓我不受認可。",
  ui_story_5084_50841302_20_dialog_content = "但幾百年過去了，血族一直如此，妳的領悟根本無從談起！",
  ui_story_5084_50841302_21_dialog_content = "無論是妳還是瓦拉吉，永遠都別想走出血之一族的宿命！",
  ui_story_5084_50841302_22_dialog_content = "哈哈哈，哈哈……哈……",
  ui_story_5084_50841302_23_dialog_content = "……",
  ui_story_5084_50841302_24_dialog_content = "瓦拉吉小姐……不，維多利亞大人。",
  ui_story_5084_50841302_25_dialog_content = "您在鎮外遊歷期間，真的獲得了主的啟示嗎？",
  ui_story_5084_50841302_26_dialog_content = "我們一族掌握著許多遠古遺物。",
  ui_story_5084_50841302_27_dialog_content = "要如何判斷是囈語對我的控制，以及自己是否配得真理之主賜予的力量？",
  ui_story_5084_50841302_28_dialog_content = "真理結社素來以血族的精神力見長，能與上古器物產生共鳴本身便是饋贈。",
  ui_story_5084_50841302_29_dialog_content = "但長期以來，眾家主間的權力鬥爭讓血脈摻雜了異志，還隨著遺物傳遞給後人。",
  ui_story_5084_50841302_30_dialog_content = "我在建立共鳴之後才知道，多數遺物裡除了催狂和痛苦的吶喊外，根本什麼也沒有。",
  ui_story_5084_50841302_31_dialog_content = "光靈與器物相互束縛的本質是畏懼。",
  ui_story_5084_50841302_32_dialog_content = "瓦拉吉傳人每一夜都因恐懼而躊躇著，導致這身衣服下的肉體和心靈傷痕累累。",
  ui_story_5084_50841302_33_dialog_content = "因此我不停搜尋典籍，就是為了用理性光靈的知識控制住它令我們瘋狂的本能。",
  ui_story_5084_50841302_34_dialog_content = "在此期間，我一層層撥開那囈語的迷霧，抵達真理之主的懷抱。",
  ui_story_5084_50841302_35_dialog_content = "持續叩問、探索，讓它們畏懼於我的力量而屈服。我想，這便是正途。",
  ui_story_5084_50841302_36_dialog_content = "謹遵維多利亞大人的教誨。",
  ui_story_5084_50841302_37_dialog_content = "但是我也要說，這並非血族的專利。",
  ui_story_5084_50841302_38_dialog_content = "遊歷在外時，我發現那些非血族的光靈，似乎也有吸引特殊器物的神祕力量。",
  ui_story_5084_50841302_39_dialog_content = "可能是一個輪子、一隻眼瞳。",
  ui_story_5084_50841302_40_dialog_content = "一枝樹藤、一片紙屑。",
  ui_story_5084_50841302_41_dialog_content = "一隻寵物，或是一口白箱。",
  ui_story_5084_50841302_42_dialog_content = "都因著不同的操縱者，釋放出強大的意識潛力。",
  ui_story_5084_50841302_43_dialog_content = "你們沒見過能夠凝聚成形，斬殺暗鬼的血液吧？",
  ui_story_5084_50841302_44_dialog_content = "我的門徒說曾在街頭見過這樣的信徒。",
  ui_story_5084_50841302_45_dialog_content = "……",
  ui_story_5084_50841302_46_dialog_content = "這樣的信徒遍佈整個世界。真理結社應該走進光靈中散播真理，將這些力量納入真理結社。",
  ui_story_5084_50841302_47_dialog_content = "獲得啟示之人早已現世，但他們還散落在世界各處，不知道那代表著什麼。",
  ui_story_5084_50841302_48_dialog_content = "我們血之一族必須凝聚這些啟示，共同向真理之主傳聲，邀祂降臨引領光靈的未來。",
  ui_story_5084_50841302_49_dialog_content = "如果是這樣，那我贊同離開瓦拉吉鎮，進入光靈之間散播真理。",
  ui_story_5084_50841302_50_dialog_content = "廣收門徒，凝聚力量。",
  ui_story_5084_50841302_51_dialog_content = "不過，我們要如何向真理之主傳聲？",
  ui_story_5084_50841302_52_dialog_content = "若我告訴你們，真理結社有一名導航員，能夠藉由連接聖物前往原始河流，甚至指揮這些聖物的力量……",
  ui_story_5084_50841302_53_dialog_content = "你們會期待未來的真理結社嗎？",
  ui_story_5084_50841302_54_dialog_content = "什麼導航員？",
  ui_story_5084_50841302_55_dialog_content = "喂，我沒說過要加入真理結社啊！",
  ui_story_5084_50841302_56_dialog_content = "空裔，請把燭台給我。",
  ui_story_5084_50841302_57_dialog_content = "啊？可是這裡有那麼多人……",
  ui_story_5084_50841302_58_dialog_content = "給我。",
  ui_story_5084_50841302_59_dialog_content = "……",
  ui_story_5084_50841302_60_dialog_content = "這位是空裔，真理結社的盟友。",
  ui_story_5084_50841302_61_dialog_content = "呃，大家好……",
  ui_story_5084_50841302_62_dialog_content = "空裔？我聽過。一支能夠駕駛巨像，擁有感應能力的種族。",
  ui_story_5084_50841302_63_dialog_content = "空裔大人，您從剛才就一直在場嗎？",
  ui_story_5084_50841302_64_dialog_content = "呃，準確來說，很多時候我都在，只是沒有出現而已。",
  ui_story_5084_50841302_65_dialog_content = "感應能力？跟血族的共鳴能力一樣嗎？",
  ui_story_5084_50841302_66_dialog_content = "不一樣。",
  ui_story_5084_50841302_67_dialog_content = "我說過，血族是透過血脈與聖物共鳴。",
  ui_story_5084_50841302_68_dialog_content = "空裔的感應，實質上是撬動血族上層的力量。而那上層力量，同樣是光靈能力的基礎。",
  ui_story_5084_50841302_69_dialog_content = "原始河流？",
  ui_story_5084_50841302_70_dialog_content = "天啊，維多利亞大人！難道……您取得了上古卷宗？",
  ui_story_5084_50841302_71_dialog_content = "沒有。上古卷宗至今無人獲得，下落無從知曉。",
  ui_story_5084_50841302_72_dialog_content = "但推動上古卷宗的原始河流，現在看來，確實有人去過。",
  ui_story_5084_50841302_73_dialog_content = "我會去尋找那個地方，所以在此拜託各位家主，未來的瓦拉吉鎮交給你們了。",
  ui_story_5084_50841302_74_dialog_content = "謹遵領袖的教誨。我們會好好領悟您傳遞的真理。",
  ui_story_5084_50841302_75_dialog_content = "真的……嗎？去過原始河流的人……",
  ui_story_5084_50841302_76_dialog_content = "克萊維斯·亞伯拉罕。你當時是在猶豫，是否要把殺死威廉的事告訴我吧？",
  ui_story_5084_50841302_77_dialog_content = "……",
  ui_story_5084_50841302_78_dialog_content = "克萊維斯，我來是想向你借一樣東西。",
  ui_story_5084_50841302_79_dialog_content = "黑盒法利亞？",
  ui_story_5084_50841302_80_dialog_content = "沒錯。",
  ui_story_5084_50841302_81_dialog_content = "你想拿走血色邪典？！",
  ui_story_5084_50841302_82_dialog_content = "血色邪典留在墓穴裡，遲早會落入吸血鬼手中。",
  ui_story_5084_50841302_83_dialog_content = "他……沒有資格拿走那東西。",
  ui_story_5084_50841302_84_dialog_content = "那是因為瓦拉吉的歷代領袖，在家主們心中留下了烙印。",
  ui_story_5084_50841302_85_dialog_content = "但如今維多利亞還沒意識到，她的血脈之中藏著何其重要的力量。",
  ui_story_5084_50841302_86_dialog_content = "再加上我的過去玷污了瓦拉吉，那一眾家主早對我的位置虎視眈眈。",
  ui_story_5084_50841302_87_dialog_content = "倘若有一天我不在了，家主們不會放過維多利亞。",
  ui_story_5084_50841302_88_dialog_content = "而由波菲里歐領導的真理結社，一定會為世界帶來龐大的災難。",
  ui_story_5084_50841302_89_dialog_content = "威廉，這件事情……",
  ui_story_5084_50841302_90_dialog_content = "只有當聖鳴節的血月照耀藤蔓之時，瓦拉吉墓穴才會為家主敞開大門。",
  ui_story_5084_50841302_91_dialog_content = "但那時一切就都來不及了。我們討論過萬門之鑰——黑盒法利亞的可能性。",
  ui_story_5084_50841302_92_dialog_content = "我兄長把法利亞放在你這裡的用意，或許正是讓身為摯友的你，在特定的時機交給我去拿走邪典。",
  ui_story_5084_50841302_93_dialog_content = "……",
  ui_story_5084_50841302_94_dialog_content = "克萊維斯，你為何陷入沉默？",
  ui_story_5084_50841302_95_dialog_content = "威廉，就算黑盒法利亞能夠打開墓穴，……不在眾家主的見證下拿走邪典，也會違反家主契約。",
  ui_story_5084_50841302_96_dialog_content = "我知道。",
  ui_story_5084_50841302_97_dialog_content = "明知道會違反家主契約，卻還是決定告訴我？威廉，你到底在想什麼？",
  ui_story_5084_50841302_98_dialog_content = "維多利亞今年幾歲了？",
  ui_story_5084_50841302_99_dialog_content = "為什麼問這個？",
  ui_story_5084_50841302_100_dialog_content = "你照顧維多利亞許多年了。你從曾經那個野心勃勃，眼裡只有自己的青年……",
  ui_story_5084_50841302_101_dialog_content = "變成一個會操心他人的長輩了。",
  ui_story_5084_50841302_102_dialog_content = "呵。要是你知道維多利亞平常是怎麼與我相處的，大概就不會說出這些話。",
  ui_story_5084_50841302_103_dialog_content = "你知道我為什麼要搬到舊鎮來住嗎？",
  ui_story_5084_50841302_104_dialog_content = "毫無疑問，為了卡戎。",
  ui_story_5084_50841302_105_dialog_content = "沒錯。威廉，我和卡戎的母親早已不想再關心真理結社的事務，更不會讓卡戎加入真理結社。",
  ui_story_5084_50841302_106_dialog_content = "你退縮了。",
  ui_story_5084_50841302_107_dialog_content = "不，威廉，正好相反。我為了卡戎，向前邁出了艱難的一步。",
  ui_story_5084_50841302_108_dialog_content = "如果我告訴你，要想避免卡戎和他母親的未來蒙上陰影，你就必須把黑盒法利亞交給我呢？",
  ui_story_5084_50841302_109_dialog_content = "……",
  ui_story_5084_50841302_110_dialog_content = "唯有讓瓦拉吉掌控邪典，真理結社才有出路。我繼承的諸多記憶中，唯有手執邪典的瓦拉吉能帶來變革！",
  ui_story_5084_50841302_111_dialog_content = "嗯。你似乎又變回了當時野心勃勃的樣子。",
  ui_story_5084_50841302_112_dialog_content = "難道那些試圖侵蝕你的瘋狂囈語，對你的懲罰還不夠嗎？",
  ui_story_5084_50841302_113_dialog_content = "沒錯，我是有野心！但那又能怎麼樣呢？！",
  ui_story_5084_50841302_114_dialog_content = "被才華出眾、力量強大的兄長給打敗，就該活在陰影中顧影自憐嗎？不！絕不！",
  ui_story_5084_50841302_115_dialog_content = "……",
  ui_story_5084_50841302_116_dialog_content = "……對不起，克萊維斯。那句話不是我的本意。",
  ui_story_5084_50841302_117_dialog_content = "我想說的是，這一次我不是為了自己，而是為了維多利亞。",
  ui_story_5084_50841302_118_dialog_content = "那也不成啊，威廉。",
  ui_story_5084_50841302_119_dialog_content = "你究竟在害怕什麼？克萊維斯，你難道看不出事情越來越不對勁了嗎？",
  ui_story_5084_50841302_120_dialog_content = "波菲里歐和那些家主們，從瓦拉吉血脈分化出去後，便不再遵循戒律了。",
  ui_story_5084_50841302_121_dialog_content = "只有你自己堅守的規則，到底有什麼意義？",
  ui_story_5084_50841302_122_dialog_content = "血族的戒律從來都是牢籠！現在的真理結社，無論於你、於我，於其他市民都是禍害。",
  ui_story_5084_50841302_123_dialog_content = "血之一族的本性如此。只不過你比我們幸運一點罷了。",
  ui_story_5084_50841302_124_dialog_content = "什麼時候開始，你也屈服命運了？",
  ui_story_5084_50841302_125_dialog_content = "不要這麼說，威廉，我只是不會否認事實而已。",
  ui_story_5084_50841302_126_dialog_content = "那把鑰匙，真的只會害了你。",
  ui_story_5084_50841302_127_dialog_content = "但你也不打算幫我，是嗎？",
  ui_story_5084_50841302_128_dialog_content = "……",
  ui_story_5084_50841302_129_dialog_content = "沒關係，克萊維斯，我會自己想辦法。",
  ui_story_5084_50841302_130_dialog_content = "我沒有把黑盒法利亞交給威廉。那個時候，我真的沒有想害他……",
  ui_story_5084_50841302_131_dialog_content = "我以為只要在聖鳴節當晚，看著威廉被家主們殺死，就可以……",
  ui_story_5084_50841302_132_dialog_content = "……",
  ui_story_5084_50841302_133_dialog_content = "<size=45>啊——！！！</size>",
  ui_story_5084_50841302_134_dialog_content = "哈哈哈……哈哈哈哈哈哈！",
  ui_story_5084_50841302_135_dialog_content = "克萊維斯……",
  ui_story_5084_50841302_136_dialog_content = "對不起，威廉……",
  ui_story_5084_50841302_137_dialog_content = "我必須給卡戎一個乾淨的未來。",
  ui_story_5084_50841302_138_dialog_content = "照顧過維多利亞的你，一定明白吧？",
  ui_story_5084_50841302_139_dialog_content = "維多利亞……",
  ui_story_5084_50841302_140_dialog_content = "呵……",
  ui_story_5084_50841302_141_dialog_content = "對不起！",
  ui_story_5084_50841302_142_dialog_content = "哈哈哈哈！克萊維斯，我還以為你不會開竅呢。",
  ui_story_5084_50841302_143_dialog_content = "威廉啊威廉，你以為用你那套唬人的戲法將她藏起來，能改變什麼嗎？",
  ui_story_5084_50841302_144_dialog_content = "噢，可憐的威廉，不受承認的威廉，就這樣死在故鄉。",
  ui_story_5084_50841302_145_dialog_content = "……",
  ui_story_5084_50841302_146_dialog_content = "哼，這枚瓦拉吉的戒指傳下去也毫無意義。",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>戴維·波菲里歐抖了抖身後的血罐子，往手指間注入此生最大的力氣。</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>他將瓦拉吉戒指碾碎。銀紅相間的粉末飛散，紛紛落在威廉身上。</color>",
  ui_story_5084_50841302_149_dialog_content = "你在做什麼？你把戒指碾碎了，以後不就——",
  ui_story_5084_50841302_150_dialog_content = "這枚戒指，對吾等毫無用處。就讓它的碎屑陪伴威廉的屍體長眠吧。",
  ui_story_5084_50841302_151_dialog_content = "從今往後，吾等再也不必提心吊膽了。",
  ui_story_5084_50841302_152_dialog_content = "名為瓦拉吉大家主的枷鎖，將從此成為歷史！",
  ui_story_5084_50841302_153_dialog_content = "哈哈哈哈！戴維，聖鳴節的晚餐還真是豐盛啊！",
  ui_story_5084_50841302_154_dialog_content = "你們……威廉他已經死了！",
  ui_story_5084_50841302_155_dialog_content = "沒錯，多虧了你的幫助。品嚐瓦拉吉的鮮血也要講究家主次序。",
  ui_story_5084_50841302_156_dialog_content = "我之後，當然是輪到我最親愛的朋友，克萊維斯。",
  ui_story_5084_50841302_157_dialog_content = "等我的小鬼吃飽喝足之後，威廉就歸你了。",
  ui_story_5084_50841302_158_dialog_content = "念在你們是昔日摯友的份上，你可以安葬他。",
  ui_story_5084_50841302_159_dialog_content = "死後睡進棺材，再怎麼說也是我們血之一族的傳統。",
  ui_story_5084_50841302_160_dialog_content = "不過可別忘了向他懺悔，說不定被摯友捅了一刀的他還聽得見呢。",
  ui_story_5084_50841302_161_dialog_content = "現在你可以放過卡戎和我太太了嗎？",
  ui_story_5084_50841302_162_dialog_content = "當然。不過克萊維斯，有件事我想不通。我的小鬼告訴我，最近你準備搬家，是嗎？",
  ui_story_5084_50841302_163_dialog_content = "……",
  ui_story_5084_50841302_164_dialog_content = "那樣的話，我以後想要拜託你幫忙的時候，不就不方便了嗎？",
  ui_story_5084_50841302_165_dialog_content = "戴維，你！",
  ui_story_5084_50841302_166_dialog_content = "哈哈哈哈！",
  ui_story_5084_50841302_167_dialog_content = "蠢貨。",
  ui_story_5084_50841302_168_dialog_content = "淘金鬼，你的人脈廣，別忘了替我找到維多利亞，斬草除根。",
  ui_story_5084_50841302_169_dialog_content = "我做了什麼……我都做了什麼？",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>克萊維斯背著死去的威廉，來到瓦拉吉墓穴。</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>然而，守墓的藤蔓人卻不願讓他將威廉安葬於此。</color>",
  ui_story_5084_50841302_172_dialog_content = "萬門之鑰！<color=#FFB400>黑盒法利亞</color>！",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>聖物現身，憑空撕出裂痕。克萊維斯跨入長流的縫隙，進入了墓穴。</color>",
  ui_story_5084_50841302_174_dialog_content = "威廉，這裡是瓦拉吉的墓穴。儘管這裡可能也不再安全，但我得盡快離開了。",
  ui_story_5084_50841302_175_dialog_content = "但願你能在此長眠，和你的祖先一起回到真理之主的懷抱。",
  ui_story_5084_50841302_176_dialog_content = "這把鑰匙在我身上就是個禍害。",
  ui_story_5084_50841302_177_dialog_content = "只要我還留著一天，就一定會被波菲里歐發現。",
  ui_story_5084_50841302_178_dialog_content = "若先祖看到這一切，請懲罰我，讓我用餘生經歷眾叛親離之苦吧。",
  ui_story_5084_50841302_179_dialog_content = "真理結社、瓦拉吉……我們努力過，但無法掌握它們的命運。",
  ui_story_5084_50841302_180_dialog_content = "威廉，血之一族啊。我們終究還是活成了命運的囚徒。",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>在沉默的守墓人見證下，克萊維斯將黑盒法利亞與威廉一同放入棺木。</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>誰也沒有察覺，萬門之鑰擅自打開了名為「命運」的門扉。</color>",
  ui_story_5084_50841302_183_dialog_content = "我不為自己辯解。這一切都是我應得的。",
  ui_story_5084_50841302_184_dialog_content = "克萊維斯先生，罪孽深重的您應該立刻向真理之主懺悔。",
  ui_story_5084_50841302_185_dialog_content = "我不求主的原諒。我已無顏面對威廉。",
  ui_story_5084_50841302_186_dialog_content = "……",
  ui_story_5084_50841302_187_dialog_content = "那個地方，除了你我之外沒人知道。而威廉已經死了。",
  ui_story_5084_50841302_188_dialog_content = "那一天，在我決定離開瓦拉吉鎮之前，你不是去找威廉，而是找我。",
  ui_story_5084_50841302_189_dialog_content = "若妳回鎮上，我會向妳坦白一切。若妳離開……",
  ui_story_5084_50841302_190_dialog_content = "你便什麼都不說。",
  ui_story_5084_50841302_191_dialog_content = "我每日每夜都在遭受折磨。",
  ui_story_5084_50841302_192_dialog_content = "你想取我性命，無論何時都可以，不過求你讓我完成最後一件事。",
  ui_story_5084_50841302_193_dialog_content = "……",
  ui_story_5084_50841302_194_dialog_content = "克萊維斯先生，您還能走嗎？",
  ui_story_5084_50841302_195_dialog_content = "卡戎和我太太與這一切無關，我一定要給他們一個乾淨的未來。",
  ui_story_5084_50841302_196_dialog_content = "但就算我活著，卡戎也一定會記恨我這個父親。",
  ui_story_5084_50841302_197_dialog_content = "未來又該如何呢？這就是對我的懲罰吧……",
  ui_story_5084_50841302_198_dialog_content = "我記得卡戎向我提過他的父親。他們的關係確實不好。",
  ui_story_5084_50841302_199_dialog_content = "……",
  ui_story_5084_50841302_200_dialog_content = "哎，維多利亞，蠟燭好像快熄滅了……",
  ui_story_5084_50841400_1_dialog_content = "維多利亞大人……這是萬門之鑰。",
  ui_story_5084_50841400_2_dialog_content = "克萊維斯家主當時將其葬於威廉大人身側，但如今威廉大人不知去向，在下只找到它。",
  ui_story_5084_50841400_3_dialog_content = "黑盒法利亞？這不是已經——",
  ui_story_5084_50841400_4_dialog_content = "PlayerName......",
  ui_story_5084_50841400_5_dialog_content = "噢，抱歉，忘了這件事不屬於這裡了。",
  ui_story_5084_50841400_6_dialog_content = "我知道您要離開了。我比須將它交給真理結社的領袖，維多利亞大人。",
  ui_story_5084_50841400_7_dialog_content = "不，它所帶來的影響任何人都無法掌握。就讓它留在這裡吧。",
  ui_story_5084_50841400_8_dialog_content = "你要確保誰也不能動它，即使是我也不行。一切必須遵循主的意志。",
  ui_story_5084_50841400_9_dialog_content = "維多利亞大人……請求您不要讓在下保管這麼重要的東西。",
  ui_story_5084_50841400_10_dialog_content = "它打從一開始就是歸你保管。當初我父親把它拿給克萊維斯，想來也是窺見了宿命的軌道。",
  ui_story_5084_50841400_11_dialog_content = "瓦拉吉的墓穴，在下不知道究竟能守護多久。",
  ui_story_5084_50841400_12_dialog_content = "如果可以，我想要退出家主之位，安心地做一根樹藤，潛心守衛墓穴，等待您的開啟。",
  ui_story_5084_50841400_13_dialog_content = "我可以用祕法讓眾家主看不見墓穴，但是你心中有堅信的真理嗎？",
  ui_story_5084_50841400_14_dialog_content = "真理……在下從一開始就只想遠離人世，這座墓穴恰好成了我的歸宿。",
  ui_story_5084_50841400_15_dialog_content = "這無關誰是真理結社的領袖。當然，我沒有質疑維多利亞大人的意思。",
  ui_story_5084_50841400_16_dialog_content = "你仍想堅守此處，不想獲得自由嗎？",
  ui_story_5084_50841400_17_dialog_content = "我的家人已全部遇害，天涯海角對我來說都一樣孤獨。",
  ui_story_5084_50841400_18_dialog_content = "那麼，我便賜予你在此尋求安寧的權利。",
  ui_story_5084_50841400_19_dialog_content = "你是瓦拉吉最忠實的朋友，有資格代替戴維·波菲里歐的位置，替遊歷在外的我照看瓦拉吉鎮。",
  ui_story_5084_50841400_20_dialog_content = "在下哪敢……？！",
  ui_story_5084_50841400_21_dialog_content = "但這就是你最想要的「歸宿」。你可以重新尋找家人，延續未來。",
  ui_story_5084_50841400_22_dialog_content = "我記得你們拋棄了與白夜城有關的過往，包括姓氏。",
  ui_story_5084_50841400_23_dialog_content = "來吧，選擇一個新的姓氏，這將成為你一族的嶄新起點。",
  ui_story_5084_50841400_24_dialog_content = "好吧……我明白了，大小姐。",
  ui_story_5084_50841400_25_dialog_content = "在下就叫……堂泰斯吧。",
  ui_story_5084_50841400_26_dialog_content = "從今以後，在下就叫格雷夫·堂泰斯。",
  ui_story_5084_50841400_27_dialog_content = "（「堂泰斯」？！他就是希卡蕾的祖先？）",
  ui_story_5084_50841400_28_dialog_content = "呵呵。既然你選擇了命運，那便如此吧。",
  ui_story_5084_50841400_29_dialog_content = "堂泰斯一族歷來都是瓦拉吉忠實的盟友，今後也不例外。黑盒法利亞將照耀你族的宿命。",
  ui_story_5084_50841400_30_dialog_content = "我明白了。那我先出去，不打擾您了。",
  ui_story_5084_50841400_31_dialog_content = "呼。一切都結束了呢。",
  ui_story_5084_50841400_32_dialog_content = "參加完這裡的聖鳴節，回到漩渦鎮之後，還有一個聖鳴節在等著我們。",
  ui_story_5084_50841400_33_dialog_content = "嗚，這不就要過三個聖鳴節了嗎！我突然有點想蓮了。",
  ui_story_5084_50841400_34_dialog_content = "咦？蠟燭這次好像真的要熄滅了。",
  ui_story_5084_50841400_35_dialog_content = "……",
  ui_story_5084_50841400_36_dialog_content = "（維多利亞看向遠處的神情，是在期待威廉嗎？）",
  ui_story_5084_50841400_37_dialog_content = "走吧。",
  ui_story_5084_50841400_38_dialog_content = "維多利亞大人，如今您有兩本邪典，您有打算帶走嗎？",
  ui_story_5084_50841400_39_dialog_content = "回去的路上，它們會回到該去的地方。各位，做好準備吧。",
  ui_story_5084_50841400_40_dialog_content = "熄滅了！咦？這本舊的邪典還在妳手上。",
  ui_story_5084_50841400_41_dialog_content = "邪典指引我們來到這裡，令我與嶄新的它相會。此時此刻，該是我把它歸還於命運的時候了。",
  ui_story_5084_50841400_42_dialog_content = "維多利亞？",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>在回歸的黑暗中，那時光洪流出現了一絲夾縫，隱約能窺見夾縫中一道奇異長流的投影。</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>於是維多利亞鬆手，那本伴她多年的邪典墜入奇異的長流之中，隨之流淌。</color>",
  ui_story_5084_50841400_45_dialog_content = "邪典去哪了……？",
  ui_story_5084_50841400_46_dialog_content = "噓，看這長流。所謂真理，自在其中。",
  ui_story_5084_50841400_47_dialog_content = "芸芸眾生，無非是這天河中一粒沉沙。我們終將回到真理之主的懷抱。",
  ui_story_5084_50841400_48_dialog_content = "去吧，願你邂逅所有的命運。",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>於是邪典順流而下，遠別了未來的陌生人。</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>在原始河流中，它靜靜漂流。水波搖曳，無數光影在邪典淌過的漣漪下浮現，顯現過去與未來。</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>邪典的書扉無風而敞，由它擾亂的一切，浮現於本無一字的白紙上。</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>於是，命運便逐一撰寫於紙——</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>邪典的身影現於那些故事之中，開始為人所知。河流之下的命運，它終於參與其中。</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>「威廉拾起不知從何而來的邪典，感受到啟示的存在，決定把它帶回去送給沉睡中的維多利亞。」</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>「年輕的維多利亞翻開無字的邪典，第一次聽見了真理的預言。」</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>邪典順流而下……繼續順流而下。時間在河流上無始亦無終，而是永無止境的環。</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>「於是維多利亞鬆手，那本伴她多年的邪典墜入奇異的長流之中，隨之流淌。」</color>",
  ui_story_5084_50841400_58_dialog_content = "所有的旅客都回到各自的時間，我也該收工了。",
  ui_story_5084_50841400_59_dialog_content = "一九一八年的維多利亞，妳還在探尋真理的路上。在懵懂的妳眼中，想必一切都無比深奧吧？",
  ui_story_5084_50841400_60_dialog_content = "沒關係，只要靜候時光流逝就行了。",
  ui_story_5084_50841400_61_dialog_content = "妳會和我一樣踏上漫長的旅途，然後蒙受啟示。",
  ui_story_5084_50841400_62_dialog_content = "到那個時候，妳將帶著他們回到這個時間，我們又會再次相見。",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>威廉將沉睡的維多利亞從漩渦鎮傳送至此，將舊邪典放在她的手中。</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>他則躺進自己來時的棺木，思及曾經的往事。</color>",
  ui_story_5084_50841400_65_dialog_content = "年幼的妳初次與我相見之時，竟是兄長因即將離世，而將妳託付於我。",
  ui_story_5084_50841400_66_dialog_content = "讓我成為領袖？",
  ui_story_5084_50841400_67_dialog_content = "沒錯，然後照顧維多利亞。",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>維多利亞靜靜站在父母身邊，不理解將死父母的臉上，為何會出現那副滿意的神情。</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>儘管威廉·瓦拉吉受盡屈辱，卻不忍心將心靈破碎的維多利亞引上血之一族的宿命之路。</color>",
  ui_story_5084_50841400_70_dialog_content = "別再浪費口舌了，我不願意。",
  ui_story_5084_50841400_71_dialog_content = "……",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>但葬禮當天，威廉還是披上信徒袍，目送兄長夫婦的棺木離開瓦拉吉鎮。</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>威廉在瓦拉吉墓穴的門口躊躇不前，聽著家主們對維多利亞的「問候」。</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>暴雨、雷電，那彷彿要撕碎世界的力量，從威廉的心底發出。</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>他直衝墓穴中心而去，只為在眾家主面前戴上那極有可能吞噬自己的瓦拉吉戒指。</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>只為保護那名將與他一同走向永恆真理之途的女孩。</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>兩人的相處並不輕鬆，但威廉必須逼迫此時抗拒真理結社的維多利亞變得強大。</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>而自己也在各處尋找能夠保全兩人的方式。</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>然後，他思及自己的死亡……</color>",
  ui_story_5084_50841400_80_dialog_content = "克萊維斯……",
  ui_story_5084_50841400_81_dialog_content = "照顧過維多利亞的你，一定明白吧？",
  ui_story_5084_50841400_82_dialog_content = "維多利亞……",
  ui_story_5084_50841400_83_dialog_content = "呵……",
  ui_story_5084_50841400_84_dialog_content = "（按照血族的傳統，死亡或許是一種祝福。）",
  ui_story_5084_50841400_85_dialog_content = "（如今的我，不會再因受到背叛而感到痛苦了。）",
  ui_story_5084_50841400_86_dialog_content = "（我明白你的苦衷。可是，維多利亞今後要怎麼辦？）",
  ui_story_5084_50841400_87_dialog_content = "（我真的已經把所知的真理都傳遞給她了嗎？）",
  ui_story_5084_50841400_88_dialog_content = "（她離開那天，是不是想告訴我，她已經堅定地走上了追尋真理的路？）",
  ui_story_5084_50841400_89_dialog_content = "（……）",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>威廉對真理的叩問不曾停歇，思緒緩緩匯入一條透亮的河流。</color>",
  ui_story_5084_50841400_91_dialog_content = "怎麼回事？我不是在教堂被……我應該死了才對。",
  ui_story_5084_50841400_92_dialog_content = "這裡究竟是哪裡？",
  ui_story_5084_50841400_93_dialog_content = "死者的國度？還是真理之主的殿堂？",
  ui_story_5084_50841400_94_dialog_content = "這條長河是……？",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>漂泊，無止盡地漂泊。漂泊的威廉一動也不動，卻吸收著全世界的種種訊息。</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>十年、百年，滄海一粟。</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>艾歐里亞暗下又亮，光靈與暗鬼的爭端經久不息。</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>只有他，還在不停地漂泊。</color>",
  ui_story_5084_50841400_99_dialog_content = "嘶……那是我？",
  ui_story_5084_50841400_100_dialog_content = "這不是她的意願，卻是她的命運。替我把這本嶄新的邪典放進棺木，她用得到的。",
  ui_story_5084_50841400_101_dialog_content = "遵命，威廉大人。",
  ui_story_5084_50841400_102_dialog_content = "還有那時……",
  ui_story_5084_50841400_103_dialog_content = "幹嘛垂頭喪氣的？你也成家不就行了。",
  ui_story_5084_50841400_104_dialog_content = "成家？養孩子？沒意思。",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>許多個威廉分散在各處，又彼此交匯重疊。一切皆混亂無序，直到他看見除了自己以外的存在。</color>",
  ui_story_5084_50841400_106_dialog_content = "這並非吾之功勞，而是真理之主的庇護。",
  ui_story_5084_50841400_107_dialog_content = "這裡是什麼地方啊？",
  ui_story_5084_50841400_108_dialog_content = "<color=#FFB400>原始河流</color>不歸時間掌管，不受空間約束，它和外界唯一的區別便是流動。",
  ui_story_5084_50841400_109_dialog_content = "再這樣下去，我們的生命也都不由自己掌管了是嗎？為什麼把我們帶來這裡？",
  ui_story_5084_50841400_110_dialog_content = "維多利亞？！",
  ui_story_5084_50841400_111_dialog_content = "哈哈哈哈哈！",
  ui_story_5084_50841400_112_dialog_content = "不愧是維多利亞·瓦拉吉，妳做到了啊！",
  ui_story_5084_50841400_113_dialog_content = "還有卡戎……",
  ui_story_5084_50841400_114_dialog_content = "克萊維斯，身為長輩的我們，終於都做到了啊！",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>結束回憶的威廉再次起身，卻不是在自己的棺木中。他望著眼前永無止境的原始河流，涉入其中。</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>被他擾亂的因果糾纏著他，將他帶往真理的確定點。</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>隨後。</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>維多利亞所扔下的邪典碰上了阻礙。那是一名躺在河流中的死者。</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>受人背叛，名為威廉的死者。在命運的門扉引導下，他於奇異的長流中甦醒過來。</color>",
  ui_story_5084_50841400_120_dialog_content = "……？！",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>那一刻，迷惘的威廉發現，血色邪典就擱在腳邊的河流裡。</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>猶如無聲的召喚，他翻開了那本空無一字的邪典。於是，他看見了。</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>「順流而下的邪典輕輕碰觸死去威廉的腳，那年輕的血族因戒指碎屑鎖住的一滴血而甦醒。」</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>「那一刻，迷惘的威廉發現，血色邪典就擱在腳旁的河流裡。」</color>",
  ui_story_5084_50841400_125_dialog_content = "啊！！！",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>「驚恐的威廉向後跌入河流，由他擾亂的河水將其打濕，一切因果皆沾染其身。」</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>「坐在河流中的威廉注意到，自己的手邊似乎多了什麼東西。他顫抖著拿起來細看。」</color>",
  ui_story_5084_50841400_128_dialog_content = "戒指……我們瓦拉吉家族的祖傳戒指？",
  ui_story_5084_50841400_129_dialog_content = "這一切……究竟是怎麼回事？",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>「蒙受召喚的威廉，必將踏上漂泊之路，成為真理的引路人。」</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>「當時機成熟，瓦拉吉墓穴將為維多利亞敞開。真理之僕威廉，必將為維多利亞引路。」</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>「於是威廉躺進自己來時的棺木，思及曾經的往事。」</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>「當他意識到使命已經達成，維多利亞羽翼漸豐，自己是否得以安息？」</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>「但當他觸碰那戒指，鎖在戒指中的瓦拉吉之血開始湧回全身……熟悉的感覺回歸，他陷入沉睡。」</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>「當威廉再次清醒，他將被引向命運的十字路口。」</color>",
  ui_story_5084_50841400_136_dialog_content = "這裡是……",
  ui_story_5084_50841400_137_dialog_content = "雖然維多利亞大人曾說，虔誠會為我指引方向……",
  ui_story_5084_50841400_138_dialog_content = "但我會犧牲……",
  ui_story_5084_50841400_139_dialog_content = "我會……",
  ui_story_5084_50841400_140_dialog_content = "……",
  ui_story_5084_50841400_141_dialog_content = "主？",
  ui_story_5084_50841400_142_dialog_content = "偉大的真理之主！",
  ui_story_5084_50841400_143_dialog_content = "你剛才說，維多利亞大人？",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>「時間在河流上無始亦無終，而是永無止境的環。」</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>「於是維多利亞鬆手，那本伴她多年的邪典墜入奇異的長流之中，隨之流淌……」</color>",
  ui_story_5084_50841400_146_dialog_content = "你們回來了。",
  ui_story_5084_50841400_147_dialog_content = "嗯？蠟燭不見了。",
  ui_story_5084_50841400_148_dialog_content = "那是屬於法利亞的力量。",
  ui_story_5084_50841400_149_dialog_content = "法利亞，關閉。",
  ui_story_5084_50841400_150_dialog_content = "（原來如此……星空墓穴就是當年的瓦拉吉墓穴。）",
  ui_story_5084_50841400_151_dialog_content = "萬門之鑰，我們又再次見面了。",
  ui_story_5084_50841400_152_dialog_content = "維多利亞小姐？",
  ui_story_5084_50841400_153_dialog_content = "呵呵，只是我的自言自語罷了，請別在意。",
  ui_story_5084_50841400_154_dialog_content = "……嗯。",
  ui_story_5084_50841400_155_dialog_content = "梅？",
  ui_story_5084_50841400_156_dialog_content = "蓮？妳怎麼來了？",
  ui_story_5084_50841400_157_dialog_content = "麵包烤好後，我發現妳不見了，就猜妳是跑來找希卡蕾小姐，沒想到維多利亞小姐和大家都在。",
  ui_story_5084_50841400_158_dialog_content = "等等，我好像聽到有吃的？",
  ui_story_5084_50841400_159_dialog_content = "暖呼呼的烤麵包、香醇的葡萄酒……這些聖鳴節餐點都是由蓮準備的唷！",
  ui_story_5084_50841400_160_dialog_content = "妳這麼一說，我確實餓了。",
  ui_story_5084_50841400_161_dialog_content = "希卡蕾小姐，您也會一同前往盛典，對嗎？",
  ui_story_5084_50841400_162_dialog_content = "嗯，既然維多利亞小姐邀請，我一定會去。",
  ui_story_5084_50841400_163_dialog_content = "時間差不多了，維多利亞大人。真理結社的成員們應該都到鎮上集合了。",
  ui_story_5084_50841400_164_dialog_content = "真理結社的大家都會來嗎？",
  ui_story_5084_50841400_165_dialog_content = "此前邀請您時，您還猶豫，現在充滿期待了嗎？",
  ui_story_5084_50841400_166_dialog_content = "雖然和真理結社的朋友們不常見面，但是被熟悉的夥伴圍繞的感覺還是很棒。",
  ui_story_5084_50841400_167_dialog_content = "歡迎各位來參加真理結社三年一度的盛大節日。",
  ui_story_5084_50841400_168_dialog_content = "三年過去了，我們對艾歐里亞的探索又近了一步，也向真理之主靠近了一步。",
  ui_story_5084_50841400_169_dialog_content = "除永恆的真理之主外，我們不論身世尊卑，不認一成不變的戒律。",
  ui_story_5084_50841400_170_dialog_content = "無論是秉承與生俱來的獨特性，還是不斷擺脫過去枷鎖，亦或是履行某種使命……",
  ui_story_5084_50841400_171_dialog_content = "因為持續的蛻變與領悟，我們在接近真理的路途上熠熠生輝。",
  ui_story_5084_50841400_172_dialog_content = "如今的真理結社，已確切地走在受真理祝福的正途之上。",
  ui_story_5084_50841400_173_dialog_content = "與真理結社關係密切的血之一族，在艾斯特拉大陸之外做好了準備。",
  ui_story_5084_50841400_174_dialog_content = "而我，也將帶領大家見證真理之主的降臨。",
  ui_story_5084_50841400_175_dialog_content = "暗潮危機之時，邪典啟示一個巨大變革即將到來。",
  ui_story_5084_50841400_176_dialog_content = "那時我所錨定的變革者，如今已經日漸成熟。",
  ui_story_5084_50841400_177_dialog_content = "鎖會在暗面顯現，鑰匙將由我帶往目的地，同真理之主一起重建神國。",
  ui_story_5084_50841400_178_dialog_content = "這會是一趟橫穿暗面，顛倒日夜的旅程。真理結社將以同盟者的身分，再次引導光靈度過危機。",
  ui_story_5084_50841400_179_dialog_content = "接下來，盡情享受盛典的美食吧。",
  ui_story_5084_50841400_180_dialog_content = "是祂許我殊榮，賜予各位真理滿溢的美食佳釀。",
  ui_story_5084_50841400_181_dialog_content = "也盡情交流你們全新的領悟吧。",
  ui_story_5084_50841400_182_dialog_content = "願真理祝福你們。",
  ui_story_5084_50841400_183_dialog_content = "願真理祝福你們！",
  ui_story_5084_50841400_184_dialog_content = "帕索洛，你幹嘛一直盯著浮士德看？他身上有什麼東西嗎？",
  ui_story_5084_50841400_185_dialog_content = "那個，浮士德先生。有關我死去父母「靈魂」的問題，希卡蕾姐姐說或許您會給我新的答案。",
  ui_story_5084_50841400_186_dialog_content = "要說「新的答案」，這個問題您可以詢問聖釘，他當是最近收穫最多的人了。",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>咕咚——</color>",
  ui_story_5084_50841400_188_dialog_content = "PlayerName，快幫我攔住獵石！",
  ui_story_5084_50841400_189_dialog_content = "啊！速度太快，朝聖釘那邊滾過去了！",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5084_50841400_191_dialog_content = "抱歉，聖釘先生！獵石沒有撞傷你吧？",
  ui_story_5084_50841400_192_dialog_content = "沒有，契法小姐。如果想讓我感受疼痛的話，您可以用荊棘用力刺我這裡。",
  ui_story_5084_50841400_193_dialog_content = "聖釘先生，你之前才說今晚絕對不會傷害自己！你……你換上了新的衣服？",
  ui_story_5084_50841400_194_dialog_content = "聖釘先生，有關「靈魂」的問題，浮士德先生說您能傳遞給我一些嶄新的體悟。",
  ui_story_5084_50841400_195_dialog_content = "喔，體悟……我的導師確實給了我一些。",
  ui_story_5084_50841400_196_dialog_content = "關於「靈魂」，我認為那是精神的凝結。或許只要精神在，人就永遠不會消失。",
  ui_story_5084_50841400_197_dialog_content = "是這樣嗎？那我能再看見那些逝去的人，對嗎？",
  ui_story_5084_50841400_198_dialog_content = "這個問題……或許維多利亞大人能為你解答。",
  ui_story_5084_50841400_199_dialog_content = "喲，許久不見，你渾身都是神聖的氣息呀。",
  ui_story_5084_50841400_200_dialog_content = "好久不見，特拉蒙先生。",
  ui_story_5084_50841400_201_dialog_content = "和維多利亞大人一起經歷了什麼嗎？",
  ui_story_5084_50841400_202_dialog_content = "這是我的榮幸。在這次旅行中，我遇到了一位重要的導師，他指引我獲得真理之主的聖化。",
  ui_story_5084_50841400_203_dialog_content = "沒想到苦修者還有開竅的一天。這位導師今天有來嗎？",
  ui_story_5084_50841400_204_dialog_content = "導師他……慚愧，我不知道……",
  ui_story_5084_50841400_205_dialog_content = "維多利亞大人，聖釘先生說「只要精神在，人就永遠不會消失」。",
  ui_story_5084_50841400_206_dialog_content = "我逝去的父母，一直都在我身邊，對嗎？",
  ui_story_5084_50841400_207_dialog_content = "光靈是因信仰之光的凝聚而誕生。我們的精神力量來自一條更高維度的河流。",
  ui_story_5084_50841400_208_dialog_content = "若你的父母逝去之後，有一些精神回到了那裡，你應該祝福他們。",
  ui_story_5084_50841400_209_dialog_content = "我應該祝福他們……",
  ui_story_5084_50841400_210_dialog_content = "謝謝維多利亞大人的解答，我再想一想。",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>看著日益壯大的真理結社，維多利亞深深感慨。</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>結社能有今天，是彼時的威廉與此時的自己，一起為過去的維多利亞掃清了前行的障礙。</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>而他們冥冥中受到的指引，或許又是來自過去或未來的誰，在時空的流轉中拼盡全力傳遞著。</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>維多利亞從命運的長河中看見無數同行者的身影，一點點化作繼續探索真理的勇氣。</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>這一切，會由那個漂泊在時間長河的人注視著。</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>河流變換，典籍記錄，此時的維多利亞卻無論如何也不想那麼快翻開嶄新的一頁。</color>",
  ui_story_5084_50841400_217_dialog_content = "那就是和我一樣崇尚隱修了？",
  ui_story_5084_50841400_218_dialog_content = "但是不來參加真理結社的盛會，這倒也能理解。確實是隱修者的作風。",
  ui_story_5084_50841400_219_dialog_content = "隱修者難道還有組織？",
  ui_story_5084_50841400_220_dialog_content = "倒也談不上組織，不過據說這支派系發源於一九一五年的瓦拉吉鎮，由一位神祕的信徒建立。",
  ui_story_5084_50841400_221_dialog_content = "維多利亞大人沒告訴過你們嗎？",
  ui_story_5084_50841400_222_dialog_content = "比起你們在光靈聚集的鎮上出沒，自稱隱修者的成員我也只偶爾在野外碰見過。",
  ui_story_5084_50841400_223_dialog_content = "你們……通常都做些什麼？",
  ui_story_5084_50841400_224_dialog_content = "尋找空曠的地方，或是探索隱祕的角落……",
  ui_story_5084_50841400_225_dialog_content = "然後呢？",
  ui_story_5084_50841400_226_dialog_content = "待在那裡，什麼也不想。",
  ui_story_5084_50841400_227_dialog_content = "說是隱修，其實只是不想看書學習吧。",
  ui_story_5084_50841400_228_dialog_content = "因為這世界上所有的書，那位隱修大師全都讀過了。",
  ui_story_5084_50841400_229_dialog_content = "但我怎麼覺得，那位隱修大師待在空曠處是無書可看，你們是有書卻不看……",
  ui_story_5084_50841400_230_dialog_content = "那他真是一位了不起的人物啊！請問他的尊姓大名？",
  ui_story_5084_50841400_231_dialog_content = "沒有人知道他的名字。但我見過他。",
  ui_story_5084_50841400_232_dialog_content = "清瘦挺拔，偶爾透露出古舊的貴族氣息……",
  ui_story_5084_50841400_233_dialog_content = "因為他常常戴一頂黑色禮帽，穿一件紅黑色的披風，牽著一匹黑色的馬。",
  ui_story_5084_50841400_234_dialog_content = "......？",
  ui_story_5084_50841400_235_dialog_content = "他行蹤隱祕，常常四處旅行，有人說他是在等一個時機和故人見面。",
  ui_story_5084_50841400_236_dialog_content = "真的是導師？！",
  ui_story_5084_50841400_237_dialog_content = "誰？",
  ui_story_5084_50841400_238_dialog_content = "他要去見的那位故人……",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>「一切結束以後，在這裡見」。他當時是這麼說的。</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>維多利亞依舊站在窗邊，目光穿透時間的流轉，凝視著那些追尋真理的身影。</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>他們如同夜空中的星辰，有的明亮閃爍，有的暫且黯淡，但每一顆都以自己的方式詮釋著真理的意義。</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>維多利亞深知，真理的探索者如同追著那遙遠的星光，需要心靈的眼睛才能洞察。</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>而他，只是這途中的引導者，引領著後繼者前行。</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>窗外的他輕聲嘆息，如今真理結社的每一個成員，都如同他的孩子。</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>他知道無論他們的道路在怎麼曲折，維多利亞都將在最黑暗的時刻為他們點亮一盞燈。</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>但也只有他知道，窗邊的維多利亞也是一名孤獨的探索者。</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>維多利亞閉上眼睛，讓心靈的聲音響徹夜空。</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>她知道，不論是隱修的冷清，還是結社的喧囂，都是通往真理的不同道路。</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>「真理，是一場永無止境的探索。」他低語道。</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>「而我，會在你們探索的旅途中，堅定地守望著你們，指引著你們。」</color>"
}
return config
